CREATE OR REPLACE FUNCTION public.admin_delete_rules_question(p_actor_user_id uuid, p_card_version_id uuid, p_question_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_app_admin(p_actor_user_id) then raise exception 'Forbidden'; end if;
  if not exists (
    select 1 from public.rules_card_versions
    where id=p_card_version_id and approved_at is null
  ) then raise exception 'Card version is missing or locked'; end if;
  if not exists (
    select 1 from public.rules_questions
    where id=p_question_id and card_version_id=p_card_version_id
  ) then raise exception 'Question not found'; end if;

  insert into public.rules_admin_events(actor_user_id,entity_type,entity_id,action,details)
  values(p_actor_user_id,'question',p_question_id,'deleted',jsonb_build_object('card_version_id',p_card_version_id));
  delete from public.rules_questions where id=p_question_id and card_version_id=p_card_version_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_save_rules_question(p_actor_user_id uuid, p_card_version_id uuid, p_question_id uuid, p_kind text, p_variant integer, p_prompt text, p_explanation text, p_illustration_prompt text, p_image_url text, p_image_alt text, p_allows_multiple boolean, p_editorial_status text, p_options jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_question_id uuid;
  v_option jsonb;
  v_option_count integer;
  v_correct_count integer;
  v_position integer;
begin
  if not public.is_app_admin(p_actor_user_id) then
    raise exception 'Forbidden';
  end if;
  if not exists (
    select 1 from public.rules_card_versions
    where id=p_card_version_id and approved_at is null
  ) then
    raise exception 'Card version is missing or locked';
  end if;
  if p_kind not in ('practice','official') or p_variant < 1 then
    raise exception 'Invalid question kind or variant';
  end if;
  if trim(coalesce(p_prompt,''))='' or trim(coalesce(p_explanation,''))=''
    or trim(coalesce(p_illustration_prompt,''))='' or trim(coalesce(p_image_alt,''))='' then
    raise exception 'Question content is incomplete';
  end if;
  if p_editorial_status not in ('draft','needs_review','approved') then
    raise exception 'Invalid editorial status';
  end if;
  if jsonb_typeof(p_options) <> 'array' then
    raise exception 'Options must be an array';
  end if;

  v_option_count := jsonb_array_length(p_options);
  select count(*) into v_correct_count
  from jsonb_array_elements(p_options) option_row
  where coalesce((option_row->>'is_correct')::boolean,false);
  if v_option_count not between 3 and 4 then
    raise exception 'A question must have 3 or 4 options';
  end if;
  if (not p_allows_multiple and v_correct_count <> 1)
    or (p_allows_multiple and v_correct_count < 1) then
    raise exception 'Invalid number of correct options';
  end if;
  if exists (
    select 1 from jsonb_array_elements(p_options) option_row
    where trim(coalesce(option_row->>'label',''))=''
      or trim(coalesce(option_row->>'explanation',''))=''
  ) then
    raise exception 'Every option needs a label and an explanation';
  end if;

  if p_question_id is null then
    insert into public.rules_questions(
      card_version_id,kind,variant,prompt,explanation,illustration_prompt,
      image_url,image_alt,allows_multiple,editorial_status
    ) values (
      p_card_version_id,p_kind,p_variant,trim(p_prompt),trim(p_explanation),
      trim(p_illustration_prompt),nullif(trim(coalesce(p_image_url,'')),''),
      trim(p_image_alt),p_allows_multiple,p_editorial_status
    ) returning id into v_question_id;
  else
    update public.rules_questions set
      kind=p_kind,variant=p_variant,prompt=trim(p_prompt),
      explanation=trim(p_explanation),illustration_prompt=trim(p_illustration_prompt),
      image_url=nullif(trim(coalesce(p_image_url,'')),''),image_alt=trim(p_image_alt),
      allows_multiple=p_allows_multiple,editorial_status=p_editorial_status
    where id=p_question_id and card_version_id=p_card_version_id
    returning id into v_question_id;
    if v_question_id is null then raise exception 'Question not found'; end if;
  end if;

  v_position := 0;
  for v_option in select value from jsonb_array_elements(p_options) loop
    v_position := v_position + 1;
    insert into public.rules_question_options(question_id,position,label,is_correct,explanation)
    values(
      v_question_id,v_position,trim(v_option->>'label'),
      coalesce((v_option->>'is_correct')::boolean,false),trim(v_option->>'explanation')
    )
    on conflict(question_id,position) do update set
      label=excluded.label,is_correct=excluded.is_correct,explanation=excluded.explanation;
  end loop;
  delete from public.rules_question_options
  where question_id=v_question_id and position > v_option_count;

  insert into public.rules_admin_events(actor_user_id,entity_type,entity_id,action,details)
  values(p_actor_user_id,'question',v_question_id,
    case when p_question_id is null then 'created' else 'updated' end,
    jsonb_build_object('card_version_id',p_card_version_id,'kind',p_kind,'variant',p_variant));
  return v_question_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.answer_rules_quiz_question_business(p_attempt_id uuid, p_question_id uuid, p_option_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_allows_multiple boolean; v_selected int; v_expected int;
begin
  if not exists(
    select 1 from rules_quiz_attempts a join rules_attempt_questions aq on aq.attempt_id=a.id
    where a.id=p_attempt_id and a.player_user_id=auth.uid() and a.status='in_progress'
      and public.can_access_rules_quiz(a.series_id,a.club_id,a.player_user_id)
      and aq.question_id=p_question_id and aq.shown_at is not null
  ) then raise exception 'Attempt unavailable'; end if;
  select allows_multiple into v_allows_multiple from rules_questions where id=p_question_id;
  select count(*) into v_selected from unnest(p_option_ids) x(id) join rules_question_options o on o.id=x.id and o.question_id=p_question_id;
  if v_selected<>cardinality(p_option_ids) or v_selected=0 or (not v_allows_multiple and v_selected<>1) then raise exception 'Invalid answer'; end if;
  update rules_attempt_questions set selected_option_ids=p_option_ids,answered_at=now() where attempt_id=p_attempt_id and question_id=p_question_id and answered_at is null;
end $function$

CREATE OR REPLACE FUNCTION public.can_create_message_thread(p_org_id uuid, p_thread_type text, p_group_id uuid, p_event_id uuid, p_player_id uuid, p_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_org_id is null or p_user_id is null then
    return false;
  end if;

  if p_thread_type = 'organization' then
    return public.is_org_manager_member(p_org_id, p_user_id)
      or exists (
        select 1
        from public.club_members cm
        where cm.club_id = p_org_id
          and cm.user_id = p_user_id
          and cm.is_active = true
          and cm.role = 'captain'
      );
  end if;

  if p_thread_type = 'group' then
    return p_group_id is not null
      and public.is_group_staff_member(p_group_id, p_user_id);
  end if;

  if p_thread_type = 'event' then
    return p_event_id is not null
      and exists (
        select 1
        from public.club_events e
        where e.id = p_event_id
          and e.club_id = p_org_id
          and (
            public.is_org_staff_member(p_org_id, p_user_id)
            or public.is_group_staff_member(e.group_id, p_user_id)
          )
      );
  end if;

  if p_thread_type = 'player' then
    return p_player_id is not null
      and public.is_org_staff_member(p_org_id, p_user_id)
      and exists (
        select 1
        from public.club_members cm
        where cm.club_id = p_org_id
          and cm.user_id = p_player_id
          and cm.is_active = true
          and cm.role = 'player'
      );
  end if;

  return false;
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_access_invitation_v1(p_token_hash text, p_consume boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare t public.access_invitation_tokens%rowtype; recipient uuid;
begin
  select * into t from public.access_invitation_tokens where token_hash = p_token_hash;
  if not found then return null; end if;
  perform 1 from public.profiles where id = t.user_id for update;
  select * into t from public.access_invitation_tokens where token_hash = p_token_hash for update;
  if t.consumed_at is not null or t.expires_at <= clock_timestamp() then return null; end if;
  recipient := coalesce(t.recipient_user_id, case when t.invitation_kind='account_recovery' then t.sent_by else t.user_id end);
  if t.invitation_kind <> 'account_recovery' and (not exists (select 1 from public.club_members where club_id=t.club_id and user_id=t.sent_by and role='manager' and is_active)
     and not exists (select 1 from public.app_admins where user_id=t.sent_by)) then return null; end if;
  if not exists (select 1 from auth.users where id=recipient and lower(trim(email))=lower(trim(t.sent_to_email)) and email not like '%@noemail.local') then return null; end if;
  if t.invitation_kind = 'parent_access' then
    if recipient <> t.user_id or not exists (select 1 from public.club_members where club_id=t.club_id and user_id=t.user_id and role='parent' and is_active) then return null; end if;
  else
    if not exists (select 1 from public.club_members where club_id=t.club_id and user_id=t.user_id and role='player' and is_active)
      or exists (select 1 from public.club_members where user_id=t.user_id and role in ('coach','manager'))
      or exists (select 1 from public.app_admins where user_id=t.user_id) then return null; end if;
    if recipient <> t.user_id and (
      not exists (select 1 from public.club_members where club_id=t.club_id and user_id=recipient and role='parent' and is_active)
      or not exists (select 1 from public.player_guardians where player_id=t.user_id and guardian_user_id=recipient and can_view and can_edit)
    ) then return null; end if;
  end if;
  if p_consume then
    -- Fail closed if the subsequent Auth request fails: issue a new invitation.
    update public.access_invitation_tokens set consumed_at=clock_timestamp() where user_id=t.user_id and consumed_at is null;
  end if;
  return jsonb_build_object('user_id',t.user_id,'sent_to_email',t.sent_to_email,'invitation_kind',t.invitation_kind);
end $function$

CREATE OR REPLACE FUNCTION public.claim_manager_news_email_v1(p_actor uuid, p_club uuid, p_news uuid, p_recipient uuid, p_email text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare n public.club_news%rowtype; d public.club_news_email_deliveries%rowtype;
begin
  perform public.require_manager_club_scope_v1(p_actor,p_club);
  select * into n from public.club_news where id=p_news and club_id=p_club for update;
  if not found then raise exception 'news_not_found' using errcode='P0002'; end if;
  -- Historical aggregate receipts cannot identify individual deliveries. Never replay them.
  if n.last_email_sent_at is not null and not exists(select 1 from public.club_news_email_deliveries where news_id=p_news) then
    return jsonb_build_object('status','legacy_sent');
  end if;
  if not exists(select 1 from public.club_members where club_id=p_club and user_id=p_recipient and is_active)
    or not exists(select 1 from auth.users where id=p_recipient and lower(trim(email))=lower(trim(p_email))) then
    raise exception 'recipient_no_longer_available' using errcode='42501';
  end if;
  select * into d from public.club_news_email_deliveries where news_id=p_news and recipient_user_id=p_recipient;
  if found and d.status <> 'failed' then return jsonb_build_object('status',d.status); end if;
  insert into public.club_news_email_deliveries(news_id,recipient_user_id,email,status)
    values(p_news,p_recipient,p_email,'sending')
    on conflict(news_id,recipient_user_id) do update set email=excluded.email,status='sending',attempt_id=gen_random_uuid(),last_error=null,updated_at=now()
    returning * into d;
  return jsonb_build_object('status','claimed','attempt_id',d.attempt_id);
end $function$

CREATE OR REPLACE FUNCTION public.coach_group_delete_keep_history_business(p_group_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_head uuid;
  v_club_id uuid;
  v_can_delete boolean := false;
  v_group_name text;
  v_archived_name text;
begin
  if p_group_id is null then
    raise exception 'Missing group id';
  end if;

  select g.head_coach_user_id, g.club_id, g.name
  into v_head, v_club_id, v_group_name
  from public.coach_groups g
  where g.id = p_group_id;

  if v_head is null or v_club_id is null then
    raise exception 'Group not found';
  end if;

  select exists (
    select 1
    from public.club_members cm
    where cm.club_id = v_club_id
      and cm.user_id = v_uid
      and cm.is_active = true
      and cm.role = 'manager'
  )
  into v_can_delete;

  if not v_can_delete then
    raise exception 'Only a manager can delete this group';
  end if;

  insert into public.club_event_coaches (event_id, coach_id)
  select
    e.id as event_id,
    c.coach_user_id as coach_id
  from public.club_events e
  join public.coach_group_coaches c
    on c.group_id = p_group_id
  where e.group_id = p_group_id
    and e.starts_at < now()
    and not exists (
      select 1
      from public.club_event_coaches ec
      where ec.event_id = e.id
        and ec.coach_id = c.coach_user_id
    );

  delete from public.message_threads t
  using public.club_events e
  where t.event_id = e.id
    and e.group_id = p_group_id
    and e.starts_at >= now();

  delete from public.club_events e
  where e.group_id = p_group_id
    and e.starts_at >= now();

  delete from public.message_threads
  where group_id = p_group_id;

  delete from public.coach_group_categories where group_id = p_group_id;
  delete from public.coach_group_players where group_id = p_group_id;
  delete from public.coach_group_coaches where group_id = p_group_id;

  v_archived_name := '__ARCHIVE_DELETED__ ' || coalesce(nullif(trim(v_group_name), ''), 'Groupe') || ' [' || p_group_id::text || ']';

  update public.coach_groups
  set
    name = v_archived_name,
    is_active = false
  where id = p_group_id;

  if exists (
    select 1
    from information_schema.columns c
    where c.table_schema = 'public'
      and c.table_name = 'club_event_series'
      and c.column_name = 'group_id'
  ) then
    execute 'delete from public.club_event_series where group_id = $1'
    using p_group_id;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.coach_transfer_player_group(p_actor_user_id uuid, p_player_user_id uuid, p_source_group_id uuid, p_destination_group_id uuid, p_future_events_action text DEFAULT 'keep'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_club_id uuid;
  v_source_club_id uuid;
  v_transfer_id uuid;
begin
  if p_future_events_action not in ('keep', 'remove_old', 'move') then
    raise exception 'Invalid future events action';
  end if;
  if p_source_group_id = p_destination_group_id then
    raise exception 'Source and destination groups must differ';
  end if;

  select club_id into v_club_id from public.coach_groups where id = p_destination_group_id and is_active = true;
  select club_id into v_source_club_id from public.coach_groups where id = p_source_group_id;
  if v_club_id is null or v_source_club_id is distinct from v_club_id then
    raise exception 'Groups must belong to the same club';
  end if;
  if not exists (
    select 1 from public.club_members cm
    where cm.club_id = v_club_id and cm.user_id = p_actor_user_id and cm.role = 'coach'
      and cm.is_active = true and cm.can_transfer_players_between_club_groups = true
  ) then
    raise exception 'Forbidden';
  end if;
  if not exists (
    select 1 from public.club_members cm
    where cm.club_id = v_club_id and cm.user_id = p_player_user_id and cm.role = 'player' and cm.is_active = true
  ) then
    raise exception 'Player is not active in this club';
  end if;
  if not exists (
    select 1 from public.coach_group_players gp
    where gp.group_id = p_source_group_id and gp.player_user_id = p_player_user_id
  ) then
    raise exception 'Player is not in the source group';
  end if;

  insert into public.coach_group_players (group_id, player_user_id)
  select p_destination_group_id, p_player_user_id
  where not exists (
    select 1 from public.coach_group_players gp
    where gp.group_id = p_destination_group_id and gp.player_user_id = p_player_user_id
  );
  delete from public.coach_group_players
  where group_id = p_source_group_id and player_user_id = p_player_user_id;

  if p_future_events_action in ('remove_old', 'move') then
    delete from public.club_event_attendees attendee
    using public.club_events event
    where attendee.event_id = event.id and attendee.player_id = p_player_user_id
      and event.group_id = p_source_group_id and event.starts_at > now();
  end if;
  if p_future_events_action = 'move' then
    insert into public.club_event_attendees (event_id, player_id, status)
    select event.id, p_player_user_id, 'expected'
    from public.club_events event
    where event.group_id = p_destination_group_id and event.starts_at > now() and event.status = 'scheduled'
      and not exists (
        select 1 from public.club_event_attendees attendee
        where attendee.event_id = event.id and attendee.player_id = p_player_user_id
      );
  end if;

  insert into public.coach_player_group_transfers (
    club_id, player_user_id, source_group_id, destination_group_id, performed_by, future_events_action
  ) values (
    v_club_id, p_player_user_id, p_source_group_id, p_destination_group_id, p_actor_user_id, p_future_events_action
  ) returning id into v_transfer_id;
  return v_transfer_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.copy_manager_event_structure_v1_business(p_event_id uuid, p_expected jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  source public.club_events%rowtype;
  series public.club_event_series%rowtype;
  expected_targets jsonb;
  actual_targets jsonb;
  target_ids uuid[];
  source_structure jsonb;
  target_id uuid;
  item jsonb;
  source_series uuid;
begin
  select * into source from public.club_events where id=p_event_id;
  if not found then raise exception 'event_not_found' using errcode='P0002'; end if;
  perform public.require_manager_club_scope_v1(auth.uid(),source.club_id);
  if source.series_id is null then raise exception 'series_not_found' using errcode='P0002'; end if;
  source_series := source.series_id;
  select * into series from public.club_event_series where id=source_series for update;
  if not found or series.club_id is distinct from source.club_id or series.group_id is distinct from source.group_id then
    raise exception 'forbidden' using errcode='42501';
  end if;
  -- Follow the series editor lock order. Individual saves also lock their event.
  perform 1 from public.club_events where series_id=source_series or id=p_event_id order by starts_at,id for update;
  select * into source from public.club_events where id=p_event_id;
  if source.series_id is distinct from source_series or source.club_id is distinct from series.club_id
    or source.group_id is distinct from series.group_id then raise exception 'planning_conflict' using errcode='PT409'; end if;
  if source.event_type not in ('training','camp') then raise exception 'invalid_structure' using errcode='22023'; end if;
  if p_expected is null or jsonb_typeof(p_expected->'future') is distinct from 'array'
    or public.manager_event_snapshot_v1(source.id) is distinct from (p_expected-'series'-'future')
    or to_jsonb(series) is distinct from p_expected->'series' then
    raise exception 'planning_conflict' using errcode='PT409';
  end if;
  source_structure := p_expected->'structure';
  if jsonb_typeof(source_structure) is distinct from 'array' or jsonb_array_length(source_structure)=0
    or jsonb_array_length(source_structure)>100 then raise exception 'invalid_structure' using errcode='22023'; end if;

  select coalesce(array_agg(e.id order by e.starts_at,e.id),'{}') into target_ids
    from public.club_events e where e.series_id=source_series and e.starts_at>source.starts_at
      and e.starts_at>=now() and e.status='scheduled';
  -- A corrupted cross-club/other-type series must never widen the write scope.
  if exists(select 1 from public.club_events e where e.id=any(target_ids)
    and (e.club_id is distinct from source.club_id or e.group_id is distinct from source.group_id
      or e.event_type is distinct from source.event_type)) then raise exception 'forbidden' using errcode='42501'; end if;
  perform 1 from public.club_event_structure_items where event_id=source.id or event_id=any(target_ids) for update;
  -- Check again after acquiring structure locks to catch a concurrent direct edit.
  if public.manager_event_snapshot_v1(source.id) is distinct from (p_expected-'series'-'future') then
    raise exception 'planning_conflict' using errcode='PT409';
  end if;
  select coalesce(jsonb_agg(x order by (x->'event'->>'starts_at')::timestamptz,x->'event'->>'id'),'[]') into expected_targets
    from jsonb_array_elements(p_expected->'future') x
    where (x->'event'->>'starts_at')::timestamptz>source.starts_at
      and (x->'event'->>'starts_at')::timestamptz>=now() and x->'event'->>'status'='scheduled';
  select coalesce(jsonb_agg(public.manager_event_snapshot_v1(e.id) order by e.starts_at,e.id),'[]') into actual_targets
    from public.club_events e where e.id=any(target_ids);
  if actual_targets is distinct from expected_targets then raise exception 'planning_conflict' using errcode='PT409'; end if;

  -- Any insertion error rolls back every replacement, including earlier targets.
  delete from public.club_event_structure_items where event_id=any(target_ids);
  foreach target_id in array target_ids loop
    for item in select * from jsonb_array_elements(source_structure) loop
      insert into public.club_event_structure_items(event_id,category,minutes,note,position)
        values(target_id,item->>'category',(item->>'minutes')::integer,item->>'note',(item->>'position')::integer);
    end loop;
  end loop;
  return jsonb_build_object('copied',cardinality(target_ids));
end $function$

CREATE OR REPLACE FUNCTION public.create_coach_events_v1_business(p_request_id uuid, p_group_id uuid, p_mode text, p_template jsonb, p_coach_ids uuid[], p_player_ids uuid[], p_structure jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_group public.coach_groups%rowtype;
  v_request public.coach_event_creation_requests%rowtype;
  v_payload jsonb;
  v_type text := p_template->>'event_type';
  v_duration int := (p_template->>'duration_minutes')::int;
  v_start timestamptz;
  v_end timestamptz;
  v_start_date date;
  v_end_date date;
  v_weekday int;
  v_interval int;
  v_time time;
  v_day date;
  v_dates timestamptz[] := '{}';
  v_event_ids uuid[] := '{}';
  v_event_id uuid;
  v_series_id uuid;
  v_item jsonb;
  v_position int;
  v_result jsonb;
begin
  select * into v_group from public.coach_groups where id=p_group_id;
  if auth.uid() is null or v_group.id is null or not public.can_manage_assigned_group(p_group_id,auth.uid(),'planning')
    then raise exception 'forbidden'; end if;
  if p_request_id is null then raise exception 'invalid_request'; end if;
  v_payload := jsonb_build_object('group_id',p_group_id,'mode',p_mode,'template',p_template,
    'coach_ids',to_jsonb(p_coach_ids),'player_ids',to_jsonb(p_player_ids),'structure',p_structure);
  -- A concurrent/retried call waits here and then receives exactly the same IDs.
  insert into public.coach_event_creation_requests(actor_id,request_id,group_id,payload)
    values(auth.uid(),p_request_id,p_group_id,v_payload) on conflict(actor_id,request_id) do nothing;
  select * into v_request from public.coach_event_creation_requests
    where actor_id=auth.uid() and request_id=p_request_id for update;
  if v_request.payload is distinct from v_payload then raise exception 'creation_request_conflict'; end if;
  if v_request.result is not null then return v_request.result || jsonb_build_object('replayed',true); end if;

  if p_mode is null or p_mode not in ('single','series') or v_type is null
    or v_type not in ('training','interclub','camp','session','event') or v_duration is null
    or v_duration not between 1 and 300 then raise exception 'invalid_event'; end if;
  if v_type in ('camp','session','event') and nullif(btrim(p_template->>'title'),'') is null then raise exception 'title_required'; end if;
  if length(coalesce(p_template->>'title',''))>500 or length(coalesce(p_template->>'location_text',''))>2000
    or length(coalesce(p_template->>'coach_note',''))>10000 then raise exception 'invalid_event'; end if;
  if p_coach_ids is null or p_player_ids is null or cardinality(p_coach_ids)>500 or cardinality(p_player_ids)>2000
    or jsonb_typeof(p_structure) is distinct from 'array' or jsonb_array_length(p_structure)>100 then raise exception 'invalid_assignments'; end if;
  if exists(select 1 from unnest(p_coach_ids) u(id) where not exists(select 1 from public.club_members m
      where m.club_id=v_group.club_id and m.user_id=u.id and m.is_active and m.role in ('coach','manager')))
    or exists(select 1 from unnest(p_player_ids) u(id) where not exists(select 1 from public.club_members m
      where m.club_id=v_group.club_id and m.user_id=u.id and m.is_active)) then raise exception 'invalid_assignments'; end if;
  for v_item in select * from jsonb_array_elements(p_structure) loop
    if v_item->>'category' is null or v_item->>'category' not in
      ('warmup_mobility','long_game','short_game_all','putting','wedging','pitching','chipping','bunker','course','mental','fitness','other')
      or (v_item->>'minutes')::int is null or (v_item->>'minutes')::int not between 1 and 300
      or length(coalesce(v_item->>'note',''))>10000 then raise exception 'invalid_structure'; end if;
  end loop;
  if p_mode='single' then
    v_start := (p_template->>'starts_at')::timestamptz;
    v_end := (p_template->>'ends_at')::timestamptz;
    if v_start is null or v_end is null or v_end<=v_start
      or v_duration<>least(300,round(extract(epoch from (v_end-v_start))/60)::int) then raise exception 'invalid_event'; end if;
    v_dates := array[v_start];
  else
    v_start_date := (p_template->>'start_date')::date;
    v_end_date := (p_template->>'end_date')::date;
    v_weekday := (p_template->>'weekday')::int;
    v_interval := (p_template->>'interval_weeks')::int;
    v_time := (p_template->>'time_of_day')::time;
    if v_start_date is null or v_end_date is null or v_end_date<v_start_date or v_end_date-v_start_date>1827
      or v_weekday is null or v_weekday not between 0 and 6 or v_interval is null or v_interval not between 1 and 52
      or v_time is null then raise exception 'invalid_recurrence'; end if;
    v_day := v_start_date + ((v_weekday-extract(dow from v_start_date)::int+7)%7);
    while v_day<=v_end_date loop
      v_start := (v_day+v_time) at time zone 'Europe/Zurich';
      -- Reject nonexistent local times during the spring DST jump.
      if (v_start at time zone 'Europe/Zurich') <> (v_day+v_time) then raise exception 'invalid_recurrence'; end if;
      v_dates := array_append(v_dates,v_start);
      if cardinality(v_dates)>80 then raise exception 'too_many_occurrences'; end if;
      v_day := v_day + v_interval*7;
    end loop;
    if cardinality(v_dates)=0 then raise exception 'no_occurrence'; end if;
    insert into public.club_event_series(group_id,club_id,event_type,title,location_text,coach_note,duration_minutes,
      weekday,time_of_day,interval_weeks,start_date,end_date,is_active,created_by)
      values(v_group.id,v_group.club_id,v_type,nullif(btrim(p_template->>'title'),''),nullif(btrim(p_template->>'location_text'),''),
        nullif(btrim(p_template->>'coach_note'),''),v_duration,v_weekday,v_time,v_interval,v_start_date,v_end_date,true,auth.uid())
      returning id into v_series_id;
  end if;
  foreach v_start in array v_dates loop
    if p_mode='series' then v_end := v_start + make_interval(mins=>v_duration); end if;
    insert into public.club_events(group_id,club_id,series_id,event_type,title,starts_at,ends_at,duration_minutes,location_text,coach_note,created_by)
      values(v_group.id,v_group.club_id,v_series_id,v_type,nullif(btrim(p_template->>'title'),''),v_start,v_end,v_duration,
        nullif(btrim(p_template->>'location_text'),''),nullif(btrim(p_template->>'coach_note'),''),auth.uid()) returning id into v_event_id;
    v_event_ids := array_append(v_event_ids,v_event_id);
    insert into public.club_event_coaches(event_id,coach_id) select v_event_id,id from (select distinct unnest(p_coach_ids) id) u
      on conflict(event_id,coach_id) do nothing;
    insert into public.club_event_attendees(event_id,player_id,status) select v_event_id,id,'present' from (select distinct unnest(p_player_ids) id) u
      on conflict(event_id,player_id) do nothing;
    v_position := 0;
    for v_item in select * from jsonb_array_elements(p_structure) loop
      insert into public.club_event_structure_items(event_id,category,minutes,note,position)
        values(v_event_id,v_item->>'category',(v_item->>'minutes')::int,nullif(btrim(v_item->>'note'),''),v_position);
      v_position := v_position+1;
    end loop;
  end loop;
  v_result := jsonb_build_object('ok',true,'event_ids',to_jsonb(v_event_ids),'series_id',v_series_id,'replayed',false);
  update public.coach_event_creation_requests set result=v_result where actor_id=auth.uid() and request_id=p_request_id;
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_legal_document(p_key text, p_kind text, p_purpose text, p_scope text, p_club uuid, p_roles text[], p_action text, p_required boolean, p_actor uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare new_id uuid;
begin
  if not exists(select 1 from public.app_admins a where a.user_id=p_actor) then raise exception 'Platform admin required'; end if;
  if p_key !~ '^[a-z0-9_-]+$' or length(trim(coalesce(p_purpose,'')))=0
    or p_scope not in ('platform','club') or (p_scope='platform' and p_club is not null)
    or (p_scope='club' and p_club is null) or cardinality(p_roles)=0
    or exists(select 1 from unnest(p_roles) r where r not in ('player','parent','coach','manager','admin'))
  then raise exception 'Invalid document'; end if;
  if not ((p_kind='terms' and p_action='accept')
    or (p_kind='privacy' and p_action in ('acknowledge','read'))
    or (p_kind='parent_authorization' and p_action='authorize' and p_scope='club')
    or (p_kind='specific_consent' and p_action='consent')
    or (p_kind='junior_notice' and p_action in ('read','acknowledge'))) then raise exception 'Invalid document action'; end if;
  insert into public.legal_documents(document_key,kind,purpose_key,scope,club_id,audience_roles,action_kind,required,created_by)
  values(p_key,p_kind,p_purpose,p_scope,p_club,p_roles,p_action,p_required,p_actor) returning id into new_id;
  insert into public.legal_drafts(document_id,updated_by) values(new_id,p_actor);
  return new_id;
end $function$

CREATE OR REPLACE FUNCTION public.create_manager_activity_batch_v1_business(p_request_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_request public.manager_activity_creation_requests%rowtype; v_group public.coach_groups%rowtype;
  v_type text:=p_payload->>'eventType'; v_mode text:=p_payload->>'mode'; v_group_mode text:=p_payload->'groupTarget'->>'mode';
  v_player_mode text:=p_payload->'playerTarget'->>'mode'; v_coach_mode text:=p_payload->'coachTarget'->>'mode'; v_parent_mode text:=p_payload->'parentTarget'->>'mode';
  v_groups uuid[]; v_players uuid[]; v_coaches uuid[]; v_parents uuid[]; v_criteria uuid[]; v_clubs uuid[]:='{}';
  v_event_players uuid[]; v_event_coaches uuid[]; v_event_parents uuid[]; v_group_id uuid; v_club uuid; v_id uuid;
  v_template jsonb; v_created jsonb; v_event public.club_events%rowtype; v_events jsonb:='[]'; v_series int:=0;
  v_start timestamptz; v_end timestamptz; v_duration int:=(p_payload->>'durationMinutes')::int;
  v_competition boolean:=v_type='competition'; v_direct boolean; v_reminder jsonb:=p_payload->'reminder';
begin
  if auth.uid() is null then raise exception 'forbidden'; end if;
  if p_request_id is null or jsonb_typeof(p_payload) is distinct from 'object' then raise exception 'invalid_request'; end if;
  insert into public.manager_activity_creation_requests(actor_id,request_id,payload) values(auth.uid(),p_request_id,p_payload) on conflict do nothing;
  select * into v_request from public.manager_activity_creation_requests where actor_id=auth.uid() and request_id=p_request_id for update;
  if v_request.payload is distinct from p_payload then raise exception 'creation_request_conflict'; end if;
  if v_request.result is not null then
    for v_club in select value::uuid from jsonb_array_elements_text(v_request.result->'club_ids') loop
      perform public.require_manager_club_scope_v1(auth.uid(),v_club);
    end loop;
    return v_request.result||jsonb_build_object('replayed',true);
  end if;
  if v_type is null or v_type not in ('training','interclub','camp','session','event','competition') or v_mode is null or v_mode not in ('single','series')
    or v_group_mode is null or v_group_mode not in ('all','selected')
    or v_player_mode is null or v_player_mode not in ('none','all','selected')
    or v_coach_mode is null or v_coach_mode not in ('none','all','selected')
    or v_parent_mode is null or v_parent_mode not in ('none','all','selected') then raise exception 'invalid_event'; end if;
  select coalesce(array_agg(distinct value::uuid),'{}') into v_players from jsonb_array_elements_text(coalesce(p_payload->'playerTarget'->'ids','[]'));
  select coalesce(array_agg(distinct value::uuid),'{}') into v_coaches from jsonb_array_elements_text(coalesce(p_payload->'coachTarget'->'ids','[]'));
  select coalesce(array_agg(distinct value::uuid),'{}') into v_parents from jsonb_array_elements_text(coalesce(p_payload->'parentTarget'->'ids','[]'));
  select coalesce(array_agg(distinct value::uuid),'{}') into v_criteria from jsonb_array_elements_text(coalesce(p_payload->'evaluationCriterionIds','[]'));
  if cardinality(v_players)>2000 or cardinality(v_coaches)>500 or cardinality(v_parents)>2000 or cardinality(v_criteria)>3 then raise exception 'invalid_assignments'; end if;
  if v_competition then
    if v_mode<>'single' or v_player_mode<>'selected' or cardinality(v_players)=0 or cardinality(v_criteria)>0 then raise exception 'invalid_competition'; end if;
    perform public.manager_validate_competition_v1(p_payload,true);
    v_groups:='{}';
  elsif v_group_mode='all' then
    select coalesce(array_agg(g.id order by g.id),'{}') into v_groups from public.coach_groups g where g.is_active and g.club_season_id is not null
      and g.name is distinct from '__ARCHIVE_HISTORIQUE__' and exists(select 1 from public.club_members m where m.club_id=g.club_id and m.user_id=auth.uid() and m.role='manager' and m.is_active);
  else
    select coalesce(array_agg(distinct value::uuid),'{}') into v_groups from jsonb_array_elements_text(coalesce(p_payload->'groupTarget'->'ids','[]'));
  end if;
  if (v_type='training' or v_mode='series') and (v_duration is null or v_duration not between 1 and 300) then raise exception 'invalid_event'; end if;
  if cardinality(v_groups)>20 then raise exception 'too_many_groups'; end if;
  v_direct:=cardinality(v_groups)=0;
  if v_direct then
    if cardinality(v_players)=0 or (not v_competition and cardinality(v_coaches)=0) then raise exception 'invalid_assignments'; end if;
    select coalesce(array_agg(c.id),'{}') into v_clubs from public.clubs c
      where (not v_competition or c.id=(p_payload->>'competitionClubId')::uuid)
      and exists(select 1 from public.club_members m where m.club_id=c.id and m.user_id=auth.uid() and m.role='manager' and m.is_active)
      and not exists(select 1 from unnest(v_players) u(id) where not exists(select 1 from public.club_members m where m.club_id=c.id and m.user_id=u.id and m.role='player' and m.is_active))
      and not exists(select 1 from unnest(v_coaches) u(id) where not exists(select 1 from public.club_members m where m.club_id=c.id and m.user_id=u.id and m.role='coach' and m.is_active));
    if cardinality(v_clubs)<>1 then raise exception 'invalid_assignments'; end if;
    perform public.require_manager_club_scope_v1(auth.uid(),v_clubs[1]);
    insert into public.coach_groups(club_id,club_season_id,name,is_active,head_coach_user_id)
      values(v_clubs[1],null,case when v_competition then 'Compétition · '||btrim(p_payload->>'title') else 'Groupe spécifique' end,true,v_coaches[1]) returning id into v_group_id;
    insert into public.coach_group_players(group_id,player_user_id) select v_group_id,id from unnest(v_players) u(id);
    insert into public.coach_group_coaches(group_id,coach_user_id,is_head) select v_group_id,id,id=v_coaches[1] from unnest(v_coaches) u(id);
    v_groups:=array[v_group_id];
  end if;
  if exists(select 1 from unnest(v_players) u(id) where not exists(select 1 from public.coach_group_players gp join public.coach_groups g on g.id=gp.group_id join public.club_members m on m.club_id=g.club_id and m.user_id=gp.player_user_id and m.role='player' and m.is_active where gp.group_id=any(v_groups) and gp.player_user_id=u.id))
    or exists(select 1 from unnest(v_coaches) u(id) where not exists(select 1 from public.coach_groups g join public.club_members m on m.club_id=g.club_id and m.user_id=u.id and m.role='coach' and m.is_active where g.id=any(v_groups) and (g.head_coach_user_id=u.id or exists(select 1 from public.coach_group_coaches gc where gc.group_id=g.id and gc.coach_user_id=u.id))))
    or exists(select 1 from unnest(v_parents) u(id) where not exists(select 1 from public.coach_groups g join public.club_members m on m.club_id=g.club_id and m.user_id=u.id and m.role='parent' and m.is_active where g.id=any(v_groups))) then raise exception 'invalid_assignments'; end if;
  foreach v_group_id in array v_groups loop
    select * into v_group from public.coach_groups where id=v_group_id for share;
    if v_group.id is null or not coalesce(v_group.is_active,false) then raise exception 'invalid_assignments'; end if;
    perform public.require_manager_club_scope_v1(auth.uid(),v_group.club_id);
    if not v_direct and (v_group.club_season_id is null or v_group.name='__ARCHIVE_HISTORIQUE__') then raise exception 'invalid_assignments'; end if;
    v_clubs:=array_append(v_clubs,v_group.club_id);
    select coalesce(array_agg(distinct g.player_user_id),'{}') into v_event_players from public.coach_group_players g where g.group_id=v_group_id
      and (v_player_mode='all' or (v_player_mode='selected' and g.player_user_id=any(v_players)));
    select coalesce(array_agg(distinct m.user_id),'{}') into v_event_coaches from public.club_members m where m.club_id=v_group.club_id and m.role='coach' and m.is_active and (
      v_coach_mode='all' or ((v_coach_mode='none' or m.user_id=any(v_coaches)) and (m.user_id=v_group.head_coach_user_id or exists(select 1 from public.coach_group_coaches g where g.group_id=v_group_id and g.coach_user_id=m.user_id))));
    select coalesce(array_agg(distinct m.user_id),'{}') into v_event_parents from public.club_members m where m.club_id=v_group.club_id and m.role='parent' and m.is_active and (
      v_parent_mode='all' or (v_parent_mode='selected' and m.user_id=any(v_parents)) or ((v_parent_mode<>'none' or v_competition) and exists(select 1 from public.player_guardians g where g.guardian_user_id=m.user_id and g.player_id=any(v_event_players) and coalesce(g.can_view,true))));
    if exists(select 1 from unnest(v_event_players) u(id) where not exists(select 1 from public.club_members m where m.club_id=v_group.club_id and m.user_id=u.id and m.role='player' and m.is_active)) then raise exception 'invalid_assignments'; end if;
    if v_mode='single' then
      v_start:=(p_payload->>'startsAt')::timestamptz;
      v_end:=case when v_type='training' then v_start+make_interval(mins=>v_duration) else (p_payload->>'endsAt')::timestamptz end;
      if v_start is null or v_end is null or v_end<=v_start then raise exception 'invalid_event'; end if;
      v_duration:=least(300,round(extract(epoch from(v_end-v_start))/60)::int);
    end if;
    v_template:=jsonb_build_object('event_type',case when v_competition then 'event' else v_type end,'title',p_payload->>'title',
      'starts_at',v_start,'ends_at',v_end,'duration_minutes',v_duration,'location_text',p_payload->>'locationText','coach_note',p_payload->>'coachNote',
      'requires_evaluation',not v_competition and coalesce((p_payload->>'requiresEvaluation')::boolean,false),
      'weekday',p_payload->'series'->'weekday','time_of_day',p_payload->'series'->>'timeOfDay','interval_weeks',p_payload->'series'->'intervalWeeks',
      'start_date',p_payload->'series'->>'startDate','end_date',p_payload->'series'->>'endDate');
    v_created:=public.create_manager_events_v1(gen_random_uuid(),v_group_id,v_mode,v_template,v_event_coaches,
      case when v_competition then v_event_players else v_event_players||v_event_parents end,'[]',v_criteria);
    if v_created->>'series_id' is not null then v_series:=v_series+1; end if;
    for v_id in select value::uuid from jsonb_array_elements_text(v_created->'event_ids') loop
      if v_competition then
        update public.club_events set event_type='competition',requires_evaluation=false,competition_level=p_payload->>'competitionLevel',competition_category=p_payload->>'competitionCategory',
          external_registration_url=nullif(btrim(p_payload->>'externalRegistrationUrl'),''),competition_note=nullif(btrim(p_payload->>'competitionNote'),'') where id=v_id;
        update public.club_event_attendees set status='expected' where event_id=v_id;
        if coalesce((v_reminder->>'enabled')::boolean,false) then
          insert into public.club_event_reminders(event_id,scheduled_for,channel,message_template,status,created_by)
            values(v_id,(v_reminder->>'scheduledFor')::timestamptz,v_reminder->>'channel',btrim(v_reminder->>'messageTemplate'),'pending',auth.uid());
        end if;
      end if;
      select * into v_event from public.club_events where id=v_id;
      v_events:=v_events||jsonb_build_array(jsonb_build_object('id',v_id,'event_type',v_event.event_type,'title',v_event.title,'starts_at',v_event.starts_at,
        'ends_at',v_event.ends_at,'location_text',v_event.location_text,'recipient_ids',to_jsonb(v_event_players||v_event_parents)));
    end loop;
  end loop;
  select array_agg(distinct u.id) into v_clubs from unnest(v_clubs) u(id);
  v_created:=jsonb_build_object('ok',true,'replayed',false,'events',v_events,'createdEvents',jsonb_array_length(v_events),'createdSeries',v_series,'firstEventId',v_events->0->>'id','club_ids',to_jsonb(v_clubs));
  update public.manager_activity_creation_requests set result=v_created where actor_id=auth.uid() and request_id=p_request_id;
  return v_created;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_manager_events_v1_business(p_request_id uuid, p_group_id uuid, p_mode text, p_template jsonb, p_coach_ids uuid[], p_player_ids uuid[], p_structure jsonb, p_criterion_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_group public.coach_groups%rowtype;
  v_request public.manager_event_creation_requests%rowtype;
  v_payload jsonb;
  v_type text := p_template->>'event_type';
  v_duration int := (p_template->>'duration_minutes')::int;
  v_start timestamptz;
  v_end timestamptz;
  v_start_date date;
  v_end_date date;
  v_weekday int;
  v_interval int;
  v_time time;
  v_day date;
  v_dates timestamptz[] := '{}';
  v_event_ids uuid[] := '{}';
  v_event_id uuid;
  v_series_id uuid;
  v_item jsonb;
  v_position int;
  v_result jsonb;
begin
  select * into v_group from public.coach_groups where id=p_group_id;
  if v_group.id is null then raise exception 'forbidden'; end if;
  perform public.require_manager_club_scope_v1(auth.uid(),v_group.club_id);
  if jsonb_typeof(p_template) is distinct from 'object' then raise exception 'invalid_event'; end if;
  if p_criterion_ids is null or cardinality(p_criterion_ids)>3
    or (cardinality(p_criterion_ids)>0 and (v_type not in ('training','camp') or not coalesce((p_template->>'requires_evaluation')::boolean,false)))
    then raise exception 'invalid_criteria'; end if;
  if p_request_id is null then raise exception 'invalid_request'; end if;
  v_payload := jsonb_build_object('group_id',p_group_id,'mode',p_mode,'template',p_template,
    'coach_ids',to_jsonb(p_coach_ids),'player_ids',to_jsonb(p_player_ids),'structure',p_structure,'criterion_ids',to_jsonb(p_criterion_ids));
  -- A concurrent/retried call waits here and then receives exactly the same IDs.
  insert into public.manager_event_creation_requests(actor_id,request_id,group_id,payload)
    values(auth.uid(),p_request_id,p_group_id,v_payload) on conflict(actor_id,request_id) do nothing;
  select * into v_request from public.manager_event_creation_requests
    where actor_id=auth.uid() and request_id=p_request_id for update;
  if v_request.payload is distinct from v_payload then raise exception 'creation_request_conflict'; end if;
  if v_request.result is not null then return v_request.result || jsonb_build_object('replayed',true); end if;

  if p_mode is null or p_mode not in ('single','series') or v_type is null
    or v_type not in ('training','interclub','camp','session','event') or v_duration is null
    or v_duration not between 1 and 300 then raise exception 'invalid_event'; end if;
  if v_type in ('camp','session','event') and nullif(btrim(p_template->>'title'),'') is null then raise exception 'title_required'; end if;
  if length(coalesce(p_template->>'title',''))>500 or length(coalesce(p_template->>'location_text',''))>2000
    or length(coalesce(p_template->>'coach_note',''))>10000 then raise exception 'invalid_event'; end if;
  if p_coach_ids is null or p_player_ids is null or cardinality(p_coach_ids)>500 or cardinality(p_player_ids)>2000
    or jsonb_typeof(p_structure) is distinct from 'array' or jsonb_array_length(p_structure)>100 then raise exception 'invalid_assignments'; end if;
  if exists(select 1 from unnest(p_coach_ids) u(id) where not exists(select 1 from public.club_members m
      where m.club_id=v_group.club_id and m.user_id=u.id and m.is_active and m.role in ('coach','manager')))
    or exists(select 1 from unnest(p_player_ids) u(id) where not exists(select 1 from public.club_members m
      where m.club_id=v_group.club_id and m.user_id=u.id and m.is_active)) then raise exception 'invalid_assignments'; end if;
  for v_item in select * from jsonb_array_elements(p_structure) loop
    if v_item->>'category' is null or v_item->>'category' not in
      ('warmup_mobility','long_game','short_game_all','putting','wedging','pitching','chipping','bunker','course','mental','fitness','other')
      or (v_item->>'minutes')::int is null or (v_item->>'minutes')::int not between 1 and 300
      or length(coalesce(v_item->>'note',''))>10000 then raise exception 'invalid_structure'; end if;
  end loop;
  if p_mode='single' then
    v_start := (p_template->>'starts_at')::timestamptz;
    v_end := (p_template->>'ends_at')::timestamptz;
    if v_start is null or v_end is null or v_end<=v_start
      or v_duration<>least(300,round(extract(epoch from (v_end-v_start))/60)::int) then raise exception 'invalid_event'; end if;
    v_dates := array[v_start];
  else
    v_start_date := (p_template->>'start_date')::date;
    v_end_date := (p_template->>'end_date')::date;
    v_weekday := (p_template->>'weekday')::int;
    v_interval := (p_template->>'interval_weeks')::int;
    v_time := (p_template->>'time_of_day')::time;
    if v_start_date is null or v_end_date is null or v_end_date<v_start_date or v_end_date-v_start_date>1827
      or v_weekday is null or v_weekday not between 0 and 6 or v_interval is null or v_interval not between 1 and 52
      or v_time is null then raise exception 'invalid_recurrence'; end if;
    v_day := v_start_date + ((v_weekday-extract(dow from v_start_date)::int+7)%7);
    while v_day<=v_end_date loop
      v_start := (v_day+v_time) at time zone 'Europe/Zurich';
      -- Reject nonexistent local times during the spring DST jump.
      if (v_start at time zone 'Europe/Zurich') <> (v_day+v_time) then raise exception 'invalid_recurrence'; end if;
      v_dates := array_append(v_dates,v_start);
      if cardinality(v_dates)>80 then raise exception 'too_many_occurrences'; end if;
      v_day := v_day + v_interval*7;
    end loop;
    if cardinality(v_dates)=0 then raise exception 'no_occurrence'; end if;
    insert into public.club_event_series(group_id,club_id,event_type,title,location_text,coach_note,duration_minutes,
      weekday,time_of_day,interval_weeks,start_date,end_date,is_active,created_by)
      values(v_group.id,v_group.club_id,v_type,nullif(btrim(p_template->>'title'),''),nullif(btrim(p_template->>'location_text'),''),
        nullif(btrim(p_template->>'coach_note'),''),v_duration,v_weekday,v_time,v_interval,v_start_date,v_end_date,true,auth.uid())
      returning id into v_series_id;
  end if;
  foreach v_start in array v_dates loop
    if p_mode='series' then v_end := v_start + make_interval(mins=>v_duration); end if;
    insert into public.club_events(group_id,club_id,series_id,event_type,title,starts_at,ends_at,duration_minutes,location_text,coach_note,created_by,requires_evaluation)
      values(v_group.id,v_group.club_id,v_series_id,v_type,nullif(btrim(p_template->>'title'),''),v_start,v_end,v_duration,
        nullif(btrim(p_template->>'location_text'),''),nullif(btrim(p_template->>'coach_note'),''),auth.uid(),v_type in ('training','camp') and coalesce((p_template->>'requires_evaluation')::boolean,false)) returning id into v_event_id;
    v_event_ids := array_append(v_event_ids,v_event_id);
    insert into public.club_event_coaches(event_id,coach_id) select v_event_id,id from (select distinct unnest(p_coach_ids) id) u
      on conflict(event_id,coach_id) do nothing;
    insert into public.club_event_attendees(event_id,player_id,status) select v_event_id,id,'present' from (select distinct unnest(p_player_ids) id) u
      on conflict(event_id,player_id) do nothing;
    perform public.manager_sync_event_criteria_v1(v_event_id,p_criterion_ids);
    v_position := 0;
    for v_item in select * from jsonb_array_elements(p_structure) loop
      insert into public.club_event_structure_items(event_id,category,minutes,note,position)
        values(v_event_id,v_item->>'category',(v_item->>'minutes')::int,nullif(btrim(v_item->>'note'),''),v_position);
      v_position := v_position+1;
    end loop;
  end loop;
  v_result := jsonb_build_object('ok',true,'event_ids',to_jsonb(v_event_ids),'series_id',v_series_id,'replayed',false);
  update public.manager_event_creation_requests set result=v_result where actor_id=auth.uid() and request_id=p_request_id;
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_manager_season_v1(p_actor uuid, p_club uuid, p_values jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare season public.club_seasons%rowtype; source uuid; copied int;
begin
  perform public.require_manager_club_scope_v1(p_actor,p_club);
  -- Serializes both concurrent season creation and the current-season switch.
  perform 1 from public.clubs where id=p_club for update;
  if not found then raise exception 'club_not_found' using errcode='P0002'; end if;
  if nullif(btrim(p_values->>'name'),'') is null or (p_values->>'starts_on')::date is null
    or (p_values->>'ends_on')::date is null or (p_values->>'ends_on')::date<(p_values->>'starts_on')::date then
    raise exception 'invalid_season' using errcode='22023';
  end if;
  select id into source from public.club_seasons where club_id=p_club and ends_on<=(p_values->>'starts_on')::date order by ends_on desc,id limit 1;
  if coalesce((p_values->>'is_current')::boolean,false) then update public.club_seasons set is_current=false where club_id=p_club and is_current; end if;
  insert into public.club_seasons(club_id,name,starts_on,ends_on,is_current) values(p_club,btrim(p_values->>'name'),
    (p_values->>'starts_on')::date,(p_values->>'ends_on')::date,coalesce((p_values->>'is_current')::boolean,false)) returning * into season;
  -- The existing after-insert trigger copies groups and Coach season records.
  insert into public.club_player_season_records(club_season_id,club_member_id,course_label,group_id,registration_status,membership_status,playing_right_status)
    select season.id,r.club_member_id,r.course_label,case when r.registration_status='active' then g.id end,
      r.registration_status,r.membership_status,r.playing_right_status
    from public.club_player_season_records r left join public.coach_groups g on g.club_season_id=season.id and g.copied_from_group_id=r.group_id
    where r.club_season_id=source;
  get diagnostics copied=row_count;
  insert into public.club_player_season_field_values(club_player_season_record_id,field_id,value_json)
    select dest.id,v.field_id,v.value_json from public.club_player_season_field_values v
    join public.club_player_season_records src on src.id=v.club_player_season_record_id and src.club_season_id=source
    join public.club_player_season_records dest on dest.club_member_id=src.club_member_id and dest.club_season_id=season.id;
  return jsonb_build_object('season',to_jsonb(season),'copied_records',copied);
end $function$

CREATE OR REPLACE FUNCTION public.create_player_golf_rounds_transactional_business(p_player_id uuid, p_round_payload jsonb, p_round_dates timestamp with time zone[], p_holes jsonb DEFAULT '[]'::jsonb)
 RETURNS uuid[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_round_ids uuid[];
  v_tournament_group_id uuid := gen_random_uuid();
  v_expected_count integer;
  v_updated_count integer;
begin
  v_round_ids := public.create_player_golf_rounds_transactional_without_group_id(
    p_player_id,
    p_round_payload,
    p_round_dates,
    p_holes
  );

  v_expected_count := coalesce(array_length(v_round_ids, 1), 0);
  if v_expected_count = 0 then
    raise exception using errcode = 'P0001', message = 'ROUND_CREATION_FAILED';
  end if;

  update public.golf_rounds gr
  set tournament_group_id = v_tournament_group_id
  where gr.id = any(v_round_ids)
    and gr.user_id = p_player_id
    and gr.round_type = 'competition';

  get diagnostics v_updated_count = row_count;

  if coalesce(p_round_payload ->> 'round_type', '') = 'competition'
    and v_updated_count <> v_expected_count
  then
    raise exception using errcode = 'P0001', message = 'ROUND_CREATION_FAILED';
  end if;

  return v_round_ids;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_player_golf_rounds_transactional_without_group_id(p_player_id uuid, p_round_payload jsonb, p_round_dates timestamp with time zone[], p_holes jsonb DEFAULT '[]'::jsonb)
 RETURNS uuid[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor_id uuid := auth.uid();
  v_round public.golf_rounds%rowtype;
  v_hole public.golf_round_holes%rowtype;
  v_hole_payload jsonb;
  v_round_id uuid;
  v_round_date timestamptz;
  v_round_ids uuid[] := array[]::uuid[];
begin
  if p_player_id is null or p_round_payload is null or jsonb_typeof(p_round_payload) <> 'object' then
    raise exception using errcode = 'P0001', message = 'INVALID_ROUND_PAYLOAD';
  end if;

  if v_actor_id is null or (
    v_actor_id <> p_player_id
    and not exists (
      select 1
      from public.player_guardians pg
      where pg.player_id = p_player_id
        and pg.guardian_user_id = v_actor_id
        and coalesce(pg.can_view, true) = true
        and coalesce(pg.can_edit, false) = true
    )
  ) then
    raise exception using errcode = 'P0001', message = 'FORBIDDEN';
  end if;

  if not exists (
    select 1
    from public.club_members cm
    where cm.user_id = p_player_id
      and cm.role = 'player'
      and cm.is_active = true
  ) then
    raise exception using errcode = 'P0001', message = 'PLAYER_MEMBERSHIP_REQUIRED';
  end if;

  if p_round_dates is null
    or coalesce(array_length(p_round_dates, 1), 0) not between 1 and 4
    or array_position(p_round_dates, null) is not null
  then
    raise exception using errcode = 'P0001', message = 'INVALID_ROUND_DATES';
  end if;

  if p_holes is null or jsonb_typeof(p_holes) <> 'array' or jsonb_array_length(p_holes) > 18 then
    raise exception using errcode = 'P0001', message = 'INVALID_HOLES_PAYLOAD';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_holes) hole
    where jsonb_typeof(hole.value) <> 'object'
      or nullif(hole.value ->> 'hole_no', '') is null
      or (hole.value ->> 'hole_no')::integer not between 1 and 18
  ) or (
    select count(*)
    from (
      select hole.value ->> 'hole_no'
      from jsonb_array_elements(p_holes) hole
      group by hole.value ->> 'hole_no'
      having count(*) > 1
    ) duplicates
  ) > 0 then
    raise exception using errcode = 'P0001', message = 'INVALID_HOLES_PAYLOAD';
  end if;

  v_round := jsonb_populate_record(null::public.golf_rounds, p_round_payload);

  if coalesce(trim(v_round.round_type::text), '') not in ('training', 'competition')
    or (
      v_round.round_type = 'competition'
      and v_round.om_competition_format = 'stroke_play_individual'
      and v_round.om_rounds_18_count is distinct from array_length(p_round_dates, 1)
    )
    or (
      coalesce(array_length(p_round_dates, 1), 0) > 1
      and not (
        v_round.round_type = 'competition'
        and v_round.om_competition_format = 'stroke_play_individual'
      )
    )
  then
    raise exception using errcode = 'P0001', message = 'INVALID_ROUND_PAYLOAD';
  end if;

  if v_round.om_organization_id is not null and not exists (
    select 1
    from public.club_members cm
    where cm.user_id = p_player_id
      and cm.club_id = v_round.om_organization_id
      and cm.role = 'player'
      and cm.is_active = true
  ) then
    raise exception using errcode = 'P0001', message = 'FORBIDDEN';
  end if;

  foreach v_round_date in array p_round_dates
  loop
    insert into public.golf_rounds (
      user_id,
      location,
      round_type,
      competition_name,
      handicap_start,
      course_source,
      course_name,
      external_course_id,
      tee_name,
      slope_rating,
      course_rating,
      match_opponent_handicap,
      om_match_result,
      match_score_text,
      notes,
      om_organization_id,
      om_competition_level,
      om_competition_format,
      om_rounds_18_count,
      score_entry_mode,
      om_match_play_wins,
      om_is_exceptional,
      om_exceptional_tournament_id,
      om_stats_submitted_at,
      start_at
    ) values (
      p_player_id,
      v_round.location,
      v_round.round_type,
      v_round.competition_name,
      v_round.handicap_start,
      v_round.course_source,
      v_round.course_name,
      v_round.external_course_id,
      v_round.tee_name,
      v_round.slope_rating,
      v_round.course_rating,
      v_round.match_opponent_handicap,
      v_round.om_match_result,
      v_round.match_score_text,
      v_round.notes,
      v_round.om_organization_id,
      v_round.om_competition_level,
      v_round.om_competition_format,
      v_round.om_rounds_18_count,
      v_round.score_entry_mode,
      v_round.om_match_play_wins,
      v_round.om_is_exceptional,
      v_round.om_exceptional_tournament_id,
      v_round.om_stats_submitted_at,
      v_round_date
    )
    returning id into v_round_id;

    for v_hole_payload in
      select value from jsonb_array_elements(p_holes)
    loop
      v_hole := jsonb_populate_record(null::public.golf_round_holes, v_hole_payload);
      insert into public.golf_round_holes (round_id, hole_no, par, stroke_index)
      values (v_round_id, v_hole.hole_no, v_hole.par, v_hole.stroke_index);
    end loop;

    v_round_ids := array_append(v_round_ids, v_round_id);
  end loop;

  return v_round_ids;
exception
  when invalid_text_representation or numeric_value_out_of_range then
    raise exception using errcode = 'P0001', message = 'INVALID_ROUND_PAYLOAD';
end;
$function$

CREATE OR REPLACE FUNCTION public.decide_legal_document(p_presentation uuid, p_actor uuid, p_decision text, p_key uuid, p_parent_code text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare p public.legal_presentations%rowtype; d public.legal_documents%rowtype; latest uuid; previous public.legal_current_state%rowtype;
  challenge public.legal_parent_challenges%rowtype; event_id uuid; expected text;
begin
  select id into event_id from public.legal_decisions where actor_id=p_actor and idempotency_key=p_key;
  if found then
    if not exists(select 1 from public.legal_decisions where id=event_id and presentation_id=p_presentation and decision=p_decision) then
      raise exception 'Idempotency key reused for another decision';
    end if;
    return event_id;
  end if;
  select * into p from public.legal_presentations where id=p_presentation;
  if not found or p.actor_id<>p_actor or p.expires_at<now() then raise exception 'Presentation expired or forbidden'; end if;
  select * into d from public.legal_documents where id=p.document_id for update;
  if coalesce(d.applicability->>'rule','')<>'all_members' then raise exception 'Rule engine not configured'; end if;
  if not d.active or not public.legal_actor_allowed(p_actor,p.beneficiary_id,p.club_id,p.actor_role) then raise exception 'Access changed'; end if;
  select id into event_id from public.legal_decisions where actor_id=p_actor and idempotency_key=p_key;
  if found then
    if not exists(select 1 from public.legal_decisions where id=event_id and presentation_id=p_presentation and decision=p_decision) then
      raise exception 'Idempotency key reused for another decision';
    end if;
    return event_id;
  end if;
  select id into latest from public.legal_versions where document_id=d.id order by version_number desc limit 1;
  if latest is distinct from p.version_id then raise exception 'Legal version changed'; end if;
  if public.legal_version_matches_document(d.id,p.version_id) is not true then raise exception 'Published metadata changed'; end if;
  if p.rendered_sha256<>encode(extensions.digest(p.rendered_snapshot::text,'sha256'),'hex') then raise exception 'Presentation integrity failed'; end if;
  if p_decision not in ('accepted','acknowledged','authorized','consented','refused','withdrawn') then raise exception 'Invalid decision'; end if;
  if p_decision='withdrawn' and d.kind<>'specific_consent' then raise exception 'Not withdrawable here'; end if;
  if p_decision='accepted' and d.action_kind<>'accept' or p_decision='acknowledged' and d.action_kind not in ('acknowledge','read')
     or p_decision='authorized' and d.action_kind<>'authorize' or p_decision='consented' and d.action_kind<>'consent'
  then raise exception 'Wrong action'; end if;
  if p.actor_id<>p.beneficiary_id and p_decision not in ('refused','withdrawn') then
    select * into challenge from public.legal_parent_challenges where presentation_id=p.id and actor_id=p_actor
      order by created_at desc limit 1 for update;
    if not found or challenge.used_at is not null or challenge.expires_at<now() or challenge.attempts>=5 then raise exception 'Confirmation required'; end if;
    update public.legal_parent_challenges set attempts=attempts+1 where id=challenge.id;
    expected:=encode(extensions.digest(coalesce(p_parent_code,''),'sha256'),'hex');
    if expected<>challenge.secret_hash then return null; end if;
    if not exists(select 1 from auth.users u where u.id=p_actor and u.email_confirmed_at is not null
      and encode(extensions.digest(lower(trim(u.email)),'sha256'),'hex')=challenge.email_hash) then raise exception 'Parent email changed'; end if;
    update public.legal_parent_challenges set used_at=now() where id=challenge.id;
    challenge.used_at:=now();
  end if;
  select * into previous from public.legal_current_state where document_id=d.id and beneficiary_id=p.beneficiary_id
    and scope_key=coalesce(p.club_id::text,'platform') for update;
  if found and previous.conflict and p_decision in ('accepted','authorized','consented') then raise exception 'Withdrawal conflict requires review'; end if;
  insert into public.legal_decisions(presentation_id,actor_id,beneficiary_id,document_id,version_id,club_id,
    decision,rendered_snapshot,rendered_sha256,authority_snapshot,idempotency_key)
  values(p.id,p_actor,p.beneficiary_id,d.id,p.version_id,p.club_id,p_decision,p.rendered_snapshot,p.rendered_sha256,
    jsonb_build_object('role',p.actor_role,'authority',p.authority,'parent_email_confirmed',challenge.used_at is not null),p_key)
  returning id into event_id;
  insert into public.legal_current_state(document_id,beneficiary_id,club_scope,version_id,decision_id,decision,decided_at,conflict)
  values(d.id,p.beneficiary_id,p.club_id,p.version_id,event_id,p_decision,now(),p_decision='withdrawn')
  on conflict(document_id,beneficiary_id,scope_key) do update set version_id=excluded.version_id,decision_id=excluded.decision_id,
    decision=excluded.decision,decided_at=excluded.decided_at,
    conflict=case when excluded.decision='withdrawn' then true else legal_current_state.conflict end;
  return event_id;
end $function$

CREATE OR REPLACE FUNCTION public.delete_coach_planning_v1(p_actor_id uuid, p_event_id uuid DEFAULT NULL::uuid, p_series_id uuid DEFAULT NULL::uuid, p_occurrence_confirmed boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_event public.club_events%rowtype;
  v_series public.club_event_series%rowtype;
  v_group uuid;
  v_club uuid;
  v_ids uuid[];
  v_recipients uuid[];
  v_notifications jsonb;
  v_table text;
begin
  if coalesce(auth.role(), '') <> 'service_role' or p_actor_id is null then
    raise exception 'forbidden';
  end if;
  if (p_event_id is null) = (p_series_id is null) then raise exception 'invalid_delete_scope'; end if;
  if p_series_id is not null then
    select * into v_series from public.club_event_series where id = p_series_id for update;
    if not found then raise exception 'series_not_found'; end if;
    v_group := v_series.group_id; v_club := v_series.club_id;
  else
    select * into v_event from public.club_events where id = p_event_id for update;
    if not found then raise exception 'event_not_found'; end if;
    v_group := v_event.group_id; v_club := v_event.club_id;
  end if;
  if v_group is null or v_club is null or not exists (
    select 1 from public.coach_groups where id = v_group and club_id = v_club
  ) or not public.can_manage_assigned_group(v_group, p_actor_id, 'planning') then
    raise exception 'forbidden';
  end if;
  if p_event_id is not null and v_event.series_id is not null and not coalesce(p_occurrence_confirmed,false) then
    raise exception 'occurrence_confirmation_required';
  end if;
  -- Lock the complete set, never a paginated browser snapshot. Foreign or
  -- manager-only occurrences make the whole request fail before any deletion.
  perform id from public.club_events where
    (p_series_id is not null and series_id = p_series_id) or id = p_event_id order by id for update;
  if exists (select 1 from public.club_events where
    ((p_series_id is not null and series_id = p_series_id) or id = p_event_id)
    and (group_id is distinct from v_group or club_id is distinct from v_club or event_type = 'competition')
  ) then raise exception 'forbidden'; end if;
  select coalesce(array_agg(id order by id), '{}'::uuid[]),
    coalesce(jsonb_agg(jsonb_build_object('id',id,'event_type',event_type,'starts_at',starts_at,
      'location_text',location_text) order by starts_at,id), '[]'::jsonb)
  into v_ids,v_notifications from public.club_events where
    (p_series_id is not null and series_id = p_series_id) or id = p_event_id;
  select coalesce(array_agg(distinct player_id), '{}'::uuid[]) into v_recipients
    from public.club_event_attendees where event_id = any(v_ids) and coalesce(status,'expected') <> 'absent';
  foreach v_table in array array['club_event_attendees','club_event_coaches','club_event_structure_items',
    'club_event_player_structure_items','club_event_player_feedback','club_event_coach_feedback'] loop
    if to_regclass('public.' || v_table) is not null then
      execute format('delete from public.%I where event_id = any($1)',v_table) using v_ids;
    end if;
  end loop;
  if to_regclass('public.training_sessions') is not null then
    if to_regclass('public.training_session_items') is not null then
      execute 'delete from public.training_session_items where session_id in (select id from public.training_sessions where club_event_id = any($1))' using v_ids;
    end if;
    execute 'delete from public.training_sessions where club_event_id = any($1)' using v_ids;
  end if;
  if to_regclass('public.message_threads') is not null then
    execute 'delete from public.message_threads where event_id = any($1)' using v_ids;
  end if;
  -- Other event-owned records follow their schema FK cascade; documents and
  -- linked club news retain their existing ON DELETE SET NULL behavior.
  delete from public.club_events where id = any(v_ids);
  if p_series_id is not null then delete from public.club_event_series where id = p_series_id; end if;
  return jsonb_build_object('ok',true,'deleted_event_id',p_event_id,'deleted_series_id',p_series_id,
    'deleted_events',cardinality(v_ids),'events',v_notifications,'recipient_ids',v_recipients);
end;
$function$

CREATE OR REPLACE FUNCTION public.delete_manager_planning_v1(p_actor_id uuid, p_event_id uuid DEFAULT NULL::uuid, p_series_id uuid DEFAULT NULL::uuid, p_occurrence_confirmed boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_event public.club_events%rowtype;
  v_series public.club_event_series%rowtype;
  v_group uuid;
  v_club uuid;
  v_ids uuid[];
  v_recipients uuid[];
  v_notifications jsonb;
  v_table text;
begin
  if coalesce(auth.role(), '') <> 'service_role' or p_actor_id is null then
    raise exception 'forbidden';
  end if;
  if (p_event_id is null) = (p_series_id is null) then raise exception 'invalid_delete_scope'; end if;
  if p_series_id is not null then
    select * into v_series from public.club_event_series where id = p_series_id for update;
    if not found then raise exception 'series_not_found'; end if;
    v_group := v_series.group_id; v_club := v_series.club_id;
  else
    select * into v_event from public.club_events where id = p_event_id for update;
    if not found then raise exception 'event_not_found'; end if;
    v_group := v_event.group_id; v_club := v_event.club_id;
  end if;
  perform public.require_manager_club_scope_v1(p_actor_id,v_club);
  if p_event_id is not null and v_event.series_id is not null and not coalesce(p_occurrence_confirmed,false) then
    raise exception 'occurrence_confirmation_required';
  end if;
  -- Lock the complete set, never a paginated browser snapshot. Foreign or
  -- occurrences outside the club/group make the request fail before deletion.
  perform id from public.club_events where
    (p_series_id is not null and series_id = p_series_id) or id = p_event_id order by id for update;
  if exists (select 1 from public.club_events where
    ((p_series_id is not null and series_id = p_series_id) or id = p_event_id)
    and (group_id is distinct from v_group or club_id is distinct from v_club)
  ) then raise exception 'forbidden'; end if;
  select coalesce(array_agg(id order by id), '{}'::uuid[]),
    coalesce(jsonb_agg(jsonb_build_object('id',id,'event_type',event_type,'starts_at',starts_at,
      'location_text',location_text) order by starts_at,id), '[]'::jsonb)
  into v_ids,v_notifications from public.club_events where
    (p_series_id is not null and series_id = p_series_id) or id = p_event_id;
  select coalesce(array_agg(distinct player_id), '{}'::uuid[]) into v_recipients
    from public.club_event_attendees where event_id = any(v_ids) and coalesce(status,'expected') <> 'absent';
  foreach v_table in array array['club_event_attendees','club_event_coaches','club_event_structure_items',
    'club_event_player_structure_items','club_event_player_feedback','club_event_coach_feedback'] loop
    if to_regclass('public.' || v_table) is not null then
      execute format('delete from public.%I where event_id = any($1)',v_table) using v_ids;
    end if;
  end loop;
  if to_regclass('public.training_sessions') is not null then
    if to_regclass('public.training_session_items') is not null then
      execute 'delete from public.training_session_items where session_id in (select id from public.training_sessions where club_event_id = any($1))' using v_ids;
    end if;
    execute 'delete from public.training_sessions where club_event_id = any($1)' using v_ids;
  end if;
  if to_regclass('public.message_threads') is not null then
    execute 'delete from public.message_threads where event_id = any($1)' using v_ids;
  end if;
  -- Other event-owned records follow their schema FK cascade; documents and
  -- linked club news retain their existing ON DELETE SET NULL behavior.
  delete from public.club_events where id = any(v_ids);
  if p_series_id is not null then delete from public.club_event_series where id = p_series_id; end if;
  return jsonb_build_object('ok',true,'deleted_event_id',p_event_id,'deleted_series_id',p_series_id,
    'deleted_events',cardinality(v_ids),'events',v_notifications,'recipient_ids',v_recipients);
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_competition_attendee_audience_status()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if exists (
    select 1
    from public.club_events e
    where e.id = new.event_id
      and e.event_type = 'competition'
  ) then
    new.status := 'expected';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_performance_mode_on_training_session_items()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_player_id uuid;
begin
  if new.session_id is null then
    raise exception 'missing_session_id';
  end if;

  select ts.user_id
  into v_player_id
  from public.training_sessions ts
  where ts.id = new.session_id;

  if v_player_id is null then
    raise exception 'training_session_not_found';
  end if;

  if not public.is_user_performance_enabled_globally(v_player_id) then
    raise exception 'performance_mode_required';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_performance_mode_on_training_sessions()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.user_id is null then
    raise exception 'missing_player_id';
  end if;

  if not public.is_user_performance_enabled_globally(new.user_id) then
    if new.motivation is not null
       or new.difficulty is not null
       or new.satisfaction is not null then
      raise exception 'performance_mode_required';
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_player_performance_on_group_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org uuid;
begin
  if tg_table_name = 'coach_groups' then
    v_org := coalesce(new.club_id, old.club_id);
    perform public.sync_org_player_performance_from_groups(v_org);
    return coalesce(new, old);
  end if;

  if tg_table_name = 'coach_group_players' then
    select g.club_id
    into v_org
    from public.coach_groups g
    where g.id = coalesce(new.group_id, old.group_id);
    perform public.sync_org_player_performance_from_groups(v_org);
    return coalesce(new, old);
  end if;

  return coalesce(new, old);
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_player_team_thread_participant_scope()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if exists (
    select 1
    from public.message_threads t
    where t.id = new.thread_id
      and t.thread_type = 'player'
      and t.player_thread_scope = 'team'
  ) and not public.is_valid_player_team_thread_participant(new.thread_id, new.user_id) then
    raise exception 'Invalid participant for player team thread organization'
      using errcode = '42501';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.ensure_manager_controls_competitions()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_event_type text;
  v_club_id uuid;
begin
  if tg_op = 'DELETE' then
    v_event_type := old.event_type;
    v_club_id := old.club_id;
  else
    v_event_type := new.event_type;
    v_club_id := new.club_id;
    if tg_op = 'UPDATE' and old.event_type = 'competition' then
      v_event_type := 'competition';
      v_club_id := old.club_id;
    end if;
  end if;

  if v_event_type = 'competition' and coalesce(auth.role(), '') <> 'service_role' then
    if auth.uid() is null or not exists (
      select 1
      from public.club_members cm
      where cm.club_id = v_club_id
        and cm.user_id = auth.uid()
        and cm.role = 'manager'
        and cm.is_active = true
    ) then
      raise exception 'Only an active club manager can create, update or delete a competition'
        using errcode = '42501';
    end if;
  end if;

  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.finish_manager_news_email_v1(p_actor uuid, p_club uuid, p_news uuid, p_recipient uuid, p_attempt uuid, p_status text, p_error text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  perform public.require_manager_club_scope_v1(p_actor,p_club);
  if p_status not in ('sent','failed','uncertain') then raise exception 'invalid_delivery_status' using errcode='22023'; end if;
  if not exists(select 1 from public.club_news where id=p_news and club_id=p_club) then raise exception 'news_not_found' using errcode='P0002'; end if;
  update public.club_news_email_deliveries set status=p_status,last_error=left(p_error,500),sent_at=case when p_status='sent' then now() else null end,updated_at=now()
    where news_id=p_news and recipient_user_id=p_recipient and attempt_id=p_attempt and status='sending';
  if not found then raise exception 'delivery_attempt_not_found' using errcode='P0002'; end if;
end $function$

CREATE OR REPLACE FUNCTION public.get_manager_camp_versions_v1(p_actor uuid, p_club_ids uuid[], p_camp uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare club uuid; result jsonb;
begin
  foreach club in array p_club_ids loop perform public.require_manager_club_scope_v1(p_actor,club); end loop;
  select coalesce(jsonb_object_agg(id,public.manager_camp_version_v1(id)),'{}') into result from public.club_camps where club_id=any(p_club_ids) and id=p_camp;
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.get_manager_competition_snapshot_v1_business(p_event_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_event public.club_events%rowtype;
begin
  select * into v_event from public.club_events where id=p_event_id;
  if v_event.id is null then raise exception 'event_not_found'; end if;
  perform public.require_manager_club_scope_v1(auth.uid(),v_event.club_id);
  if v_event.event_type<>'competition' then raise exception 'invalid_competition'; end if;
  return jsonb_build_object('event',to_jsonb(v_event),
    'attendees',coalesce((select jsonb_agg(to_jsonb(a) order by a.player_id) from public.club_event_attendees a where a.event_id=p_event_id),'[]'),
    'coaches',coalesce((select jsonb_agg(to_jsonb(c) order by c.coach_id) from public.club_event_coaches c where c.event_id=p_event_id),'[]'),
    'reminder',(select to_jsonb(r) from public.club_event_reminders r where r.event_id=p_event_id),
    'group',(select to_jsonb(g) from public.coach_groups g where g.id=v_event.group_id),
    'group_players',coalesce((select jsonb_agg(to_jsonb(p) order by p.player_user_id) from public.coach_group_players p where p.group_id=v_event.group_id),'[]'),
    'group_coaches',coalesce((select jsonb_agg(to_jsonb(c) order by c.coach_user_id) from public.coach_group_coaches c where c.group_id=v_event.group_id),'[]'));
end;
$function$

CREATE OR REPLACE FUNCTION public.get_manager_evaluation_snapshot_v1_business(p_event_id uuid, p_player_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_event public.club_events%rowtype; v_attendee public.club_event_attendees%rowtype;
begin
  select * into v_event from public.club_events where id=p_event_id;
  if v_event.id is null then raise exception 'event_not_found'; end if;
  perform public.require_manager_club_scope_v1(auth.uid(),v_event.club_id);
  select * into v_attendee from public.club_event_attendees where event_id=p_event_id and player_id=p_player_id;
  if v_attendee.player_id is null then raise exception 'unknown_attendee'; end if;
  return jsonb_build_object(
    'event',jsonb_build_object('id',v_event.id,'group_id',v_event.group_id,'club_id',v_event.club_id,'status',v_event.status,
      'event_type',v_event.event_type,'starts_at',v_event.starts_at,'ends_at',v_event.ends_at,'duration_minutes',v_event.duration_minutes,'requires_evaluation',v_event.requires_evaluation),
    'attendee',jsonb_build_object('player_id',v_attendee.player_id,'status',v_attendee.status,'coach_recorded_status',v_attendee.coach_recorded_status,
      'coach_recorded_by',v_attendee.coach_recorded_by,'coach_recorded_at',v_attendee.coach_recorded_at),
    'feedback',coalesce((select jsonb_agg(to_jsonb(f) order by (f.coach_id=auth.uid()) desc,f.coach_id) from public.club_event_coach_feedback f where event_id=p_event_id and player_id=p_player_id),'[]'::jsonb),
    'criteria',coalesce((select jsonb_agg(to_jsonb(c) order by c.position,c.id) from public.club_event_evaluation_criteria c where event_id=p_event_id and is_enabled and snapshot_respondent in ('coach','both')),'[]'::jsonb),
    'responses',coalesce((select jsonb_agg(to_jsonb(r) order by r.event_criterion_id) from public.club_event_evaluation_responses r where event_id=p_event_id and player_id=p_player_id and respondent_role='coach'),'[]'::jsonb)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.get_manager_om_contest_v1_business(p_contest_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.om_internal_contests%rowtype;
begin
 select * into c from public.om_internal_contests where id=p_contest_id for share;
 if c.id is null then raise exception 'contest_not_found'; end if;
 perform public.require_manager_club_scope_v1(auth.uid(),c.organization_id);
 return jsonb_build_object('contest',to_jsonb(c),'version',public.manager_om_contest_version_v1(c.id),
  'results',coalesce((select jsonb_agg(to_jsonb(r) order by r.rank,r.player_id) from public.om_internal_contest_results r where r.contest_id=c.id),'[]'),
  'players',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'first_name',p.first_name,'last_name',p.last_name) order by p.last_name,p.first_name,p.id)
   from public.profiles p where exists(select 1 from public.om_internal_contest_results r where r.contest_id=c.id and r.player_id=p.id)
    or (exists(select 1 from public.club_members m where m.club_id=c.organization_id and m.user_id=p.id and m.role='player' and m.is_active)
     and (c.group_id is null or exists(select 1 from public.coach_group_players gp where gp.group_id=c.group_id and gp.player_user_id=p.id)))),'[]'));
end $function$

CREATE OR REPLACE FUNCTION public.get_manager_om_data_v1_business(p_club_id uuid, p_kind text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 perform public.require_manager_club_scope_v1(auth.uid(),p_club_id);
 if p_kind='contest' then
  return jsonb_build_object('club_id',p_club_id,'rows',coalesce((select jsonb_agg(to_jsonb(c)||jsonb_build_object('version',public.manager_om_contest_version_v1(c.id)) order by c.contest_date desc,c.id) from public.om_internal_contests c where c.organization_id=p_club_id),'[]'),
   'groups',coalesce((select jsonb_agg(jsonb_build_object('id',g.id,'name',g.name,'is_active',g.is_active,'club_season_id',g.club_season_id) order by g.name,g.id) from public.coach_groups g where g.club_id=p_club_id),'[]'));
 elsif p_kind='tournament' then
  return jsonb_build_object('club_id',p_club_id,'rows',coalesce((select jsonb_agg(to_jsonb(r)||jsonb_build_object('version',md5(to_jsonb(r)::text)) order by r.starts_on desc nulls last,r.id) from public.om_exceptional_tournaments r where r.organization_id=p_club_id),'[]'),'groups','[]'::jsonb);
 end if;
 raise exception 'invalid_kind';
end $function$

CREATE OR REPLACE FUNCTION public.get_manager_om_ranking_v1_business(p_club_id uuid, p_from date, p_to date, p_player_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ranking jsonb;
begin
 perform public.require_manager_club_scope_v1(auth.uid(),p_club_id);
 if p_from is null or p_to is null or p_to<p_from then raise exception 'invalid_dates';end if;
 if p_player_id is null then
  select coalesce(jsonb_agg(to_jsonb(r)),'[]') into ranking from public.om_ranking_snapshot(p_club_id,p_from,p_to) r;
  return jsonb_build_object('club_id',p_club_id,'rows',ranking,'avatars',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'avatar_url',p.avatar_url)) from public.profiles p where exists(select 1 from jsonb_array_elements(ranking) r where r->>'player_id'=p.id::text)),'[]'));
 end if;
 return jsonb_build_object('club_id',p_club_id,'player_id',p_player_id,
  'scores',coalesce((select jsonb_agg(to_jsonb(s)) from public.om_tournament_scores s where s.organization_id=p_club_id and s.player_id=p_player_id and s.occurred_on between p_from and p_to),'[]'),
  'bonuses',coalesce((select jsonb_agg(jsonb_build_object('id',b.id,'bonus_type',b.bonus_type,'points_net',b.points_net,'points_brut',b.points_brut,'description',b.description,'occurred_on',b.occurred_on)) from public.om_bonus_entries b where b.organization_id=p_club_id and b.player_id=p_player_id and b.occurred_on between p_from and p_to),'[]'),
  'rounds',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'start_at',r.start_at,'competition_name',r.competition_name,'course_name',r.course_name)) from public.golf_rounds r where exists(select 1 from public.om_tournament_scores s where s.round_id=r.id and s.organization_id=p_club_id and s.player_id=p_player_id and s.occurred_on between p_from and p_to)),'[]'));
end $function$

CREATE OR REPLACE FUNCTION public.get_manager_planning_snapshot_v1_business(p_event_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e public.club_events%rowtype; result jsonb; s jsonb;
begin
  select * into e from public.club_events where id=p_event_id;
  if not found then raise exception 'event_not_found' using errcode='P0002'; end if;
  perform public.require_manager_club_scope_v1(auth.uid(),e.club_id);
  result := public.manager_event_snapshot_v1(e.id);
  if e.series_id is not null then
    select to_jsonb(x) into s from public.club_event_series x where id=e.series_id;
    result := result || jsonb_build_object('series',s,'future',coalesce((
      select jsonb_agg(public.manager_event_snapshot_v1(x.id) order by x.starts_at,x.id)
      from public.club_events x where x.series_id=e.series_id and x.starts_at>=now()),'[]'));
  end if;
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.get_rules_quiz_question_business(p_attempt_id uuid, p_position smallint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_row rules_attempt_questions; v_question rules_questions;
begin
  if not exists(
    select 1 from rules_quiz_attempts a
    where a.id=p_attempt_id and a.player_user_id=auth.uid() and a.status='in_progress'
      and public.can_access_rules_quiz(a.series_id,a.club_id,a.player_user_id)
  ) then raise exception 'Attempt unavailable'; end if;
  update rules_attempt_questions set shown_at=coalesce(shown_at,now()) where attempt_id=p_attempt_id and position=p_position returning * into v_row;
  select * into v_question from rules_questions where id=v_row.question_id;
  return jsonb_build_object('position',p_position,'question_id',v_question.id,'prompt',v_question.prompt,'image_url',v_question.image_url,'image_alt',v_question.image_alt,
    'options',(select jsonb_agg(jsonb_build_object('id',o.id,'label',o.label) order by array_position(v_row.option_order,o.id)) from rules_question_options o where o.question_id=v_question.id),
    'answered',v_row.answered_at is not null,'selected_option_ids',coalesce(v_row.selected_option_ids,'{}'::uuid[]));
end $function$

CREATE OR REPLACE FUNCTION public.get_rules_quiz_result_business(p_attempt_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_attempt rules_quiz_attempts;
begin
  select * into v_attempt from rules_quiz_attempts where id=p_attempt_id and player_user_id=auth.uid() and status='submitted';
  if v_attempt.id is null then raise exception 'Result unavailable'; end if;
  return jsonb_build_object('score',v_attempt.total_score,'correct',v_attempt.correct_count,'base',v_attempt.base_score,'speed_bonus',v_attempt.speed_bonus,'perfect_bonus',v_attempt.perfect_bonus,
    'questions',(select jsonb_agg(jsonb_build_object('position',aq.position,'prompt',q.prompt,'correct',aq.is_correct,'explanation',q.explanation,
      'selected',aq.selected_option_ids,'options',(select jsonb_agg(jsonb_build_object('id',o.id,'label',o.label,'correct',o.is_correct,'explanation',o.explanation) order by array_position(aq.option_order,o.id)) from rules_question_options o where o.question_id=q.id)) order by aq.position)
      from rules_attempt_questions aq join rules_questions q on q.id=aq.question_id where aq.attempt_id=p_attempt_id));
end $function$

CREATE OR REPLACE FUNCTION public.guard_golf_tournament_group_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_round_count integer;
begin
  if old.tournament_group_id is not null
    and new.tournament_group_id is distinct from old.tournament_group_id
  then
    raise exception using errcode = 'P0001', message = 'TOURNAMENT_GROUP_IMMUTABLE';
  end if;

  if old.tournament_group_id is not null
    and new.round_type = 'competition'
    and new.om_competition_format = 'stroke_play_individual'
  then
    select count(*)::integer
    into v_round_count
    from public.golf_rounds gr
    where gr.tournament_group_id = old.tournament_group_id;

    if new.om_rounds_18_count is distinct from v_round_count then
      raise exception using errcode = 'P0001', message = 'INVALID_TOURNAMENT_ROUND_COUNT';
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.issue_legal_parent_challenge(p_presentation uuid, p_actor uuid, p_email_hash text, p_secret_hash text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare p public.legal_presentations%rowtype; d public.legal_documents%rowtype; latest uuid; recent timestamptz; sends integer; challenge_id uuid;
begin
  if p_email_hash !~ '^[0-9a-f]{64}$' or p_secret_hash !~ '^[0-9a-f]{64}$' then raise exception 'Invalid challenge'; end if;
  perform pg_advisory_xact_lock(hashtextextended('legal_parent:'||p_actor::text,0));
  select * into p from public.legal_presentations where id=p_presentation;
  if not found or p.actor_id<>p_actor or p.beneficiary_id=p_actor or p.expires_at<=now()
    or p.authority<>'verified_representative' then raise exception 'Presentation unavailable'; end if;
  select * into d from public.legal_documents where id=p.document_id for update;
  if not d.active or not public.legal_actor_allowed(p_actor,p.beneficiary_id,p.club_id,p.actor_role) then raise exception 'Access changed'; end if;
  select id into latest from public.legal_versions where document_id=d.id order by version_number desc limit 1;
  if latest is distinct from p.version_id then raise exception 'Legal version changed'; end if;
  if not exists(select 1 from auth.users u where u.id=p_actor and u.email_confirmed_at is not null
      and encode(extensions.digest(lower(trim(u.email)),'sha256'),'hex')=p_email_hash) then raise exception 'Verified parent email required'; end if;
  select max(created_at),count(*) filter(where created_at>now()-interval '1 hour') into recent,sends
    from public.legal_parent_challenges where actor_id=p_actor;
  if recent>now()-interval '1 minute' or sends>=5 then raise exception 'Challenge rate limited'; end if;
  update public.legal_parent_challenges set used_at=now() where presentation_id=p.id and used_at is null;
  insert into public.legal_parent_challenges(presentation_id,actor_id,beneficiary_id,email_hash,secret_hash,expires_at)
  values(p.id,p_actor,p.beneficiary_id,p_email_hash,p_secret_hash,least(p.expires_at,now()+interval '10 minutes'))
  returning id into challenge_id;
  return challenge_id;
end $function$

CREATE OR REPLACE FUNCTION public.legal_required_event_access(p_event uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare club uuid; enabled_now boolean;
begin
  select enabled into enabled_now from public.legal_enforcement_control where singleton=true;
  if not found then return false; end if;
  if not enabled_now then return true; end if;
  if p_event is null then return public.legal_required_direct_access(null); end if;
  select e.club_id into club from public.club_events e where e.id=p_event;
  if not found or club is null then return false; end if;
  return public.legal_required_direct_access(club);
end $function$

