CREATE OR REPLACE FUNCTION public.manage_player_guardian_v1(p_actor_id uuid, p_club_id uuid, p_player_id uuid, p_guardian_id uuid, p_action text, p_relation text DEFAULT 'other'::text, p_is_primary boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform public.require_manager_player_scope_v1(p_actor_id, p_club_id, p_player_id);
  if p_action = 'delete' then
    delete from public.player_guardians where player_id = p_player_id and guardian_user_id = p_guardian_id;
    -- Revoked links must not remain scheduled recipients, including other clubs.
    update public.player_periodic_report_configs
      set recipient_user_ids = array_remove(recipient_user_ids, p_guardian_id), updated_at = now()
      where player_user_id = p_player_id and p_guardian_id = any(recipient_user_ids);
  elsif p_action = 'upsert' then
    if p_guardian_id = p_player_id or p_relation not in ('mother', 'father', 'legal_guardian', 'other') then
      raise exception using errcode = '22023', message = 'invalid_guardian';
    end if;
    perform 1 from public.club_members where user_id = p_guardian_id and club_id = p_club_id
      and role = 'parent' and is_active = true for share;
    if not found then raise exception using errcode = 'P0002', message = 'guardian_not_found'; end if;
    if p_is_primary then
      update public.player_guardians set is_primary = false where player_id = p_player_id;
    end if;
    insert into public.player_guardians (player_id, guardian_user_id, relation, is_primary, can_view, can_edit)
      values (p_player_id, p_guardian_id, p_relation, p_is_primary, true, true)
      on conflict (player_id, guardian_user_id) do update set
        relation = excluded.relation, is_primary = excluded.is_primary, can_view = true, can_edit = true;
  else
    raise exception using errcode = '22023', message = 'invalid_action';
  end if;
  return jsonb_build_object('ok', true);
end;
$function$

CREATE OR REPLACE FUNCTION public.manager_sync_event_criteria_v1(p_event uuid, p_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare club uuid; kind text; criterion uuid; pos int := 0;
begin
  select club_id,event_type into club,kind from public.club_events where id=p_event;
  if p_ids is null or cardinality(p_ids)>3 or cardinality(p_ids)<>(select count(distinct x) from unnest(p_ids) x) then
    raise exception 'invalid_criteria' using errcode='22023';
  end if;
  if exists(select 1 from unnest(p_ids) x where not exists(
    select 1 from public.club_evaluation_criteria c where c.id=x and c.club_id=club
    and (exists(select 1 from public.club_event_evaluation_criteria ec where ec.event_id=p_event and ec.criterion_id=x)
      or (c.is_active and kind=any(c.activity_types))))) then
    raise exception 'invalid_criteria' using errcode='22023';
  end if;
  -- Disable instead of deleting: snapshots and every existing answer survive.
  update public.club_event_evaluation_criteria set is_enabled=false where event_id=p_event;
  foreach criterion in array p_ids loop
    pos := pos+1;
    update public.club_event_evaluation_criteria set is_enabled=true,position=pos where event_id=p_event and criterion_id=criterion;
    if not found then
      insert into public.club_event_evaluation_criteria(event_id,club_id,criterion_id,position) values(p_event,club,criterion,pos);
    end if;
  end loop;
end $function$

CREATE OR REPLACE FUNCTION public.manager_validate_competition_v1(p_payload jsonb, p_reminder_editable boolean DEFAULT true)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_start timestamptz:=(p_payload->>'startsAt')::timestamptz; v_end timestamptz:=(p_payload->>'endsAt')::timestamptz;
  v_day date:=(p_payload->>'competitionStartDate')::date; v_last date:=(p_payload->>'competitionEndDate')::date;
  v_reminder jsonb:=p_payload->'reminder'; v_scheduled timestamptz;
begin
  if nullif(btrim(p_payload->>'title'),'') is null or length(p_payload->>'title')>500 then raise exception 'title_required'; end if;
  if (p_payload->>'competitionLevel') is null or (p_payload->>'competitionLevel') not in ('internal','club','regional','national','international')
    or (p_payload->>'competitionCategory') is null or (p_payload->>'competitionCategory') not in ('u10','u12','u14','u16','u18','all') then raise exception 'invalid_competition'; end if;
  if v_start is null or v_end is null or v_end<=v_start or v_day is null or v_last is null or v_last<v_day
    or extract(year from v_day)<>extract(year from v_last)
    or (v_start at time zone 'Europe/Zurich')::date<>v_day or (v_end at time zone 'Europe/Zurich')::date<>v_last then raise exception 'invalid_competition_dates'; end if;
  if length(coalesce(p_payload->>'locationText',''))>2000 or length(coalesce(p_payload->>'competitionNote',''))>10000
    or length(coalesce(p_payload->>'externalRegistrationUrl',''))>2000
    or (coalesce(btrim(p_payload->>'externalRegistrationUrl'),'')<>'' and p_payload->>'externalRegistrationUrl' !~* '^https?://[^[:space:]/]+') then raise exception 'invalid_competition'; end if;
  if p_reminder_editable and coalesce((v_reminder->>'enabled')::boolean,false) then
    v_scheduled:=(v_reminder->>'scheduledFor')::timestamptz;
    if v_scheduled is null or v_scheduled<=now() or v_scheduled>=v_start
      or v_reminder->>'channel' is null or v_reminder->>'channel' not in ('in_app','email','both')
      or nullif(btrim(v_reminder->>'messageTemplate'),'') is null or length(v_reminder->>'messageTemplate')>10000 then raise exception 'invalid_reminder'; end if;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.normalize_club_event_attendee_initial_status()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_event_type text;
begin
  select e.event_type into v_event_type
  from public.club_events e
  where e.id = new.event_id;

  if coalesce(v_event_type, '') = 'camp' then
    if new.status is null or new.status = 'expected' then
      new.status := 'not_registered';
    end if;
  elsif coalesce(v_event_type, '') = 'competition' then
    new.status := 'expected';
  elsif new.status is null or new.status = 'expected' then
    new.status := 'present';
  end if;

  return new;
end;
$function$

