CREATE OR REPLACE FUNCTION public.om_recompute_round(p_round_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare actor uuid:=auth.uid(); owner_id uuid; club uuid;
begin
  -- Existing score triggers call this name after a row write. Their write policy
  -- already governs the row; service-role jobs retain their existing path.
  if auth.role()='service_role' or session_user='postgres' or pg_trigger_depth()>0 then
    return public.om_recompute_round_business(p_round_id);
  end if;
  select r.user_id,r.om_organization_id into owner_id,club
    from public.golf_rounds r where r.id=p_round_id;
  if not found or actor is null or not (
    actor=owner_id or exists(select 1 from public.player_guardians g
      where g.player_id=owner_id and g.guardian_user_id=actor
        and coalesce(g.can_view,true) and coalesce(g.can_edit,false))
  ) then raise exception 'Forbidden'; end if;
  if public.legal_required_direct_access(club) is not true then raise exception 'Legal validation required'; end if;
  return public.om_recompute_round_business(p_round_id);
end $function$

CREATE OR REPLACE FUNCTION public.om_recompute_round_business(p_round_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_round public.golf_rounds%rowtype;
  v_comp_level text;
  v_rounds_18_count smallint;
  v_cr numeric(6,1);
  v_sr integer;
  v_gross numeric(8,2);
  v_net numeric(8,2);
  v_coef numeric;
  v_base_brut numeric;
  v_base_net numeric;
  v_bonus_holes_net numeric;
  v_bonus_holes_brut numeric;
  v_bonus_mp_net numeric;
  v_bonus_mp_brut numeric;
  v_bonus_exc_net numeric;
  v_bonus_exc_brut numeric;
  v_total_net numeric;
  v_total_brut numeric;
  v_round_total_score numeric(8,2);
  v_target_org_ids uuid[];
  v_target_org_id uuid;
  v_round_holes_count integer;
  v_is_single_nine boolean := false;
  v_is_double_nine_layout boolean := false;
  v_handicap_for_net numeric(8,2);
begin
  select * into v_round
  from public.golf_rounds
  where id = p_round_id;

  if v_round.id is null then
    return jsonb_build_object('ok', false, 'reason', 'round_not_found');
  end if;

  if v_round.round_type is distinct from 'competition' then
    delete from public.om_tournament_scores where round_id = v_round.id;
    return jsonb_build_object('ok', true, 'reason', 'not_competition');
  end if;

  if v_round.om_organization_id is null
     or v_round.om_competition_format is null then
    delete from public.om_tournament_scores where round_id = v_round.id;
    return jsonb_build_object('ok', true, 'reason', 'missing_core_fields');
  end if;

  if v_round.om_competition_format = 'match_play_individual' then
    v_comp_level := coalesce(v_round.om_competition_level, 'club_official');
    v_rounds_18_count := coalesce(v_round.om_rounds_18_count, 1);
  else
    if v_round.om_competition_level is null or v_round.om_rounds_18_count is null then
      delete from public.om_tournament_scores where round_id = v_round.id;
      return jsonb_build_object('ok', true, 'reason', 'missing_stroke_core_fields');
    end if;
    v_comp_level := v_round.om_competition_level;
    v_rounds_18_count := v_round.om_rounds_18_count;
  end if;

  v_coef := case
    when v_round.om_competition_format = 'match_play_individual' then 1
    else public.om_competition_coefficient(v_comp_level)
  end;

  if v_round.om_competition_format = 'match_play_individual' then
    v_cr := 0;
    v_sr := 0;
    v_gross := 0;
    v_net := 0;
    v_base_net := 0;
    v_base_brut := 0;
    v_bonus_holes_net := 0;
    v_bonus_holes_brut := 0;
    v_bonus_exc_net := 0;
    v_bonus_exc_brut := 0;

    if coalesce(v_round.om_match_result, 'lost') = 'won' then
      v_bonus_mp_net := 10;
      v_bonus_mp_brut := 10;
      v_total_net := 10;
      v_total_brut := 10;
    else
      v_bonus_mp_net := 0;
      v_bonus_mp_brut := 0;
      v_total_net := 0;
      v_total_brut := 0;
    end if;
  else
    if v_round.course_rating is null or v_round.slope_rating is null then
      delete from public.om_tournament_scores where round_id = v_round.id;
      return jsonb_build_object('ok', true, 'reason', 'missing_stroke_fields');
    end if;

    select
      count(*),
      sum(h.score::numeric)
    into v_round_holes_count, v_round_total_score
    from public.golf_round_holes h
    where h.round_id = v_round.id;

    if v_round.total_score is not null then
      v_round_total_score := v_round.total_score::numeric;
    end if;

    if v_round_total_score is null then
      delete from public.om_tournament_scores where round_id = v_round.id;
      return jsonb_build_object('ok', true, 'reason', 'missing_stroke_score');
    end if;

    v_is_single_nine := coalesce(v_rounds_18_count, 1) = 1 and coalesce(v_round_holes_count, 0) = 9;

    if coalesce(v_rounds_18_count, 1) = 1
       and coalesce(v_round_holes_count, 0) = 18
       and coalesce(v_round.course_rating, 0) <= 40 then
      select coalesce(
        bool_and(
          h_front.par is not distinct from h_back.par
          and h_front.stroke_index is not distinct from h_back.stroke_index
        ),
        false
      )
      into v_is_double_nine_layout
      from public.golf_round_holes h_front
      join public.golf_round_holes h_back
        on h_back.round_id = h_front.round_id
       and h_back.hole_no = h_front.hole_no + 9
      where h_front.round_id = v_round.id
        and h_front.hole_no between 1 and 9;
    end if;

    v_cr := round(
      case
        when v_is_single_nine then v_round.course_rating::numeric / 2
        when v_is_double_nine_layout then v_round.course_rating::numeric * 2
        else v_round.course_rating::numeric
      end,
      1
    );
    v_sr :=
      case
        when v_is_single_nine then greatest(1, round(v_round.slope_rating::numeric / 2))::int
        else v_round.slope_rating
      end;

    if coalesce(v_rounds_18_count, 1) > 1
       and nullif(trim(coalesce(v_round.competition_name, '')), '') is not null then
      select
        round(avg(g.score_gross), 2),
        round(avg(g.score_net), 2)
      into v_gross, v_net
      from (
        select
          coalesce(gr.total_score::numeric, sum(h.score::numeric)) as score_gross,
          coalesce(gr.total_score::numeric, sum(h.score::numeric))
            - case
                when coalesce(gr.om_rounds_18_count, 1) = 1
                     and count(h.*) filter (where h.score is not null) = 9
                  then coalesce(gr.handicap_start, 0)::numeric / 2
                else coalesce(gr.handicap_start, 0)::numeric
              end as score_net
        from public.golf_rounds gr
        left join public.golf_round_holes h on h.round_id = gr.id and h.score is not null
        where gr.round_type = 'competition'
          and gr.user_id = v_round.user_id
          and gr.om_organization_id = v_round.om_organization_id
          and gr.om_competition_level = v_comp_level
          and gr.om_competition_format = v_round.om_competition_format
          and gr.om_rounds_18_count = v_rounds_18_count
          and date_trunc('year', gr.start_at) = date_trunc('year', v_round.start_at)
          and lower(trim(coalesce(gr.competition_name, ''))) = lower(trim(coalesce(v_round.competition_name, '')))
        group by gr.id, gr.total_score, gr.handicap_start, gr.om_rounds_18_count
        having coalesce(gr.total_score::numeric, sum(h.score::numeric)) is not null
      ) g;
    else
      v_gross := v_round_total_score;
      v_handicap_for_net :=
        case
          when v_is_single_nine then coalesce(v_round.handicap_start, 0)::numeric / 2
          else coalesce(v_round.handicap_start, 0)::numeric
        end;
      v_net := v_round_total_score - v_handicap_for_net;
    end if;

    if v_gross is null or v_net is null then
      delete from public.om_tournament_scores where round_id = v_round.id;
      return jsonb_build_object('ok', true, 'reason', 'missing_scores_for_average');
    end if;

    v_base_net := 100 + ((v_cr - v_net) * 5);
    v_base_brut := 150 + v_sr + ((v_cr - v_gross) * 5);
    v_base_net := round(v_base_net * v_coef, 2);
    v_base_brut := round(v_base_brut * v_coef, 2);

    v_bonus_holes_net := public.om_holes_bonus_net(v_rounds_18_count);
    v_bonus_holes_brut := public.om_holes_bonus_brut(v_rounds_18_count);
    v_bonus_mp_net := 0;
    v_bonus_mp_brut := 0;
    if coalesce(v_round.om_is_exceptional, false) then
      v_bonus_exc_net := 100;
      v_bonus_exc_brut := 150;
    else
      v_bonus_exc_net := 0;
      v_bonus_exc_brut := 0;
    end if;

    v_total_net := greatest(0, round(v_base_net + v_bonus_holes_net + v_bonus_mp_net + v_bonus_exc_net, 2));
    v_total_brut := round(v_base_brut + v_bonus_holes_brut + v_bonus_mp_brut + v_bonus_exc_brut, 2);
  end if;

  select coalesce(array_agg(distinct cm.club_id order by cm.club_id), '{}'::uuid[])
  into v_target_org_ids
  from public.club_members cm
  where cm.user_id = v_round.user_id
    and cm.role = 'player'
    and cm.is_active = true;

  if not (v_round.om_organization_id = any(v_target_org_ids)) then
    v_target_org_ids := array_append(v_target_org_ids, v_round.om_organization_id);
  end if;

  delete from public.om_tournament_scores
  where round_id = v_round.id;

  foreach v_target_org_id in array v_target_org_ids
  loop
    insert into public.om_tournament_scores (
      round_id, organization_id, player_id, competition_level, competition_format, rounds_18_count, coefficient,
      score_gross, score_net, course_rating, slope_rating,
      base_points_brut, base_points_net,
      bonus_holes_points_brut, bonus_holes_points_net,
      bonus_match_play_points_brut, bonus_match_play_points_net,
      bonus_exceptional_points_brut, bonus_exceptional_points_net,
      total_points_brut, total_points_net, occurred_on, calculated_at
    )
    values (
      v_round.id, v_target_org_id, v_round.user_id, v_comp_level, v_round.om_competition_format, v_rounds_18_count, v_coef,
      round(v_gross, 2), round(v_net, 2), v_cr, v_sr,
      v_base_brut, v_base_net,
      v_bonus_holes_brut, v_bonus_holes_net,
      v_bonus_mp_brut, v_bonus_mp_net,
      v_bonus_exc_brut, v_bonus_exc_net,
      v_total_brut, v_total_net, (v_round.start_at at time zone 'Europe/Zurich')::date, now()
    );
  end loop;

  update public.golf_rounds
  set om_points_net = v_total_net,
      om_points_brut = v_total_brut,
      om_stats_submitted_at = coalesce(om_stats_submitted_at, now())
  where id = v_round.id;

  return jsonb_build_object(
    'ok', true,
    'round_id', v_round.id,
    'organization_ids', to_jsonb(v_target_org_ids),
    'organization_count', coalesce(array_length(v_target_org_ids, 1), 0),
    'player_id', v_round.user_id,
    'score_gross_used', v_gross,
    'score_net_used', v_net,
    'handicap_used_for_net',
      case
        when v_round.om_competition_format = 'match_play_individual' then 0
        when v_is_single_nine then coalesce(v_round.handicap_start, 0)::numeric / 2
        else coalesce(v_round.handicap_start, 0)::numeric
      end,
    'course_rating_used', v_cr,
    'slope_rating_used', v_sr,
    'detected_single_nine', v_is_single_nine,
    'detected_double_nine_layout', v_is_double_nine_layout,
    'total_points_net', v_total_net,
    'total_points_brut', v_total_brut
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.om_sync_bonus_for_attendee(p_event_id uuid, p_player_id uuid, p_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_event record;
  v_bonus_type text;
  v_points numeric(10,2);
  v_occurred_on date;
  v_today date;
begin
  if p_event_id is null or p_player_id is null then
    return;
  end if;

  select
    e.id,
    e.club_id,
    e.event_type,
    e.status,
    e.starts_at
  into v_event
  from public.club_events e
  where e.id = p_event_id;

  if v_event.id is null then
    return;
  end if;

  -- Always clear current derived bonus row first, then possibly reinsert.
  delete from public.om_bonus_entries b
  where b.source_table = 'club_event_attendees'
    and b.source_id = p_event_id
    and b.player_id = p_player_id
    and b.bonus_type in ('training_presence', 'camp_day_presence');

  if coalesce(p_status, '') <> 'present' then
    return;
  end if;

  if coalesce(v_event.status, 'scheduled') <> 'scheduled' then
    return;
  end if;

  if v_event.event_type = 'training' then
    v_bonus_type := 'training_presence';
    v_points := 5;
  elsif v_event.event_type = 'camp' then
    v_bonus_type := 'camp_day_presence';
    v_points := 15;
  else
    return;
  end if;

  v_occurred_on := (v_event.starts_at at time zone 'Europe/Zurich')::date;
  v_today := (now() at time zone 'Europe/Zurich')::date;
  if v_occurred_on > v_today then
    return;
  end if;

  insert into public.om_bonus_entries (
    organization_id,
    player_id,
    bonus_type,
    points_net,
    points_brut,
    source_table,
    source_id,
    description,
    occurred_on,
    created_by
  )
  values (
    v_event.club_id,
    p_player_id,
    v_bonus_type,
    v_points,
    v_points,
    'club_event_attendees',
    p_event_id,
    case
      when v_bonus_type = 'training_presence' then 'Club training attendance'
      else 'Club camp attendance'
    end,
    v_occurred_on,
    null
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.patch_coach_camp_registrations_v1(p_camp_id uuid, p_actor_id uuid, p_registrations jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_camp public.club_camps%rowtype;
  v_existing public.club_camp_players%rowtype;
  v_entry jsonb;
  v_player uuid;
  v_status text;
  v_day record;
  v_key text;
  v_day_status text;
  v_seen uuid[] := '{}';
begin
  select * into v_camp from public.club_camps where id = p_camp_id for update;
  if v_camp.id is null then raise exception 'camp_not_found'; end if;
  if not exists(select 1 from public.club_members where club_id = v_camp.club_id
    and user_id = p_actor_id and is_active and role in ('coach','manager')) then raise exception 'forbidden'; end if;
  if p_registrations is null or jsonb_typeof(p_registrations) <> 'array' or jsonb_array_length(p_registrations) > 1000 then
    raise exception 'invalid_registrations';
  end if;
  -- Lock related rows before any patch; omitted players/days are untouched.
  perform 1 from public.club_camp_days where camp_id = p_camp_id order by day_index for share;
  for v_entry in select * from jsonb_array_elements(p_registrations) loop
    if jsonb_typeof(v_entry) <> 'object' then raise exception 'invalid_registration'; end if;
    v_player := (v_entry->>'player_id')::uuid;
    if v_player is null or v_player = any(v_seen) then raise exception 'invalid_player'; end if;
    v_seen := array_append(v_seen,v_player);
    if not exists(select 1 from public.club_members where club_id = v_camp.club_id and user_id = v_player
      and role = 'player' and is_active) then raise exception 'invalid_player'; end if;
    select * into v_existing from public.club_camp_players where camp_id = p_camp_id and player_id = v_player for update;
    v_status := case when v_entry ? 'registration_status' then v_entry->>'registration_status'
      else coalesce(v_existing.registration_status,'invited') end;
    if v_status is null or v_status not in ('invited','registered','declined') then raise exception 'invalid_registration_status'; end if;
    if v_entry ? 'day_status_by_day_index' and jsonb_typeof(v_entry->'day_status_by_day_index') <> 'object' then
      raise exception 'invalid_day_status';
    end if;
    for v_key,v_day_status in select * from jsonb_each_text(coalesce(v_entry->'day_status_by_day_index','{}'::jsonb)) loop
      if v_day_status is null or v_day_status not in ('present','absent') or not exists (
        select 1 from public.club_camp_days where camp_id = p_camp_id and day_index::text = v_key) then
        raise exception 'invalid_day_status';
      end if;
      if v_status <> 'registered' then raise exception 'day_status_requires_registration'; end if;
    end loop;
    insert into public.club_camp_players(camp_id,player_id,registration_status,registered_at)
      values(p_camp_id,v_player,v_status,case when v_status = 'registered' then coalesce(v_existing.registered_at,now()) end)
      on conflict(camp_id,player_id) do update set registration_status = excluded.registration_status, registered_at = excluded.registered_at;
    for v_day in select event_id,day_index from public.club_camp_days where camp_id = p_camp_id order by day_index loop
      v_day_status := v_entry->'day_status_by_day_index'->>v_day.day_index::text;
      insert into public.club_event_attendees(event_id,player_id,status)
        values(v_day.event_id,v_player,case when v_status = 'registered' then coalesce(v_day_status,'present') else 'not_registered' end)
        on conflict(event_id,player_id) do update set
          status = case when v_day_status is not null then v_day_status
            when club_event_attendees.coach_recorded_status is not null then club_event_attendees.status
            when v_status <> 'registered' then 'not_registered'
            when club_event_attendees.status = 'not_registered' then 'present'
            else club_event_attendees.status end,
          coach_recorded_status = case when v_day_status is not null and club_event_attendees.coach_recorded_status is not null
            then v_day_status else club_event_attendees.coach_recorded_status end,
          coach_recorded_by = case when v_day_status is not null and club_event_attendees.coach_recorded_status is not null
            and club_event_attendees.status is distinct from v_day_status then p_actor_id else club_event_attendees.coach_recorded_by end,
          coach_recorded_at = case when v_day_status is not null and club_event_attendees.coach_recorded_status is not null
            and club_event_attendees.status is distinct from v_day_status then now() else club_event_attendees.coach_recorded_at end;
    end loop;
  end loop;
  return jsonb_build_object('ok',true,'updated_player_ids',to_jsonb(v_seen));
end;
$function$

CREATE OR REPLACE FUNCTION public.prepare_event_evaluation_criterion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_criterion public.club_evaluation_criteria%rowtype;
  v_event_club uuid;
begin
  select * into v_criterion from public.club_evaluation_criteria where id = new.criterion_id;
  select club_id into v_event_club from public.club_events where id = new.event_id;
  if v_criterion.id is null or v_event_club is null or v_criterion.club_id <> v_event_club then
    raise exception 'Criterion and activity must belong to the same club' using errcode = '23514';
  end if;
  if (tg_op = 'INSERT' or new.criterion_id is distinct from old.criterion_id or new.event_id is distinct from old.event_id)
    and (v_criterion.archived_at is not null or not v_criterion.is_active) then
    raise exception 'Inactive or archived criterion cannot be selected' using errcode = '23514';
  end if;
  if (tg_op = 'INSERT' or new.criterion_id is distinct from old.criterion_id or new.event_id is distinct from old.event_id)
    and not exists (select 1 from public.club_events e where e.id = new.event_id and e.event_type = any(v_criterion.activity_types)) then
    raise exception 'Criterion does not apply to this activity type' using errcode = '23514';
  end if;
  if new.is_enabled and (select count(*) from public.club_event_evaluation_criteria x where x.event_id = new.event_id and x.is_enabled and x.id <> new.id) >= 3 then
    raise exception 'Maximum three custom criteria per activity' using errcode = '23514';
  end if;
  new.club_id := v_criterion.club_id;
  if tg_op = 'INSERT' then
    new.snapshot_name := v_criterion.name;
    new.snapshot_description := v_criterion.description;
    new.snapshot_respondent := v_criterion.respondent;
    new.snapshot_response_format := v_criterion.response_format;
    new.snapshot_choices := v_criterion.choices_json;
    new.snapshot_domain_key := v_criterion.domain_key;
    new.snapshot_domain_label := v_criterion.domain_label;
    new.snapshot_is_required := v_criterion.is_required;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.present_legal_document(p_document uuid, p_actor uuid, p_beneficiary uuid, p_role text, p_locale text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d public.legal_documents%rowtype; v public.legal_versions%rowtype; tr jsonb; rendered jsonb; presentation uuid;
  variable text; value text; rendered_title text; rendered_body text; rendered_action text; allowed text[];
begin
  select * into d from public.legal_documents where id=p_document for update;
  if not found or not d.active then raise exception 'Document unavailable'; end if;
  if coalesce(d.applicability->>'rule','')<>'all_members' then raise exception 'Rule engine not configured'; end if;
  if not (p_role=any(d.audience_roles)) or not public.legal_actor_allowed(p_actor,p_beneficiary,d.club_id,p_role) then raise exception 'Forbidden'; end if;
  if d.kind='parent_authorization' and p_actor=p_beneficiary then raise exception 'Child beneficiary required'; end if;
  if p_actor<>p_beneficiary and d.kind<>'parent_authorization' and d.kind<>'specific_consent' then raise exception 'Wrong beneficiary'; end if;
  select * into v from public.legal_versions where document_id=d.id order by version_number desc limit 1;
  if not found then raise exception 'No published version'; end if;
  if public.legal_version_matches_document(d.id,v.id) is not true then raise exception 'Published metadata changed'; end if;
  tr:=v.snapshot->'translations'->p_locale;
  if tr is null or tr->>'status'<>'approved' then raise exception 'Locale unavailable'; end if;
  rendered_title:=tr->>'title'; rendered_body:=tr->>'body'; rendered_action:=tr->>'action_label';
  allowed:=array(select jsonb_array_elements_text(v.snapshot->'allowed_variables'));
  if not public.legal_template_is_valid(coalesce(rendered_title,''),allowed)
    or not public.legal_template_is_valid(coalesce(rendered_body,''),allowed)
    or not public.legal_template_is_valid(coalesce(rendered_action,''),allowed)
  then raise exception 'Published template invalid'; end if;
  foreach variable in array array['child_name','club_name','user_name'] loop
    if variable=any(public.legal_template_variables(rendered_title||rendered_body||coalesce(rendered_action,''))) then
      case variable
        when 'child_name' then
          if p_actor=p_beneficiary then raise exception 'Child variable requires a child beneficiary'; end if;
          select nullif(btrim(concat_ws(' ',first_name,last_name)),'') into value from public.profiles where id=p_beneficiary;
        when 'club_name' then
          if d.club_id is null then raise exception 'Club variable requires a club document'; end if;
          select nullif(btrim(name),'') into value from public.clubs where id=d.club_id;
        when 'user_name' then
          select nullif(btrim(concat_ws(' ',first_name,last_name)),'') into value from public.profiles where id=p_actor;
      end case;
      if value is null or position('{{' in value)>0 or position('}}' in value)>0 then raise exception 'Template value unavailable'; end if;
      rendered_title:=replace(rendered_title,'{{'||variable||'}}',value);
      rendered_body:=replace(rendered_body,'{{'||variable||'}}',value);
      rendered_action:=replace(rendered_action,'{{'||variable||'}}',value);
    end if;
  end loop;
  rendered:=jsonb_build_object('document_id',d.id,'version_id',v.id,'version_number',v.version_number,
    'kind',d.kind,'purpose_key',d.purpose_key,'scope',d.scope,'club_id',d.club_id,'action_kind',d.action_kind,
    'locale',p_locale,'title',rendered_title,'body',rendered_body,'action_label',rendered_action,
    'notice_version_ids','[]'::jsonb);
  insert into public.legal_presentations(actor_id,beneficiary_id,actor_role,authority,document_id,version_id,club_id,locale,rendered_snapshot,rendered_sha256)
  values(p_actor,p_beneficiary,p_role,case when p_actor=p_beneficiary then 'self' else 'verified_representative' end,
    d.id,v.id,d.club_id,p_locale,rendered,encode(extensions.digest(rendered::text,'sha256'),'hex')) returning id into presentation;
  return presentation;
end $function$

