CREATE OR REPLACE FUNCTION public.publish_legal_draft(p_document_id uuid, p_publisher uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d public.legal_documents%rowtype; dr public.legal_drafts%rowtype; loc text; tr jsonb; n integer; v uuid; snap jsonb;
  source_variables text[]; translated_variables text[];
begin
  select * into d from public.legal_documents where id=p_document_id for update;
  if not found then raise exception 'Document missing'; end if;
  select * into dr from public.legal_drafts where document_id=p_document_id for update;
  if not found or length(trim(dr.change_summary))=0 then raise exception 'Change summary required'; end if;
  if d.applicability->>'status'<>'approved' or not exists(select 1 from public.legal_rule_revisions rr where rr.document_id=d.id
    and rr.configuration=d.applicability and rr.reviewed_by is not null and rr.reviewed_at is not null
    and rr.revision=(select max(revision) from public.legal_rule_revisions where document_id=d.id)) then raise exception 'Applicability unapproved'; end if;
  if exists(select 1 from unnest(dr.allowed_variables) as t(variable)
    where variable not in ('child_name','club_name','user_name')) then raise exception 'Unsupported variable'; end if;
  if not ('fr'=any(d.required_locales)) then raise exception 'French source required'; end if;
  source_variables:=public.legal_template_variables(
    coalesce(dr.translations->'fr'->>'title','')||coalesce(dr.translations->'fr'->>'body','')||coalesce(dr.translations->'fr'->>'action_label',''));
  foreach loc in array d.required_locales loop
    tr:=dr.translations->loc;
    if loc not in ('fr','en','de','it') or tr is null or tr->>'status'<>'approved'
       or coalesce((tr->>'source_revision')::integer,-1)<>dr.source_revision
       or length(trim(coalesce(tr->>'title','')))=0 or length(trim(coalesce(tr->>'body','')))=0
       or (d.action_kind<>'read' and length(trim(coalesce(tr->>'action_label','')))=0)
    then raise exception 'Missing or unapproved translation: %',loc; end if;
    if not public.legal_template_is_valid(coalesce(tr->>'title',''),dr.allowed_variables)
      or not public.legal_template_is_valid(coalesce(tr->>'body',''),dr.allowed_variables)
      or not public.legal_template_is_valid(coalesce(tr->>'action_label',''),dr.allowed_variables)
    then raise exception 'Invalid placeholder: %',loc; end if;
    translated_variables:=public.legal_template_variables(coalesce(tr->>'title','')||coalesce(tr->>'body','')||coalesce(tr->>'action_label',''));
    if translated_variables<>source_variables then raise exception 'Placeholder mismatch: %',loc; end if;
  end loop;
  select coalesce(max(version_number),0)+1 into n from public.legal_versions where document_id=d.id;
  snap:=jsonb_build_object('document_key',d.document_key,'kind',d.kind,'purpose_key',d.purpose_key,
    'scope',d.scope,'club_id',d.club_id,'audience_roles',d.audience_roles,'action_kind',d.action_kind,
    'required',d.required,'applicability',d.applicability,'required_locales',d.required_locales,
    'allowed_variables',dr.allowed_variables,'translations',dr.translations,'change_summary',dr.change_summary);
  insert into public.legal_versions(document_id,version_number,snapshot,content_sha256,published_by)
  values(d.id,n,snap,encode(extensions.digest(snap::text,'sha256'),'hex'),p_publisher) returning id into v;
  return v;
end $function$

CREATE OR REPLACE FUNCTION public.publish_legal_draft_checked(p_document_id uuid, p_publisher uuid, p_expected jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d public.legal_documents%rowtype; dr public.legal_drafts%rowtype; latest uuid; actual jsonb;
begin
  if p_expected is null or jsonb_typeof(p_expected)<>'object' then raise exception 'Publication review required'; end if;
  if not exists(select 1 from public.app_admins a where a.user_id=p_publisher) then raise exception 'Platform admin required'; end if;
  select * into d from public.legal_documents where id=p_document_id for update;
  if not found then raise exception 'Document missing'; end if;
  select * into dr from public.legal_drafts where document_id=p_document_id for update;
  if not found then raise exception 'Draft missing'; end if;
  select id into latest from public.legal_versions where document_id=p_document_id order by version_number desc limit 1;
  actual:=jsonb_build_object(
    'document',jsonb_build_object('document_key',d.document_key,'kind',d.kind,'purpose_key',d.purpose_key,
      'scope',d.scope,'club_id',d.club_id,'audience_roles',d.audience_roles,'action_kind',d.action_kind,
      'required',d.required,'active',d.active,'applicability',d.applicability,'required_locales',d.required_locales),
    'draft',jsonb_build_object('source_revision',dr.source_revision,'change_summary',dr.change_summary,
      'allowed_variables',dr.allowed_variables,'translations',dr.translations),
    'latest_version_id',latest);
  if actual is distinct from p_expected then raise exception 'Publication preview changed; reload and review'; end if;
  return public.publish_legal_draft(p_document_id,p_publisher);
end $function$

CREATE OR REPLACE FUNCTION public.queue_player_document_storage_deletion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not exists (
    select 1
    from public.player_dashboard_documents document
    where document.storage_bucket = old.storage_bucket
      and document.storage_path = old.storage_path
  ) then
    insert into public.player_document_storage_deletions (storage_bucket, storage_path)
    values (old.storage_bucket, old.storage_path)
    on conflict (storage_bucket, storage_path) do nothing;
  end if;
  return old;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_legal_rule_revision()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare next_revision integer; reviewer uuid; note text;
begin
  if tg_op='INSERT' then
    insert into public.legal_rule_revisions(document_id,revision,configuration,review_note)
    values(new.id,1,new.applicability,'Unapproved initial rule');
    return new;
  end if;
  if new.applicability is distinct from old.applicability then
    select coalesce(max(revision),0)+1 into next_revision from public.legal_rule_revisions where document_id=new.id;
    reviewer:=nullif(current_setting('app.legal_reviewer',true),'')::uuid;
    note:=coalesce(nullif(current_setting('app.legal_note',true),''),'Unreviewed rule change');
    insert into public.legal_rule_revisions(document_id,revision,configuration,review_note,reviewed_by,reviewed_at)
    values(new.id,next_revision,new.applicability,note,reviewer,case when reviewer is null then null else now() end);
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.remove_manager_parent_v1(p_actor_id uuid, p_club_id uuid, p_member_id uuid, p_expected_player_ids uuid[], p_expected_shared_player_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_parent_id uuid;
  v_players uuid[];
  v_shared uuid[];
  v_removed integer;
  v_admin boolean;
begin
  select exists(select 1 from public.app_admins where user_id = p_actor_id) into v_admin;
  perform 1 from public.club_members where club_id = p_club_id and user_id = p_actor_id
    and role = 'manager' and is_active = true for share;
  if not found and not v_admin then
    raise exception using errcode = '42501', message = 'manager_forbidden';
  end if;
  select user_id into v_parent_id from public.club_members
    where id = p_member_id and club_id = p_club_id and role = 'parent';
  if not found then raise exception using errcode = 'P0002', message = 'parent_not_found'; end if;
  if not v_admin and exists(select 1 from public.app_admins where user_id = v_parent_id) then
    raise exception using errcode = '42501', message = 'protected_account';
  end if;

  -- Same lock order as manage_player_guardian_v1: junior profiles, then parent membership.
  perform 1 from public.profiles p where exists (
    select 1 from public.player_guardians g where g.guardian_user_id = v_parent_id and g.player_id = p.id
  ) order by p.id for update;
  perform 1 from public.club_members where id = p_member_id and role = 'parent' and club_id = p_club_id for update;
  if not found then raise exception using errcode = 'P0002', message = 'parent_not_found'; end if;
  perform 1 from public.club_members m where m.role = 'player' and exists (
    select 1 from public.player_guardians g where g.guardian_user_id = v_parent_id and g.player_id = m.user_id
  ) for share;

  select coalesce(array_agg(g.player_id order by g.player_id), '{}'::uuid[]) into v_players
    from public.player_guardians g where g.guardian_user_id = v_parent_id and exists (
      select 1 from public.club_members m where m.user_id = g.player_id and m.club_id = p_club_id and m.role = 'player'
    );
  select coalesce(array_agg(selected.player_id order by selected.player_id), '{}'::uuid[]) into v_shared
    from unnest(v_players) as selected(player_id)
    where exists(select 1 from public.club_members m where m.user_id = selected.player_id and m.role = 'player' and m.club_id <> p_club_id);
  if p_expected_player_ids is null or p_expected_shared_player_ids is null
    or v_players <> array(select distinct id from unnest(p_expected_player_ids) id order by id)
    or v_shared <> array(select distinct id from unnest(p_expected_shared_player_ids) id order by id) then
    raise exception using errcode = 'PT409', message = 'parent_links_changed';
  end if;

  delete from public.player_guardians where guardian_user_id = v_parent_id
    and player_id = any(v_players) and not (player_id = any(v_shared));
  get diagnostics v_removed = row_count;
  update public.player_periodic_report_configs
    set recipient_user_ids = array_remove(recipient_user_ids, v_parent_id), updated_at = now()
    where v_parent_id = any(recipient_user_ids) and (club_id = p_club_id
      or (player_user_id = any(v_players) and not (player_user_id = any(v_shared))));
  -- Keep delivery history, but prevent unused links issued by this club from being redeemed.
  update public.access_invitation_tokens set consumed_at = now()
    where club_id = p_club_id and consumed_at is null
      and invitation_kind in ('parent_access', 'junior_access')
      and (user_id = v_parent_id or recipient_user_id = v_parent_id);
  delete from public.club_members where id = p_member_id and club_id = p_club_id and role = 'parent';
  return jsonb_build_object('ok', true, 'removed_links', v_removed, 'preserved_shared_links', cardinality(v_shared));
end;
$function$

CREATE OR REPLACE FUNCTION public.require_manager_club_scope_v1(p_actor uuid, p_club uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_actor is null or p_club is null then raise exception 'forbidden' using errcode='42501'; end if;
  if exists(select 1 from public.app_admins where user_id=p_actor) then return; end if;
  perform 1 from public.club_members where club_id=p_club and user_id=p_actor and role='manager' and is_active for share;
  if not found then raise exception 'forbidden' using errcode='42501'; end if;
end $function$

CREATE OR REPLACE FUNCTION public.require_manager_player_scope_v1(p_actor_id uuid, p_club_id uuid, p_player_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform 1 from public.club_members
    where user_id = p_actor_id and club_id = p_club_id and role = 'manager' and is_active = true for share;
  if not found then
    perform 1 from public.app_admins where user_id = p_actor_id for share;
    if not found then raise exception using errcode = '42501', message = 'manager_forbidden'; end if;
  end if;
  -- The profile lock serializes global family-link/consent changes across clubs.
  perform 1 from public.profiles where id = p_player_id for update;
  perform 1 from public.club_members
    where club_id = p_club_id and user_id = p_player_id and role = 'player' and is_active = true for share;
  if not found then raise exception using errcode = 'P0002', message = 'player_not_found'; end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.resolve_legal_withdrawal_conflict(p_document uuid, p_beneficiary uuid, p_club uuid, p_admin uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare current_row public.legal_current_state%rowtype; resolution_id uuid;
begin
  if length(trim(coalesce(p_reason,'')))<20 then raise exception 'Reason required'; end if;
  if not exists(select 1 from public.app_admins a where a.user_id=p_admin) then raise exception 'Platform admin required'; end if;
  perform 1 from public.legal_documents where id=p_document for update;
  if not found then raise exception 'Document missing'; end if;
  select * into current_row from public.legal_current_state
    where document_id=p_document and beneficiary_id=p_beneficiary and scope_key=coalesce(p_club::text,'platform') for update;
  if not found or not current_row.conflict then raise exception 'No withdrawal conflict'; end if;
  insert into public.legal_conflict_resolutions(document_id,beneficiary_id,club_scope,prior_decision_id,resolved_by,reason)
  values(p_document,p_beneficiary,p_club,current_row.decision_id,p_admin,p_reason) returning id into resolution_id;
  update public.legal_current_state set conflict=false
    where document_id=p_document and beneficiary_id=p_beneficiary and scope_key=coalesce(p_club::text,'platform');
  return resolution_id;
end $function$

CREATE OR REPLACE FUNCTION public.review_legal_applicability(p_document uuid, p_reviewer uuid, p_configuration jsonb, p_note text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if length(trim(p_note))<20 or p_configuration->>'status'<>'approved' then raise exception 'Reviewed rationale required'; end if;
  perform set_config('app.legal_reviewer',p_reviewer::text,true);
  perform set_config('app.legal_note',p_note,true);
  update public.legal_documents set applicability=p_configuration where id=p_document and applicability is distinct from p_configuration;
  if not found then raise exception 'Missing document or unchanged rule'; end if;
end $function$

CREATE OR REPLACE FUNCTION public.review_legal_data_request(p_request uuid, p_actor uuid, p_status text, p_note text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare previous text;
begin
  if p_status not in ('identity_check','in_review','resolved','rejected') or length(trim(p_note))<10 then raise exception 'Invalid review'; end if;
  select status into previous from public.legal_data_requests where id=p_request for update;
  if not found then raise exception 'Request missing'; end if;
  update public.legal_data_requests set status=p_status,
    closed_at=case when p_status in ('resolved','rejected') then now() else null end where id=p_request;
  insert into public.legal_data_request_events(request_id,actor_id,from_status,to_status,note)
  values(p_request,p_actor,previous,p_status,p_note);
end $function$

CREATE OR REPLACE FUNCTION public.review_legal_representative(p_guardian uuid, p_child uuid, p_club uuid, p_status text, p_basis text, p_admin uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare assertion_id uuid; previous text;
begin
  if p_status not in ('verified','revoked') or length(trim(coalesce(p_basis,'')))<20 then raise exception 'Reviewed basis required'; end if;
  if not exists(select 1 from public.app_admins a where a.user_id=p_admin) then raise exception 'Platform admin required'; end if;
  if p_status='verified' then
    if not exists(select 1 from public.player_guardians g where g.guardian_user_id=p_guardian and g.player_id=p_child and g.can_edit)
      or not exists(select 1 from public.club_members m where m.user_id=p_guardian and m.club_id=p_club and m.role='parent' and m.is_active)
      or not exists(select 1 from public.club_members m where m.user_id=p_child and m.club_id=p_club and m.role='player' and m.is_active)
    then raise exception 'Current family access is not sufficient'; end if;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('legal_rep:'||p_guardian::text||':'||p_child::text||':'||p_club::text,0));
  select id,status into assertion_id,previous from public.legal_representative_assertions
    where guardian_id=p_guardian and child_id=p_child and club_id=p_club for update;
  if assertion_id is null and p_status='revoked' then raise exception 'Assertion missing'; end if;
  if assertion_id is null then
    insert into public.legal_representative_assertions(guardian_id,child_id,club_id,status,basis,verified_by,verified_at)
    values(p_guardian,p_child,p_club,p_status,p_basis,p_admin,now()) returning id into assertion_id;
  else
    update public.legal_representative_assertions set status=p_status,basis=p_basis,verified_by=p_admin,
      verified_at=case when p_status='verified' then now() else null end where id=assertion_id;
  end if;
  insert into public.legal_representative_events(assertion_id,guardian_id,child_id,club_id,prior_status,new_status,review_basis,reviewed_by)
  values(assertion_id,p_guardian,p_child,p_club,previous,p_status,p_basis,p_admin);
  return assertion_id;
end $function$

CREATE OR REPLACE FUNCTION public.save_coach_training_debrief(p_event_id uuid, p_coach_id uuid, p_report_text text, p_report_scope text, p_reviews jsonb, p_update_report boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_event public.club_events%rowtype;
  v_debrief_id uuid;
  v_review jsonb;
  v_player_id uuid;
  v_status text;
  v_engagement integer;
  v_attitude integer;
  v_performance integer;
  v_attendee_count integer;
  v_review_count integer;
  v_unique_review_count integer;
begin
  if not public.can_manage_coach_event(p_event_id, p_coach_id) then
    raise exception 'forbidden';
  end if;

  select * into v_event
  from public.club_events
  where id = p_event_id
  for update;

  if v_event.id is null then
    raise exception 'event_not_found';
  end if;
  if v_event.event_type <> 'training' then
    raise exception 'training_only';
  end if;
  if v_event.status = 'cancelled' then
    raise exception 'event_cancelled';
  end if;
  if p_update_report and not public.is_coach_training_assistance_enabled(v_event.club_id) then
    raise exception 'coach_training_assistance_disabled';
  end if;
  if p_update_report is not true and btrim(coalesce(p_report_text, '')) <> '' then
    raise exception 'report_update_not_allowed';
  end if;
  if coalesce(
    v_event.ends_at,
    v_event.starts_at + make_interval(mins => coalesce(v_event.duration_minutes, 0))
  ) > now() then
    raise exception 'event_not_finished';
  end if;
  if char_length(coalesce(p_report_text, '')) > 10000 then
    raise exception 'report_too_long';
  end if;
  if p_report_scope not in ('collective', 'individual', 'mixed') then
    raise exception 'invalid_report_scope';
  end if;
  if jsonb_typeof(coalesce(p_reviews, '[]'::jsonb)) <> 'array' then
    raise exception 'invalid_reviews';
  end if;

  select count(*) into v_attendee_count
  from public.club_event_attendees
  where event_id = p_event_id;

  select count(*), count(distinct (value ->> 'player_id'))
  into v_review_count, v_unique_review_count
  from jsonb_array_elements(coalesce(p_reviews, '[]'::jsonb));

  if v_review_count <> v_attendee_count or v_unique_review_count <> v_attendee_count then
    raise exception 'all_attendees_required';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(coalesce(p_reviews, '[]'::jsonb)) item
    left join public.club_event_attendees a
      on a.event_id = p_event_id
     and a.player_id::text = item.value ->> 'player_id'
    where a.player_id is null
  ) then
    raise exception 'unknown_attendee';
  end if;

  if p_update_report then
    select id into v_debrief_id
    from public.coach_training_debriefs
    where event_id = p_event_id
    for update;

    if v_debrief_id is null then
      insert into public.coach_training_debriefs (
        event_id, organization_id, report_text, report_scope, author_coach_id
      ) values (
        p_event_id,
        v_event.club_id,
        nullif(btrim(coalesce(p_report_text, '')), ''),
        p_report_scope,
        p_coach_id
      )
      returning id into v_debrief_id;
    else
      update public.coach_training_debriefs
      set report_text = nullif(btrim(coalesce(p_report_text, '')), ''),
          report_scope = p_report_scope,
          report_version = case
            when coalesce(report_text, '') is distinct from coalesce(nullif(btrim(coalesce(p_report_text, '')), ''), '')
              then report_version + 1
            else report_version
          end,
          author_coach_id = p_coach_id,
          updated_at = now()
      where id = v_debrief_id;
    end if;
  end if;

  for v_review in
    select value from jsonb_array_elements(coalesce(p_reviews, '[]'::jsonb))
  loop
    v_player_id := (v_review ->> 'player_id')::uuid;
    v_status := v_review ->> 'status';
    v_engagement := nullif(v_review ->> 'engagement', '')::integer;
    v_attitude := nullif(v_review ->> 'attitude', '')::integer;
    v_performance := nullif(v_review ->> 'performance', '')::integer;

    if v_status is null or v_status not in ('present', 'absent') then
      raise exception 'attendance_required';
    end if;
    if v_status = 'present' and (
      v_engagement is null
      or v_attitude is null
      or v_performance is null
      or v_engagement not between 1 and 6
      or v_attitude not between 1 and 6
      or v_performance not between 1 and 6
    ) then
      raise exception 'ratings_required';
    end if;

    update public.club_event_attendees
    set status = v_status,
        coach_recorded_status = v_status,
        coach_recorded_by = p_coach_id,
        coach_recorded_at = now()
    where event_id = p_event_id
      and player_id = v_player_id;

    delete from public.club_event_coach_feedback
    where event_id = p_event_id
      and player_id = v_player_id;

    if v_status = 'present' then
      insert into public.club_event_coach_feedback (
        event_id,
        player_id,
        coach_id,
        engagement,
        attitude,
        performance,
        visible_to_player,
        private_note,
        player_note
      ) values (
        p_event_id,
        v_player_id,
        p_coach_id,
        v_engagement,
        v_attitude,
        v_performance,
        true,
        null,
        null
      );
    end if;
  end loop;

  return v_debrief_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_coach_training_debrief_v2(p_event_id uuid, p_coach_id uuid, p_source_text text, p_report_scope text, p_collective_summary_text text, p_individual_comments jsonb, p_reviews jsonb, p_update_report boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_event public.club_events%rowtype;
  v_debrief_id uuid;
  v_existing public.coach_training_debriefs%rowtype;
  v_comments jsonb := coalesce(p_individual_comments, '{}'::jsonb);
  v_review jsonb;
  v_player_id uuid;
  v_status text;
  v_engagement integer;
  v_attitude integer;
  v_performance integer;
  v_attendee_count integer;
  v_review_count integer;
  v_unique_review_count integer;
begin
  if not public.can_manage_coach_event(p_event_id, p_coach_id) then
    raise exception 'forbidden';
  end if;

  select * into v_event
  from public.club_events
  where id = p_event_id
  for update;

  if v_event.id is null then raise exception 'event_not_found'; end if;
  if v_event.event_type <> 'training' then raise exception 'training_only'; end if;
  if v_event.status = 'cancelled' then raise exception 'event_cancelled'; end if;
  if p_update_report and not public.is_coach_training_assistance_enabled(v_event.club_id) then
    raise exception 'coach_training_assistance_disabled';
  end if;
  if p_update_report is not true and (
    btrim(coalesce(p_source_text, '')) <> ''
    or btrim(coalesce(p_collective_summary_text, '')) <> ''
    or v_comments <> '{}'::jsonb
  ) then
    raise exception 'report_update_not_allowed';
  end if;
  if coalesce(
    v_event.ends_at,
    v_event.starts_at + make_interval(mins => coalesce(v_event.duration_minutes, 0))
  ) > now() then
    raise exception 'event_not_finished';
  end if;
  if char_length(coalesce(p_source_text, '')) > 10000 then raise exception 'report_too_long'; end if;
  if char_length(coalesce(p_collective_summary_text, '')) > 10000 then
    raise exception 'collective_summary_too_long';
  end if;
  if p_report_scope not in ('collective', 'individual') then raise exception 'invalid_report_scope'; end if;
  if jsonb_typeof(v_comments) <> 'object' then raise exception 'invalid_individual_comments'; end if;
  if exists (
    select 1
    from jsonb_each_text(v_comments) item
    left join public.club_event_attendees attendee
      on attendee.event_id = p_event_id
     and attendee.player_id::text = item.key
    where attendee.player_id is null
       or char_length(btrim(item.value)) > 4000
  ) then
    raise exception 'invalid_individual_comments';
  end if;
  if jsonb_typeof(coalesce(p_reviews, '[]'::jsonb)) <> 'array' then raise exception 'invalid_reviews'; end if;

  select count(*) into v_attendee_count
  from public.club_event_attendees
  where event_id = p_event_id;

  select count(*), count(distinct (value ->> 'player_id'))
  into v_review_count, v_unique_review_count
  from jsonb_array_elements(coalesce(p_reviews, '[]'::jsonb));

  if v_review_count <> v_attendee_count or v_unique_review_count <> v_attendee_count then
    raise exception 'all_attendees_required';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(coalesce(p_reviews, '[]'::jsonb)) item
    left join public.club_event_attendees attendee
      on attendee.event_id = p_event_id
     and attendee.player_id::text = item.value ->> 'player_id'
    where attendee.player_id is null
  ) then
    raise exception 'unknown_attendee';
  end if;

  if p_update_report then
    select * into v_existing
    from public.coach_training_debriefs
    where event_id = p_event_id
    for update;

    if v_existing.id is null then
      insert into public.coach_training_debriefs (
        event_id,
        organization_id,
        report_text,
        report_scope,
        collective_summary_text,
        individual_comments,
        author_coach_id
      ) values (
        p_event_id,
        v_event.club_id,
        nullif(btrim(coalesce(p_source_text, '')), ''),
        p_report_scope,
        nullif(btrim(coalesce(p_collective_summary_text, '')), ''),
        v_comments,
        p_coach_id
      )
      returning id into v_debrief_id;
    else
      update public.coach_training_debriefs
      set report_text = nullif(btrim(coalesce(p_source_text, '')), ''),
          report_scope = p_report_scope,
          collective_summary_text = nullif(btrim(coalesce(p_collective_summary_text, '')), ''),
          individual_comments = v_comments,
          report_version = case
            when coalesce(v_existing.report_text, '') is distinct from coalesce(nullif(btrim(coalesce(p_source_text, '')), ''), '')
              or coalesce(v_existing.individual_comments, '{}'::jsonb) is distinct from v_comments
            then v_existing.report_version + 1
            else v_existing.report_version
          end,
          author_coach_id = p_coach_id,
          updated_at = now()
      where id = v_existing.id
      returning id into v_debrief_id;
    end if;
  end if;

  for v_review in
    select value from jsonb_array_elements(coalesce(p_reviews, '[]'::jsonb))
  loop
    v_player_id := (v_review ->> 'player_id')::uuid;
    v_status := v_review ->> 'status';
    v_engagement := nullif(v_review ->> 'engagement', '')::integer;
    v_attitude := nullif(v_review ->> 'attitude', '')::integer;
    v_performance := nullif(v_review ->> 'performance', '')::integer;

    if v_status is null or v_status not in ('present', 'absent') then raise exception 'attendance_required'; end if;
    if v_status = 'present' and (
      v_engagement is null
      or v_attitude is null
      or v_performance is null
      or v_engagement not between 1 and 6
      or v_attitude not between 1 and 6
      or v_performance not between 1 and 6
    ) then
      raise exception 'ratings_required';
    end if;

    update public.club_event_attendees
    set status = v_status,
        coach_recorded_status = v_status,
        coach_recorded_by = p_coach_id,
        coach_recorded_at = now()
    where event_id = p_event_id
      and player_id = v_player_id;

    delete from public.club_event_coach_feedback
    where event_id = p_event_id
      and player_id = v_player_id;

    if v_status = 'present' then
      insert into public.club_event_coach_feedback (
        event_id, player_id, coach_id, engagement, attitude, performance,
        visible_to_player, private_note, player_note
      ) values (
        p_event_id, v_player_id, p_coach_id, v_engagement, v_attitude, v_performance,
        true, null, null
      );
    end if;
  end loop;

  return v_debrief_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_coach_training_player_evaluation_v1(p_event_id uuid, p_coach_id uuid, p_player_id uuid, p_status text, p_engagement integer, p_attitude integer, p_performance integer, p_source_text text, p_private_note text, p_update_comment boolean)
