  ) then raise exception 'ratings_required'; end if;
  if char_length(v_source_text) > 4000 then raise exception 'individual_comment_too_long'; end if;
  if char_length(v_private_note) > 4000 then raise exception 'invalid_note'; end if;
  if p_status = 'absent' and (v_source_text <> '' or v_private_note <> '') then
    raise exception 'absent_comment_not_allowed';
  end if;

  update public.club_event_attendees
  set status = p_status,
      coach_recorded_status = p_status,
      coach_recorded_by = p_coach_id,
      coach_recorded_at = now()
  where event_id = p_event_id
    and player_id = p_player_id;

  delete from public.club_event_coach_feedback
  where event_id = p_event_id
    and player_id = p_player_id;

  if p_status = 'present' then
    insert into public.club_event_coach_feedback (
      event_id, player_id, coach_id, engagement, attitude, performance,
      visible_to_player, private_note, player_note
    ) values (
      p_event_id, p_player_id, p_coach_id, p_engagement, p_attitude, p_performance,
      true, nullif(v_private_note, ''), nullif(v_source_text, '')
    );

    select * into v_debrief
    from public.coach_training_debriefs
    where event_id = p_event_id
    for update;

    if v_debrief.id is null and v_source_text <> '' then
      v_comments := jsonb_build_object(p_player_id::text, v_source_text);
      insert into public.coach_training_debriefs (
        event_id, organization_id, report_text, report_scope,
        collective_summary_text, individual_comments, report_version, author_coach_id
      ) values (
        p_event_id, v_event.club_id, null, 'individual',
        null, v_comments, 1, p_coach_id
      )
      returning id, report_version into v_debrief_id, v_report_version;
    elsif v_debrief.id is not null then
      v_comments := coalesce(v_debrief.individual_comments, '{}'::jsonb);
      v_comments := case
        when v_source_text = '' then v_comments - p_player_id::text
        else jsonb_set(v_comments, array[p_player_id::text], to_jsonb(v_source_text), true)
      end;

      update public.coach_training_debriefs
      set individual_comments = v_comments,
          report_version = case
            when coalesce(v_debrief.individual_comments, '{}'::jsonb) is distinct from v_comments
              then v_debrief.report_version + 1
            else v_debrief.report_version
          end,
          author_coach_id = p_coach_id,
          updated_at = now()
      where id = v_debrief.id
      returning id, report_version into v_debrief_id, v_report_version;
    end if;
  end if;

  return jsonb_build_object(
    'debrief_id', v_debrief_id,
    'report_version', v_report_version,
    'note_inserted', false
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.save_coach_training_player_evaluation_v2(p_event_id uuid, p_coach_id uuid, p_player_id uuid, p_status text, p_engagement integer, p_attitude integer, p_performance integer, p_source_text text, p_private_note text, p_update_comment boolean, p_expected_recorded_at timestamp with time zone, p_custom_responses jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_event public.club_events%rowtype;
  v_attendee public.club_event_attendees%rowtype;
  v_criterion public.club_event_evaluation_criteria%rowtype;
  v_answer jsonb;
  v_key text;
  v_result jsonb;
begin
  select * into v_event from public.club_events where id = p_event_id for update;
  if v_event.id is null then raise exception 'event_not_found'; end if;
  if not public.can_manage_coach_event(p_event_id, p_coach_id) then raise exception 'forbidden'; end if;
  if v_event.requires_evaluation = false then raise exception 'evaluation_disabled'; end if;
  select * into v_attendee from public.club_event_attendees
    where event_id = p_event_id and player_id = p_player_id for update;
  if v_attendee.player_id is null then raise exception 'unknown_attendee'; end if;
  if v_attendee.coach_recorded_at is distinct from p_expected_recorded_at then raise exception 'evaluation_conflict'; end if;
  if p_custom_responses is null or jsonb_typeof(p_custom_responses) <> 'object' then raise exception 'invalid_custom_responses'; end if;

  -- Validate the entire submission before touching feedback, presence or answers.
  perform 1 from public.club_event_evaluation_criteria where event_id = p_event_id for share;
  for v_key in select jsonb_object_keys(p_custom_responses) loop
    if not exists (select 1 from public.club_event_evaluation_criteria
      where id::text = v_key and event_id = p_event_id and is_enabled and snapshot_respondent in ('coach','both')) then
      raise exception 'invalid_custom_criterion';
    end if;
  end loop;
  if p_status = 'present' then
    for v_criterion in select * from public.club_event_evaluation_criteria
      where event_id = p_event_id and is_enabled and snapshot_respondent in ('coach','both') loop
      v_answer := p_custom_responses -> v_criterion.id::text;
      if v_answer is null or v_answer = 'null'::jsonb or v_answer = '""'::jsonb then
        if v_criterion.snapshot_is_required then raise exception 'required_criteria_missing'; end if;
      elsif v_criterion.snapshot_response_format = 'short_text' then
        if jsonb_typeof(v_answer) <> 'string' or char_length(btrim(v_answer #>> '{}')) not between 1 and 240 then
          raise exception 'invalid_custom_response';
        end if;
      elsif not exists (select 1 from jsonb_array_elements(v_criterion.snapshot_choices) choice where choice->'value' = v_answer) then
        raise exception 'invalid_custom_response';
      end if;
    end loop;
  end if;

  v_result := public.save_coach_training_player_evaluation_v1(p_event_id, p_coach_id, p_player_id,
    p_status, p_engagement, p_attitude, p_performance, p_source_text, p_private_note, p_update_comment);
  delete from public.club_event_evaluation_responses r where r.event_id = p_event_id and r.player_id = p_player_id
    and r.respondent_role = 'coach' and (p_status = 'absent' or exists (
      select 1 from public.club_event_evaluation_criteria c where c.id = r.event_criterion_id and c.is_enabled));
  if p_status = 'present' then
    insert into public.club_event_evaluation_responses
      (club_id,event_id,event_criterion_id,player_id,respondent_user_id,respondent_role,value_json)
    select v_event.club_id,p_event_id,c.id,p_player_id,p_coach_id,'coach',p_custom_responses->c.id::text
    from public.club_event_evaluation_criteria c where c.event_id = p_event_id and c.is_enabled
      and c.snapshot_respondent in ('coach','both') and p_custom_responses ? c.id::text
      and p_custom_responses->c.id::text not in ('null'::jsonb,'""'::jsonb);
  else
    -- An explicit absence must not resurrect an old junior-visible comment on reload.
    update public.coach_training_debriefs set individual_comments = individual_comments - p_player_id::text,
      report_version = report_version + 1, updated_at = now(), author_coach_id = p_coach_id
      where event_id = p_event_id and individual_comments ? p_player_id::text;
  end if;
  return v_result || jsonb_build_object('recorded_at', (select coach_recorded_at from public.club_event_attendees
    where event_id = p_event_id and player_id = p_player_id));
end;
$function$

CREATE OR REPLACE FUNCTION public.save_manager_camp_v1(p_actor uuid, p_camp uuid, p_club uuid, p_expected_version text, p_values jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  camp public.club_camps%rowtype; old_day public.club_camp_days%rowtype; day jsonb; opt jsonb; reg jsonb; assignment jsonb;
  groups uuid[]; players uuid[]; coaches uuid[]; day_coaches uuid[]; head_coach uuid; season uuid; primary_group uuid;
  incoming_events uuid[]; removed uuid[]; kept_options uuid[] := '{}'; assignment_ids uuid[]; day_indexes int[];
  v_event_id uuid; v_option_id uuid; player uuid; start_time timestamptz; end_time timestamptz; v_day_index int := 0; pos int := 0;
  reg_status text; day_status text; input_kind text; v_choices jsonb; option_capacity int; quantity_sum int; inserted int;
  new_camp boolean := p_camp is null; days_result jsonb := '[]';
begin
  if new_camp then
    perform public.require_manager_club_scope_v1(p_actor,p_club);
    insert into public.club_camps(club_id,title,created_by,status) values(p_club,btrim(p_values->>'title'),p_actor,'draft') returning * into camp;
  else
    select * into camp from public.club_camps where id=p_camp for update;
    if not found then raise exception 'camp_not_found' using errcode='P0002'; end if;
    perform public.require_manager_club_scope_v1(p_actor,camp.club_id);
    -- Lock children before comparing the version. Player registration/option
    -- submissions which happened after opening the editor cause a safe conflict.
    perform 1 from public.club_events where id in(select d.event_id from public.club_camp_days d where camp_id=camp.id) order by id for update;
    perform 1 from public.club_camp_players where camp_id=camp.id for update;
    perform 1 from public.club_camp_options where camp_id=camp.id for update;
    perform 1 from public.club_camp_days where camp_id=camp.id for update;
    perform 1 from public.club_event_attendees where club_event_attendees.event_id in(select d.event_id from public.club_camp_days d where camp_id=camp.id) for update;
    perform 1 from public.club_camp_player_options where club_camp_player_options.option_id in(select o.id from public.club_camp_options o where camp_id=camp.id) for update;
    if p_expected_version is null or public.manager_camp_version_v1(camp.id)<>p_expected_version then
      raise exception 'camp_conflict' using errcode='PT409';
    end if;
  end if;
  groups := array(select distinct value::uuid from jsonb_array_elements_text(p_values->'group_ids'));
  players := array(select distinct value::uuid from jsonb_array_elements_text(p_values->'player_ids'));
  head_coach := nullif(p_values->>'head_coach_user_id','')::uuid;
  season := nullif(p_values->>'season_id','')::uuid;
  coaches := array(select distinct x from (
    select value::uuid x from jsonb_array_elements_text(p_values->'coach_ids')
    union select head_coach union select nullif(d->>'responsible_coach_id','')::uuid from jsonb_array_elements(p_values->'days') d
    union select c.value::uuid from jsonb_array_elements(p_values->'days') d cross join lateral jsonb_array_elements_text(d->'coach_ids') c) c where x is not null);
  if nullif(btrim(p_values->>'title'),'') is null or p_values->>'status' not in ('draft','scheduled','cancelled')
    or jsonb_typeof(p_values->'days') is distinct from 'array' or jsonb_array_length(p_values->'days')>80
    or (p_values->>'status'<>'draft' and (head_coach is null or (cardinality(groups)=0 and cardinality(players)=0) or jsonb_array_length(p_values->'days')=0))
    or (jsonb_array_length(p_values->'days')>0 and head_coach is null) then raise exception 'invalid_camp' using errcode='22023'; end if;
  if season is not null and not exists(select 1 from public.club_seasons where id=season and club_id=camp.club_id) then raise exception 'invalid_season' using errcode='22023'; end if;
  if exists(select 1 from unnest(groups) x where not exists(select 1 from public.coach_groups g where g.id=x and g.club_id=camp.club_id
    and (season is null or g.club_season_id is null or g.club_season_id=season)))
    or exists(select 1 from unnest(players) x where not exists(select 1 from public.club_members m where m.club_id=camp.club_id and m.user_id=x and m.role='player' and m.is_active)
      and not exists(select 1 from public.club_camp_players cp where cp.camp_id=camp.id and cp.player_id=x))
    or exists(select 1 from unnest(coaches) x where not exists(select 1 from public.club_members m where m.club_id=camp.club_id and m.user_id=x and m.role in ('coach','manager') and m.is_active)
      and not exists(select 1 from public.club_camp_coaches cc where cc.camp_id=camp.id and cc.coach_id=x)) then
    raise exception 'invalid_assignments' using errcode='22023';
  end if;
  incoming_events := array(select nullif(d->>'event_id','')::uuid from jsonb_array_elements(p_values->'days') d where nullif(d->>'event_id','') is not null);
  if cardinality(incoming_events)<>(select count(distinct x) from unnest(incoming_events) x)
    or exists(select 1 from unnest(incoming_events) x where not exists(select 1 from public.club_camp_days d where d.camp_id=camp.id and d.event_id=x)) then
    raise exception 'invalid_days' using errcode='22023';
  end if;
  removed := array(select cp.player_id from public.club_camp_players cp where cp.camp_id=camp.id and not(cp.player_id=any(players)));
  if exists(select 1 from public.club_camp_days d join public.club_events e on e.id=d.event_id where d.camp_id=camp.id and (
      exists(select 1 from public.club_event_attendees a where a.event_id=e.id and a.player_id=any(removed)
        and (coalesce(e.ends_at,e.starts_at)<now() or a.coach_recorded_status is not null or a.status in ('absent','excused','present')))
      or exists(select 1 from public.club_event_coach_feedback f where f.event_id=e.id and f.player_id=any(removed))
      or exists(select 1 from public.club_event_player_feedback f where f.event_id=e.id and f.player_id=any(removed))
      or exists(select 1 from public.club_event_evaluation_responses f where f.event_id=e.id and f.player_id=any(removed))
      or exists(select 1 from public.club_event_player_structure_items f where f.event_id=e.id and f.player_id=any(removed))
      or exists(select 1 from public.coach_player_private_notes f where f.event_id=e.id and f.player_id=any(removed))))
    or exists(select 1 from public.club_camp_player_options po join public.club_camp_options o on o.id=po.option_id where o.camp_id=camp.id and po.player_id=any(removed)) then
    raise exception 'camp_history_removal' using errcode='23000';
  end if;
  for old_day in select * from public.club_camp_days d where d.camp_id=camp.id and not(d.event_id=any(incoming_events)) loop
    if exists(select 1 from public.club_event_attendees a where a.event_id=old_day.event_id and (a.coach_recorded_status is not null or a.status in ('present','absent','excused')))
      or exists(select 1 from public.club_event_coach_feedback f where f.event_id=old_day.event_id)
      or exists(select 1 from public.club_event_player_feedback f where f.event_id=old_day.event_id)
      or exists(select 1 from public.club_event_evaluation_responses f where f.event_id=old_day.event_id)
      or exists(select 1 from public.club_event_player_structure_items f where f.event_id=old_day.event_id)
      or exists(select 1 from public.coach_player_private_notes f where f.event_id=old_day.event_id)
      or exists(select 1 from public.message_threads f where f.event_id=old_day.event_id)
      or exists(select 1 from public.club_camp_option_days f where f.camp_day_id=old_day.id)
      or exists(select 1 from public.training_sessions f where f.club_event_id=old_day.event_id) then
      raise exception 'camp_history_removal' using errcode='23000';
    end if;
    -- Keep the event and any overlooked dependencies; cancel instead of deleting.
    update public.club_events set status='cancelled' where id=old_day.event_id;
    delete from public.club_camp_days where id=old_day.id;
  end loop;
  if cardinality(groups)=0 and jsonb_array_length(p_values->'days')>0 then
    insert into public.coach_groups(club_id,club_season_id,name,is_active,head_coach_user_id)
      values(camp.club_id,season,'Groupe spécifique',true,head_coach) returning id into primary_group;
    groups := array[primary_group];
    insert into public.coach_group_players(group_id,player_user_id) select primary_group,x from unnest(players) x;
    insert into public.coach_group_coaches(group_id,coach_user_id,is_head) select primary_group,x,x=head_coach from unnest(coaches) x;
  else primary_group := groups[1]; end if;
  update public.club_camps set title=btrim(p_values->>'title'),notes=nullif(p_values->>'notes',''),image_url=nullif(p_values->>'image_url',''),
    capacity=(p_values->>'capacity')::int,head_coach_user_id=head_coach,season_id=season,status=p_values->>'status',archived_at=null,
    participants_snapshot_at=case when cardinality(players)>0 then now() else null end,updated_at=now() where id=camp.id;
  delete from public.club_camp_groups where camp_id=camp.id and not(group_id=any(groups));
  insert into public.club_camp_groups(camp_id,group_id) select camp.id,x from unnest(groups) x on conflict do nothing;
  delete from public.club_camp_coaches where camp_id=camp.id and not(coach_id=any(coaches));
  insert into public.club_camp_coaches(camp_id,coach_id,is_head) select camp.id,x,x=head_coach from unnest(coaches) x
    on conflict(camp_id,coach_id) do update set is_head=excluded.is_head;
  delete from public.club_camp_players where camp_id=camp.id and player_id=any(removed);
  insert into public.club_camp_players(camp_id,player_id,registration_status) select camp.id,x,'invited' from unnest(players) x on conflict do nothing;
  for reg in select value from jsonb_array_elements(p_values->'player_registrations') loop
    player := (reg->>'player_id')::uuid; reg_status := reg->>'registration_status';
    if not(player=any(players)) or reg_status not in ('invited','registered','declined') then raise exception 'invalid_registration' using errcode='22023'; end if;
    update public.club_camp_players set registration_status=reg_status,
      registered_at=case when reg_status='registered' then coalesce(registered_at,now()) else null end
      where camp_id=camp.id and player_id=player;
  end loop;
  -- Reordering keeps both day and event IDs; negative indexes are transactional.
  update public.club_camp_days d set day_index=-100000-d.day_index where d.camp_id=camp.id;
  for day in select value from jsonb_array_elements(p_values->'days') loop
    v_event_id := nullif(day->>'event_id','')::uuid;
    start_time := (day->>'starts_at')::timestamptz; end_time := (day->>'ends_at')::timestamptz;
    if start_time is null or end_time is null or end_time<=start_time then raise exception 'invalid_days' using errcode='22023'; end if;
    day_coaches := array(select distinct x from (select head_coach x union select nullif(day->>'responsible_coach_id','')::uuid
      union select value::uuid from jsonb_array_elements_text(day->'coach_ids')) q where x is not null);
    if v_event_id is null then
      insert into public.club_events(club_id,group_id,event_type,title,starts_at,ends_at,duration_minutes,location_text,coach_note,status,requires_evaluation,created_by)
        values(camp.club_id,primary_group,'camp',btrim(p_values->>'title'),start_time,end_time,least(300,round(extract(epoch from(end_time-start_time))/60)::int),
          nullif(day->>'location_text',''),nullif(day->>'practical_info',''),'scheduled',coalesce((day->>'evaluation_enabled')::boolean,false),p_actor) returning id into v_event_id;
      insert into public.club_camp_days(camp_id,event_id,day_index) values(camp.id,v_event_id,v_day_index);
      old_day := null;
    else
      select * into old_day from public.club_camp_days d where d.event_id=v_event_id and d.camp_id=camp.id;
      update public.club_events e set group_id=primary_group,title=btrim(p_values->>'title'),starts_at=start_time,ends_at=end_time,
        duration_minutes=least(300,round(extract(epoch from(end_time-start_time))/60)::int),location_text=nullif(day->>'location_text',''),
        coach_note=nullif(day->>'practical_info',''),requires_evaluation=coalesce((day->>'evaluation_enabled')::boolean,false) where e.id=v_event_id;
    end if;
    update public.club_camp_days d set day_index=v_day_index,starts_at=start_time,ends_at=end_time,location_text=nullif(day->>'location_text',''),
      practical_info=nullif(day->>'practical_info',''),responsible_coach_id=coalesce(nullif(day->>'responsible_coach_id','')::uuid,head_coach),
      evaluation_enabled=coalesce((day->>'evaluation_enabled')::boolean,false),updated_at=now() where d.event_id=v_event_id and d.camp_id=camp.id;
    delete from public.club_event_coaches ec where ec.event_id=v_event_id and not(ec.coach_id=any(day_coaches));
    insert into public.club_event_coaches(event_id,coach_id) select v_event_id,x from unnest(day_coaches) x on conflict do nothing;
    -- Retained rows preserve coach_recorded_* and RSVP metadata. Only explicit
    -- registration/day choices change status; historical days remain untouched.
    if old_day.id is null or coalesce(old_day.ends_at,old_day.starts_at)>=now() then
      delete from public.club_event_attendees a where a.event_id=v_event_id and a.player_id=any(removed);
      foreach player in array players loop
        select value into reg from jsonb_array_elements(p_values->'player_registrations') where value->>'player_id'=player::text;
        select cp.registration_status into reg_status from public.club_camp_players cp where cp.camp_id=camp.id and cp.player_id=player;
        day_status := reg#>>array['day_status_by_day_index',v_day_index::text];
        if day_status is not null and day_status not in ('expected','present','absent','excused','not_registered') then raise exception 'invalid_attendance' using errcode='22023'; end if;
        if reg_status<>'registered' then day_status := 'not_registered'; end if;
        insert into public.club_event_attendees(event_id,player_id,status) values(v_event_id,player,coalesce(day_status,'expected'))
          on conflict(event_id,player_id) do nothing;
        get diagnostics inserted=row_count;
        -- The legacy BEFORE INSERT trigger defaults camp rows to not_registered.
        -- Restore the explicit manager choice only after insertion; keep all
        -- metadata on retained rows and never reset an unspecified existing RSVP.
        if inserted=1 or day_status is not null then
          update public.club_event_attendees a set status=coalesce(day_status,'expected') where a.event_id=v_event_id and a.player_id=player;
        end if;
      end loop;
    end if;
    perform public.manager_sync_event_criteria_v1(v_event_id,case when coalesce((day->>'evaluation_enabled')::boolean,false)
      then array(select value::uuid from jsonb_array_elements_text(day->'evaluation_criterion_ids')) else '{}'::uuid[] end);
    days_result := days_result || jsonb_build_array(jsonb_build_object('event_id',v_event_id,'day_index',v_day_index));
    v_day_index := v_day_index+1;
  end loop;
  for opt in select value from jsonb_array_elements(p_values->'options') loop
    v_option_id := nullif(opt->>'id','')::uuid;
    if v_option_id is not null and (v_option_id=any(kept_options) or not exists(select 1 from public.club_camp_options o where o.id=v_option_id and o.camp_id=camp.id)) then
      raise exception 'invalid_option' using errcode='22023';
    end if;
    input_kind := coalesce(opt->>'input_type','checkbox'); v_choices := coalesce(opt->'choices','[]'); option_capacity := (opt->>'capacity')::int;
    if nullif(btrim(opt->>'name'),'') is null or input_kind not in ('checkbox','yes_no','select','radio')
      or jsonb_typeof(v_choices)<>'array' or (input_kind in ('select','radio') and jsonb_array_length(v_choices)<2) then raise exception 'invalid_option' using errcode='22023'; end if;
    assignment_ids := array(select (x->>'player_id')::uuid from jsonb_array_elements(opt->'player_assignments') x);
    if cardinality(assignment_ids)<>(select count(distinct x) from unnest(assignment_ids) x) or not(assignment_ids<@players) then raise exception 'invalid_option_assignment' using errcode='22023'; end if;
    select coalesce(sum(coalesce((x->>'quantity')::int,1)),0) into quantity_sum from jsonb_array_elements(opt->'player_assignments') x;
    if option_capacity is not null and quantity_sum>option_capacity then raise exception 'option_capacity' using errcode='22023'; end if;
    day_indexes := array(select value::int from jsonb_array_elements_text(opt->'day_indexes'));
    if coalesce((opt->>'applies_to_all_days')::boolean,true)=false and (cardinality(day_indexes)=0 or exists(select 1 from unnest(day_indexes) x where x<0 or x>=v_day_index)) then raise exception 'invalid_option_days' using errcode='22023'; end if;
    if v_option_id is null then
      insert into public.club_camp_options(camp_id,name) values(camp.id,btrim(opt->>'name')) returning id into v_option_id;
    end if;
    update public.club_camp_options o set name=btrim(opt->>'name'),description=nullif(opt->>'description',''),
      is_active=coalesce((opt->>'is_active')::boolean,true),applies_to_all_days=coalesce((opt->>'applies_to_all_days')::boolean,true),
      capacity=option_capacity,allows_quantity=input_kind='checkbox' and jsonb_array_length(v_choices)=0 and coalesce((opt->>'allows_quantity')::boolean,false),
      input_type=input_kind,choices=v_choices,internal_note=nullif(opt->>'internal_note',''),sort_order=pos,updated_at=now() where o.id=v_option_id;
    delete from public.club_camp_option_days od where od.option_id=v_option_id;
    if coalesce((opt->>'applies_to_all_days')::boolean,true)=false then
      insert into public.club_camp_option_days(option_id,camp_day_id) select v_option_id,d.id from public.club_camp_days d where d.camp_id=camp.id and d.day_index=any(day_indexes);
    end if;
    delete from public.club_camp_player_options po where po.option_id=v_option_id and not(po.player_id=any(assignment_ids));
    for assignment in select value from jsonb_array_elements(opt->'player_assignments') loop
      insert into public.club_camp_player_options(option_id,player_id,quantity,note,selected_value,assigned_by)
        values(v_option_id,(assignment->>'player_id')::uuid,coalesce((assignment->>'quantity')::int,1),nullif(assignment->>'note',''),nullif(assignment->>'selected_value',''),p_actor)
        on conflict(option_id,player_id) do update set quantity=excluded.quantity,note=excluded.note,selected_value=excluded.selected_value,
          updated_at=case when row(club_camp_player_options.quantity,club_camp_player_options.note,club_camp_player_options.selected_value)
            is distinct from row(excluded.quantity,excluded.note,excluded.selected_value) then now() else club_camp_player_options.updated_at end;
    end loop;
    kept_options := array_append(kept_options,v_option_id); pos := pos+1;
  end loop;
  -- Removed options with existing answers are archived with answers intact.
  update public.club_camp_options o set is_active=false,updated_at=now() where o.camp_id=camp.id and not(o.id=any(kept_options));
  return jsonb_build_object('ok',true,'camp_id',camp.id,'days',days_result);
end $function$

CREATE OR REPLACE FUNCTION public.save_manager_competition_v1_business(p_event_id uuid, p_expected jsonb, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_event public.club_events%rowtype; v_group public.coach_groups%rowtype; v_reminder public.club_event_reminders%rowtype;
  v_players uuid[]; v_coaches uuid[]; v_can_change boolean; v_snapshot jsonb; v_start timestamptz; v_end timestamptz;
begin
  select * into v_event from public.club_events where id=p_event_id for update;
  if v_event.id is null then raise exception 'event_not_found'; end if;
  perform public.require_manager_club_scope_v1(auth.uid(),v_event.club_id);
  if v_event.event_type<>'competition' then raise exception 'invalid_competition'; end if;
  if v_event.status='cancelled' then raise exception 'event_cancelled'; end if;
  select * into v_group from public.coach_groups where id=v_event.group_id for update;
  if v_group.id is not null and v_group.club_id is distinct from v_event.club_id then raise exception 'forbidden'; end if;
  perform 1 from public.club_event_attendees where event_id=p_event_id for update;
  perform 1 from public.club_event_coaches where event_id=p_event_id for update;
  perform 1 from public.coach_group_players where group_id=v_event.group_id for update;
  perform 1 from public.coach_group_coaches where group_id=v_event.group_id for update;
  select * into v_reminder from public.club_event_reminders where event_id=p_event_id for update;
  v_snapshot:=public.get_manager_competition_snapshot_v1(p_event_id);
  if p_expected is null or p_expected is distinct from v_snapshot then raise exception 'competition_conflict'; end if;
  if jsonb_typeof(p_payload) is distinct from 'object' then raise exception 'invalid_competition'; end if;
  v_can_change:=v_reminder.id is null or v_reminder.status='pending';
  perform public.manager_validate_competition_v1(p_payload,v_can_change);
  select coalesce(array_agg(distinct value::uuid),'{}') into v_players from jsonb_array_elements_text(coalesce(p_payload->'playerTarget'->'ids','[]'));
  select coalesce(array_agg(distinct value::uuid),'{}') into v_coaches from jsonb_array_elements_text(coalesce(p_payload->'coachTarget'->'ids','[]'));
  if cardinality(v_players) not between 1 and 2000 or cardinality(v_coaches)>500
    or exists(select 1 from unnest(v_players) u(id) where not exists(select 1 from public.club_members m where m.club_id=v_event.club_id and m.user_id=u.id and m.role='player' and m.is_active))
    or exists(select 1 from unnest(v_coaches) u(id) where not exists(select 1 from public.club_members m where m.club_id=v_event.club_id and m.user_id=u.id and m.role='coach' and m.is_active)) then raise exception 'invalid_assignments'; end if;
  -- A roster edit must not erase recorded participation or evaluation history.
  if exists(select 1 from public.club_event_attendees a where a.event_id=p_event_id and not(a.player_id=any(v_players)) and (
    a.coach_recorded_status is not null or a.status in ('present','absent','excused')
    or exists(select 1 from public.club_event_coach_feedback f where f.event_id=p_event_id and f.player_id=a.player_id)
    or exists(select 1 from public.club_event_player_feedback f where f.event_id=p_event_id and f.player_id=a.player_id)
    or exists(select 1 from public.club_event_evaluation_responses r where r.event_id=p_event_id and r.player_id=a.player_id))) then raise exception 'evaluated_attendee_removal'; end if;
  -- Only an exclusive activity-only group follows this roster. A normal/shared group is preserved.
  if v_group.id is not null and v_group.club_season_id is null and not exists(select 1 from public.club_events e where e.group_id=v_group.id and e.id<>p_event_id) then
    delete from public.coach_group_players where group_id=v_group.id and not(player_user_id=any(v_players));
    insert into public.coach_group_players(group_id,player_user_id) select v_group.id,id from unnest(v_players) u(id) on conflict do nothing;
    delete from public.coach_group_coaches where group_id=v_group.id and not(coach_user_id=any(v_coaches));
    insert into public.coach_group_coaches(group_id,coach_user_id,is_head) select v_group.id,id,id=v_coaches[1] from unnest(v_coaches) u(id)
      on conflict(group_id,coach_user_id) do update set is_head=excluded.is_head;
    update public.coach_groups set name='Compétition · '||btrim(p_payload->>'title'),head_coach_user_id=v_coaches[1] where id=v_group.id;
  end if;
  v_start:=(p_payload->>'startsAt')::timestamptz; v_end:=(p_payload->>'endsAt')::timestamptz;
  update public.club_events set title=btrim(p_payload->>'title'),starts_at=v_start,ends_at=v_end,
    duration_minutes=least(300,greatest(1,round(extract(epoch from(v_end-v_start))/60)::int)),location_text=nullif(btrim(p_payload->>'locationText'),''),
    competition_level=p_payload->>'competitionLevel',competition_category=p_payload->>'competitionCategory',external_registration_url=nullif(btrim(p_payload->>'externalRegistrationUrl'),''),
    competition_note=nullif(btrim(p_payload->>'competitionNote'),''),requires_evaluation=false where id=p_event_id;
  delete from public.club_event_attendees where event_id=p_event_id and not(player_id=any(v_players));
  insert into public.club_event_attendees(event_id,player_id,status) select p_event_id,id,'expected' from unnest(v_players) u(id) on conflict(event_id,player_id) do nothing;
  delete from public.club_event_coaches where event_id=p_event_id and not(coach_id=any(v_coaches));
  insert into public.club_event_coaches(event_id,coach_id) select p_event_id,id from unnest(v_coaches) u(id) on conflict do nothing;
  if v_can_change then
    if coalesce((p_payload->'reminder'->>'enabled')::boolean,false) then
      if v_reminder.id is null then
        insert into public.club_event_reminders(event_id,scheduled_for,channel,message_template,status,created_by)
          values(p_event_id,(p_payload->'reminder'->>'scheduledFor')::timestamptz,p_payload->'reminder'->>'channel',btrim(p_payload->'reminder'->>'messageTemplate'),'pending',auth.uid());
      else
        update public.club_event_reminders set scheduled_for=(p_payload->'reminder'->>'scheduledFor')::timestamptz,channel=p_payload->'reminder'->>'channel',
          message_template=btrim(p_payload->'reminder'->>'messageTemplate'),last_error=null where id=v_reminder.id;
      end if;
    elsif v_reminder.id is not null then delete from public.club_event_reminders where id=v_reminder.id and status='pending'; end if;
  end if;
  return jsonb_build_object('ok',true,'firstEventId',p_event_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.save_manager_event_feedback_v1_business(p_event_id uuid, p_player_id uuid, p_feedback jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_event public.club_events%rowtype;
  v_engagement integer := (p_feedback->>'engagement')::integer;
  v_attitude integer := (p_feedback->>'attitude')::integer;
  v_performance integer := (p_feedback->>'performance')::integer;
  v_private_note text := nullif(btrim(p_feedback->>'private_note'), '');
  v_player_note text := nullif(btrim(p_feedback->>'player_note'), '');
begin
  select * into v_event from public.club_events where id = p_event_id for update;
  if v_event.id is null then raise exception 'event_not_found'; end if;
  if not exists (select 1 from public.club_members cm where cm.club_id = v_event.club_id
    and cm.user_id = auth.uid() and cm.role = 'manager' and cm.is_active = true) then
    raise exception 'forbidden';
  end if;
  if not exists (select 1 from public.club_event_attendees a where a.event_id = p_event_id and a.player_id = p_player_id) then
    raise exception 'unknown_attendee';
  end if;
  if v_event.status = 'cancelled' or coalesce(v_event.ends_at, v_event.starts_at + make_interval(mins => coalesce(v_event.duration_minutes, 0))) > now() then
    raise exception 'event_not_finished';
  end if;
  if p_feedback is null or jsonb_typeof(p_feedback) <> 'object'
    or v_engagement not between 1 and 6 or v_attitude not between 1 and 6 or v_performance not between 1 and 6
    or char_length(coalesce(v_private_note, '')) > 4000 or char_length(coalesce(v_player_note, '')) > 4000 then
    raise exception 'invalid_feedback';
  end if;
  insert into public.club_event_coach_feedback
    (event_id, player_id, coach_id, engagement, attitude, performance, visible_to_player, private_note, player_note)
  values (p_event_id, p_player_id, auth.uid(), v_engagement, v_attitude, v_performance,
    coalesce((p_feedback->>'visible_to_player')::boolean, false), v_private_note, v_player_note)
  on conflict (event_id, player_id, coach_id) do update set
    engagement = excluded.engagement, attitude = excluded.attitude, performance = excluded.performance,
    visible_to_player = excluded.visible_to_player, private_note = excluded.private_note, player_note = excluded.player_note;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_manager_event_feedback_v2_business(p_event_id uuid, p_player_id uuid, p_expected jsonb, p_values jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_event public.club_events%rowtype; v_attendee public.club_event_attendees%rowtype;
  v_snapshot jsonb; v_feedback jsonb; v_previous jsonb; v_answers jsonb; v_answer jsonb; v_key text;
  v_status text:=p_values->>'attendance'; v_criterion public.club_event_evaluation_criteria%rowtype;
  v_notify boolean:=false;
begin
  select * into v_event from public.club_events where id=p_event_id for update;
  if v_event.id is null then raise exception 'event_not_found'; end if;
  perform public.require_manager_club_scope_v1(auth.uid(),v_event.club_id);
  select * into v_attendee from public.club_event_attendees where event_id=p_event_id and player_id=p_player_id for update;
  if v_attendee.player_id is null then raise exception 'unknown_attendee'; end if;
  if v_event.status='cancelled' then raise exception 'event_cancelled'; end if;
  if not coalesce(v_event.requires_evaluation,false) then raise exception 'evaluation_disabled'; end if;
  if coalesce(v_event.ends_at,v_event.starts_at+make_interval(mins=>v_event.duration_minutes))>now() then raise exception 'event_not_finished'; end if;
  perform 1 from public.club_event_coach_feedback where event_id=p_event_id and player_id=p_player_id for update;
  perform 1 from public.club_event_evaluation_criteria where event_id=p_event_id for share;
  perform 1 from public.club_event_evaluation_responses where event_id=p_event_id and player_id=p_player_id and respondent_role='coach' for update;
  v_snapshot:=public.get_manager_evaluation_snapshot_v1(p_event_id,p_player_id);
  if p_expected is null or v_snapshot is distinct from p_expected then raise exception 'evaluation_conflict'; end if;
  if jsonb_typeof(p_values) is distinct from 'object' or v_status is null or v_status not in ('present','absent') then raise exception 'attendance_required'; end if;
  v_feedback:=p_values->'feedback'; v_answers:=p_values->'responses';
  if jsonb_typeof(v_feedback) is distinct from 'object' or jsonb_typeof(v_answers) is distinct from 'object' then raise exception 'invalid_feedback'; end if;
  if char_length(coalesce(v_feedback->>'private_note',''))>4000 or char_length(coalesce(v_feedback->>'player_note',''))>4000 then raise exception 'invalid_note'; end if;
  if v_status='present' and (
    (v_feedback->>'engagement')::integer is null or (v_feedback->>'engagement')::integer not between 1 and 6 or
    (v_feedback->>'attitude')::integer is null or (v_feedback->>'attitude')::integer not between 1 and 6 or
    (v_feedback->>'performance')::integer is null or (v_feedback->>'performance')::integer not between 1 and 6
  ) then raise exception 'ratings_required'; end if;
  for v_key in select jsonb_object_keys(v_answers) loop
    if not exists(select 1 from public.club_event_evaluation_criteria where id::text=v_key and event_id=p_event_id and is_enabled and snapshot_respondent in ('coach','both')) then raise exception 'invalid_custom_criterion'; end if;
  end loop;
  if v_status='present' then
    for v_criterion in select * from public.club_event_evaluation_criteria where event_id=p_event_id and is_enabled and snapshot_respondent in ('coach','both') loop
      v_answer:=v_answers->v_criterion.id::text;
      if v_answer is null or v_answer='null'::jsonb or v_answer='""'::jsonb then
        if v_criterion.snapshot_is_required then raise exception 'required_criteria_missing'; end if;
      elsif v_criterion.snapshot_response_format='short_text' then
        if jsonb_typeof(v_answer)<>'string' or char_length(btrim(v_answer#>>'{}')) not between 1 and 240 then raise exception 'invalid_custom_response'; end if;
      elsif not exists(select 1 from jsonb_array_elements(v_criterion.snapshot_choices) c where c->'value'=v_answer) then raise exception 'invalid_custom_response'; end if;
    end loop;
  else
    v_feedback:=v_feedback||jsonb_build_object('engagement',null,'attitude',null,'performance',null,'visible_to_player',false,'player_note',null);
  end if;
  v_previous:=v_snapshot->'feedback'->0;
  -- Only a new/changed visible assessment may notify the junior. Private notes never do.
  v_notify:=v_status='present' and coalesce((v_feedback->>'visible_to_player')::boolean,false) and (
    not coalesce((v_previous->>'visible_to_player')::boolean,false) or
    jsonb_build_array(v_feedback->'engagement',v_feedback->'attitude',v_feedback->'performance',nullif(btrim(v_feedback->>'player_note'),'')) is distinct from
    jsonb_build_array(v_previous->'engagement',v_previous->'attitude',v_previous->'performance',nullif(btrim(v_previous->>'player_note'),'')));
  -- Preserve evaluations authored by other coaches. This function only updates the Manager's row.
  perform public.save_manager_event_feedback_v1(p_event_id,p_player_id,v_feedback);
  update public.club_event_attendees set status=v_status,coach_recorded_status=v_status,coach_recorded_by=auth.uid(),coach_recorded_at=clock_timestamp()
    where event_id=p_event_id and player_id=p_player_id;
  delete from public.club_event_evaluation_responses r where event_id=p_event_id and player_id=p_player_id and respondent_role='coach'
    and exists(select 1 from public.club_event_evaluation_criteria c where c.id=r.event_criterion_id and c.is_enabled and c.snapshot_respondent in ('coach','both'));
  if v_status='present' then
    insert into public.club_event_evaluation_responses(club_id,event_id,event_criterion_id,player_id,respondent_user_id,respondent_role,value_json)
      select v_event.club_id,p_event_id,c.id,p_player_id,auth.uid(),'coach',v_answers->c.id::text from public.club_event_evaluation_criteria c
      where c.event_id=p_event_id and c.is_enabled and c.snapshot_respondent in ('coach','both') and v_answers?c.id::text and v_answers->c.id::text not in ('null'::jsonb,'""'::jsonb);
  end if;
  return jsonb_build_object('ok',true,'notification_required',coalesce(v_notify,false));
end;
$function$

CREATE OR REPLACE FUNCTION public.save_manager_player_consent_v1(p_actor_id uuid, p_club_id uuid, p_player_id uuid, p_values jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_status text := p_values->>'status';
  v_source text := coalesce(nullif(p_values->>'source', ''), 'manager');
  v_signer uuid := nullif(p_values->>'signer_guardian_user_id', '')::uuid;
  v_decided_at timestamptz;
  v_consent public.player_consents%rowtype;
begin
  perform public.require_manager_player_scope_v1(p_actor_id, p_club_id, p_player_id);
  if v_status is null or v_status not in ('pending', 'granted', 'refused', 'adult')
    or v_source not in ('manager', 'import') then
    raise exception using errcode = '22023', message = 'invalid_consent';
  end if;
  if v_signer is not null then
    perform 1 from public.player_guardians
      where player_id = p_player_id and guardian_user_id = v_signer and can_view = true for share;
    if not found then raise exception using errcode = '42501', message = 'invalid_signer'; end if;
  end if;
  v_decided_at := case when v_status = 'pending' then null
    else coalesce(nullif(p_values->>'decided_at', '')::timestamptz, now()) end;
  -- Preserve the existing global consent-status synchronization after checking the target.
  update public.club_members set player_consent_status = v_status
    where user_id = p_player_id and role = 'player' and is_active = true;
  insert into public.player_consents (club_id, player_user_id, status, decided_at, signer_guardian_user_id,
    signer_name, source, consent_version, internal_notes, updated_by, updated_at)
  values (p_club_id, p_player_id, v_status, v_decided_at, v_signer,
    nullif(trim(p_values->>'signer_name'), ''), v_source, nullif(trim(p_values->>'consent_version'), ''),
    nullif(trim(p_values->>'internal_notes'), ''), p_actor_id, now())
  on conflict (club_id, player_user_id) do update set status = excluded.status, decided_at = excluded.decided_at,
    signer_guardian_user_id = excluded.signer_guardian_user_id, signer_name = excluded.signer_name,
    source = excluded.source, consent_version = excluded.consent_version, internal_notes = excluded.internal_notes,
    updated_by = excluded.updated_by, updated_at = excluded.updated_at
  returning * into v_consent;
  insert into public.player_consent_history (club_id, player_user_id, status, decided_at,
    signer_guardian_user_id, signer_name, source, consent_version, internal_notes, changed_by)
  values (p_club_id, p_player_id, v_status, v_decided_at, v_signer, v_consent.signer_name, v_source,
    v_consent.consent_version, v_consent.internal_notes, p_actor_id);
  return jsonb_build_object('ok', true, 'consent', to_jsonb(v_consent), 'history', (
    select coalesce(jsonb_agg(to_jsonb(h) order by h.changed_at desc), '[]'::jsonb)
    from (select * from public.player_consent_history where club_id = p_club_id and player_user_id = p_player_id
      order by changed_at desc limit 100) h));
end;
$function$

CREATE OR REPLACE FUNCTION public.save_platform_news_v1(p_news_id uuid, p_actor_id uuid, p_status text, p_scheduled_for timestamp with time zone, p_visible_on_home boolean, p_image_url text, p_club_ids jsonb, p_translations jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_news_id uuid := p_news_id;
  v_club_count integer;
  v_input_club_count integer;
begin
  if not exists (select 1 from public.app_admins where user_id = p_actor_id) then
    raise exception using errcode = 'P0001', message = 'FORBIDDEN';
  end if;
  if p_status not in ('draft', 'scheduled', 'published', 'archived')
    or (p_status = 'scheduled' and p_scheduled_for is null)
  then raise exception using errcode = 'P0001', message = 'INVALID_STATUS'; end if;
  if jsonb_typeof(p_club_ids) <> 'array' or jsonb_array_length(p_club_ids) = 0 then
    raise exception using errcode = 'P0001', message = 'CLUB_REQUIRED';
  end if;
  if jsonb_typeof(p_translations) <> 'object'
    or btrim(coalesce(p_translations #>> '{fr,title}', '')) = ''
  then raise exception using errcode = 'P0001', message = 'FRENCH_TITLE_REQUIRED'; end if;

  select count(distinct selected_club.value), count(*) into v_club_count, v_input_club_count
  from jsonb_array_elements_text(p_club_ids) selected_club(value)
  join public.clubs on clubs.id = selected_club.value::uuid;
  if v_club_count = 0 or v_club_count <> v_input_club_count then
    raise exception using errcode = 'P0001', message = 'INVALID_CLUB';
  end if;

  if v_news_id is null then
    insert into public.platform_news (created_by, updated_by, status, scheduled_for, published_at, visible_on_home, image_url)
    values (p_actor_id, p_actor_id, p_status,
      case when p_status = 'scheduled' then p_scheduled_for else null end,
      case when p_status = 'published' then now() else null end,
      coalesce(p_visible_on_home, false), nullif(btrim(coalesce(p_image_url, '')), ''))
    returning id into v_news_id;
  else
    update public.platform_news
    set updated_by = p_actor_id,
        status = p_status,
        scheduled_for = case when p_status = 'scheduled' then p_scheduled_for else null end,
        published_at = case when p_status = 'published' then coalesce(published_at, now()) else null end,
        visible_on_home = coalesce(p_visible_on_home, false),
        image_url = nullif(btrim(coalesce(p_image_url, '')), '')
    where id = v_news_id;
    if not found then raise exception using errcode = 'P0001', message = 'NEWS_NOT_FOUND'; end if;
    delete from public.platform_news_clubs where news_id = v_news_id;
    delete from public.platform_news_translations where news_id = v_news_id;
  end if;

  insert into public.platform_news_clubs (news_id, club_id)
  select v_news_id, value::uuid from jsonb_array_elements_text(p_club_ids);

  insert into public.platform_news_translations (news_id, locale, title, summary, body)
  select v_news_id, entry.key, btrim(entry.value ->> 'title'),
    nullif(btrim(coalesce(entry.value ->> 'summary', '')), ''),
    btrim(coalesce(entry.value ->> 'body', ''))
  from jsonb_each(p_translations) entry
  where entry.key in ('fr', 'en', 'de', 'it')
    and btrim(coalesce(entry.value ->> 'title', '')) <> '';

  return v_news_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_platform_news_v2(p_news_id uuid, p_actor_id uuid, p_status text, p_scheduled_for timestamp with time zone, p_visible_on_home boolean, p_image_url text, p_targets jsonb, p_translations jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_news_id uuid := p_news_id;
  v_target jsonb;
  v_club_id uuid;
  v_roles text[];
begin
  if not exists (select 1 from public.app_admins where user_id = p_actor_id) then
    raise exception using errcode = 'P0001', message = 'FORBIDDEN';
  end if;
  if p_status not in ('draft', 'scheduled', 'published', 'archived')
    or (p_status = 'scheduled' and p_scheduled_for is null)
  then raise exception using errcode = 'P0001', message = 'INVALID_STATUS'; end if;
  if jsonb_typeof(p_targets) <> 'array' or jsonb_array_length(p_targets) = 0 then
    raise exception using errcode = 'P0001', message = 'TARGET_REQUIRED';
  end if;
  if jsonb_typeof(p_translations) <> 'object'
    or btrim(coalesce(p_translations #>> '{fr,title}', '')) = ''
  then raise exception using errcode = 'P0001', message = 'FRENCH_TITLE_REQUIRED'; end if;

  -- Validate the complete matrix before changing an existing news item.
  for v_target in select value from jsonb_array_elements(p_targets)
  loop
    begin
      v_club_id := (v_target ->> 'club_id')::uuid;
    exception when invalid_text_representation then
      raise exception using errcode = 'P0001', message = 'INVALID_CLUB';
    end;
    if not exists (select 1 from public.clubs where id = v_club_id) then
      raise exception using errcode = 'P0001', message = 'INVALID_CLUB';
    end if;
    if jsonb_typeof(v_target -> 'roles') <> 'array' then
      raise exception using errcode = 'P0001', message = 'INVALID_TARGET_ROLES';
    end if;
    select array_agg(distinct role_value.value order by role_value.value) into v_roles
    from jsonb_array_elements_text(v_target -> 'roles') role_value(value);
    if coalesce(cardinality(v_roles), 0) = 0
      or not (v_roles <@ array['player', 'coach', 'manager']::text[])
    then raise exception using errcode = 'P0001', message = 'INVALID_TARGET_ROLES'; end if;
  end loop;

  if (select count(*) from jsonb_array_elements(p_targets))
    <> (select count(distinct value ->> 'club_id') from jsonb_array_elements(p_targets))
  then raise exception using errcode = 'P0001', message = 'DUPLICATE_CLUB_TARGET'; end if;

  if v_news_id is null then
    insert into public.platform_news (created_by, updated_by, status, scheduled_for, published_at, visible_on_home, image_url)
    values (p_actor_id, p_actor_id, p_status,
      case when p_status = 'scheduled' then p_scheduled_for else null end,
      case when p_status = 'published' then now() else null end,
      coalesce(p_visible_on_home, false), nullif(btrim(coalesce(p_image_url, '')), ''))
    returning id into v_news_id;
  else
    update public.platform_news
    set updated_by = p_actor_id,
        status = p_status,
        scheduled_for = case when p_status = 'scheduled' then p_scheduled_for else null end,
        published_at = case when p_status = 'published' then coalesce(published_at, now()) else null end,
        visible_on_home = coalesce(p_visible_on_home, false),
        image_url = nullif(btrim(coalesce(p_image_url, '')), '')
    where id = v_news_id;
    if not found then raise exception using errcode = 'P0001', message = 'NEWS_NOT_FOUND'; end if;
    delete from public.platform_news_clubs where news_id = v_news_id;
    delete from public.platform_news_translations where news_id = v_news_id;
  end if;

  for v_target in select value from jsonb_array_elements(p_targets)
  loop
    v_club_id := (v_target ->> 'club_id')::uuid;
    select array_agg(distinct role_value.value order by role_value.value) into v_roles
    from jsonb_array_elements_text(v_target -> 'roles') role_value(value);
    insert into public.platform_news_clubs (news_id, club_id, target_roles)
    values (v_news_id, v_club_id, v_roles);
  end loop;

  insert into public.platform_news_translations (news_id, locale, title, summary, body)
  select v_news_id, entry.key, btrim(entry.value ->> 'title'),
    nullif(btrim(coalesce(entry.value ->> 'summary', '')), ''),
    btrim(coalesce(entry.value ->> 'body', ''))
  from jsonb_each(p_translations) entry
  where entry.key in ('fr', 'en', 'de', 'it')
    and btrim(coalesce(entry.value ->> 'title', '')) <> '';

  return v_news_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_player_golf_hole_transactional(p_round_id uuid, p_hole jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
