CREATE OR REPLACE FUNCTION public.save_player_golf_holes_transactional_business(p_round_id uuid, p_holes jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor_id uuid := auth.uid();
  v_round public.golf_rounds%rowtype;
  v_hole_count integer;
  v_distinct_hole_count integer;
  v_min_hole integer;
  v_max_hole integer;
begin
  if v_actor_id is null or p_round_id is null or jsonb_typeof(p_holes) is distinct from 'array' then
    raise exception using errcode = 'P0001', message = 'FORBIDDEN';
  end if;

  select gr.*
  into v_round
  from public.golf_rounds gr
  where gr.id = p_round_id
  for update;
  if not found then
    raise exception using errcode = 'P0001', message = 'ROUND_NOT_FOUND';
  end if;

  if v_round.user_id is distinct from v_actor_id and not exists (
    select 1
    from public.player_guardians pg
    where pg.player_id = v_round.user_id
      and pg.guardian_user_id = v_actor_id
      and coalesce(pg.can_view, true) = true
      and coalesce(pg.can_edit, false) = true
  ) then
    raise exception using errcode = 'P0001', message = 'FORBIDDEN';
  end if;

  if not exists (
    select 1 from public.club_members cm
    where cm.user_id = v_round.user_id and cm.role = 'player' and cm.is_active = true
  ) then
    raise exception using errcode = 'P0001', message = 'PLAYER_MEMBERSHIP_REQUIRED';
  end if;
  if exists (
    select 1 from public.club_members cm
    where cm.user_id = v_round.user_id
      and cm.role = 'player'
      and cm.is_active = true
      and coalesce(cm.player_consent_status, 'pending') not in ('granted', 'adult')
  ) then
    raise exception using errcode = 'P0001', message = 'PLAYER_CONSENT_REQUIRED';
  end if;
  if v_round.om_organization_id is not null and not exists (
    select 1 from public.club_members cm
    where cm.user_id = v_round.user_id
      and cm.club_id = v_round.om_organization_id
      and cm.role = 'player'
      and cm.is_active = true
  ) then
    raise exception using errcode = 'P0001', message = 'FORBIDDEN';
  end if;

  select
    count(*)::integer,
    count(distinct hole_no)::integer,
    min(hole_no),
    max(hole_no)
  into v_hole_count, v_distinct_hole_count, v_min_hole, v_max_hole
  from jsonb_to_recordset(p_holes) as h(hole_no integer);

  if v_hole_count not in (9, 18)
    or v_distinct_hole_count <> v_hole_count
    or v_min_hole <> 1
    or v_max_hole <> v_hole_count
  then
    raise exception using errcode = 'P0001', message = 'INVALID_ROUND_PAYLOAD';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(p_holes) as h(
      hole_no integer,
      par integer,
      score integer,
      putts integer
    )
    where (h.par is not null and (h.par < 1 or h.par > 7))
      or (h.score is not null and (h.score < 0 or h.score > 30))
      or (h.putts is not null and (
        h.putts < 0
        or h.putts > 10
        or (h.score is not null and h.putts > h.score)
      ))
  ) then
    raise exception using errcode = 'P0001', message = 'INVALID_HOLE_PAYLOAD';
  end if;

  insert into public.golf_round_holes (
    round_id,
    hole_no,
    par,
    stroke_index,
    score,
    putts,
    fairway_hit,
    note
  )
  select
    p_round_id,
    h.hole_no,
    h.par,
    h.stroke_index,
    h.score,
    h.putts,
    h.fairway_hit,
    nullif(trim(h.note), '')
  from jsonb_to_recordset(p_holes) as h(
    hole_no integer,
    par integer,
    stroke_index integer,
    score integer,
    putts integer,
    fairway_hit boolean,
    note text
  )
  on conflict (round_id, hole_no) do update set
    par = excluded.par,
    stroke_index = excluded.stroke_index,
    score = excluded.score,
    putts = excluded.putts,
    fairway_hit = excluded.fairway_hit,
    note = excluded.note;

  perform public.om_recompute_round(p_round_id);

  return jsonb_build_object(
    'ok', true,
    'round_id', p_round_id,
    'hole_count', v_hole_count
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.set_legal_draft_variables(p_document uuid, p_expected_revision integer, p_variables text[], p_actor uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare dr public.legal_drafts%rowtype; normalized text[]; changed jsonb;
begin
  if not exists(select 1 from public.app_admins a where a.user_id=p_actor) then raise exception 'Platform admin required'; end if;
  if p_variables is null or exists(select 1 from unnest(p_variables) as t(variable)
    where variable is null or variable not in ('child_name','club_name','user_name')) then raise exception 'Unsupported variable'; end if;
  select coalesce(array_agg(distinct variable order by variable),'{}'::text[]) into normalized
    from unnest(p_variables) as t(variable);
  select * into dr from public.legal_drafts where document_id=p_document for update;
  if not found or dr.source_revision is distinct from p_expected_revision then raise exception 'Draft changed; reload'; end if;
  if dr.allowed_variables=normalized then return dr.source_revision; end if;
  select coalesce(jsonb_object_agg(key,value || jsonb_build_object('status','needs_review')),'{}'::jsonb)
    into changed from jsonb_each(dr.translations);
  update public.legal_drafts set allowed_variables=normalized,translations=changed,
    source_revision=dr.source_revision+1,updated_by=p_actor,updated_at=now() where document_id=p_document;
  return dr.source_revision+1;
end $function$

CREATE OR REPLACE FUNCTION public.set_player_camp_attendance_transactional(p_event_id uuid, p_player_id uuid, p_actor_id uuid, p_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_camp public.club_camps%rowtype;
  v_registration public.club_camp_players%rowtype;
  v_registered_count integer;
begin
  if p_status not in ('present', 'absent') then
    raise exception using errcode = 'P0001', message = 'INVALID_ATTENDANCE_STATUS';
  end if;

  select c.*
  into v_camp
  from public.club_camp_days cd
  join public.club_camps c on c.id = cd.camp_id
  where cd.event_id = p_event_id
  for update of c;
  if not found then
    raise exception using errcode = 'P0001', message = 'CAMP_DAY_NOT_FOUND';
  end if;

  if v_camp.status <> 'scheduled' then
    raise exception using errcode = 'P0001', message = 'CAMP_NOT_AVAILABLE';
  end if;

  select cp.*
  into v_registration
  from public.club_camp_players cp
  where cp.camp_id = v_camp.id
    and cp.player_id = p_player_id
  for update;
  if not found then
    raise exception using errcode = 'P0001', message = 'CAMP_PLAYER_NOT_FOUND';
  end if;

  if p_actor_id is null or (
    p_actor_id <> p_player_id
    and not exists (
      select 1
      from public.player_guardians pg
      where pg.player_id = p_player_id
        and pg.guardian_user_id = p_actor_id
        and coalesce(pg.can_view, true) = true
        and coalesce(pg.can_edit, false) = true
    )
  ) then
    raise exception using errcode = 'P0001', message = 'FORBIDDEN';
  end if;

  if v_registration.registration_status <> 'registered' then
    if p_status <> 'present' then
      raise exception using errcode = 'P0001', message = 'CAMP_REGISTRATION_REQUIRED';
    end if;

    select count(*)::integer
    into v_registered_count
    from public.club_camp_players cp
    where cp.camp_id = v_camp.id
      and cp.registration_status = 'registered';

    if v_camp.capacity is not null and v_registered_count >= v_camp.capacity then
      raise exception using errcode = 'P0001', message = 'CAMP_CAPACITY_EXCEEDED';
    end if;

    update public.club_camp_players cp
    set
      registration_status = 'registered',
      registered_at = coalesce(cp.registered_at, now())
    where cp.camp_id = v_camp.id
      and cp.player_id = p_player_id;
  end if;

  insert into public.club_event_attendees (event_id, player_id, status)
  values (p_event_id, p_player_id, p_status)
  on conflict (event_id, player_id) do update set
    status = excluded.status;

  return jsonb_build_object(
    'ok', true,
    'registration_status', 'registered',
    'attendance_status', p_status
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.set_player_camp_option_transactional(p_camp_id uuid, p_option_id uuid, p_player_id uuid, p_actor_id uuid, p_selected boolean, p_quantity integer DEFAULT 1, p_selected_value text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_camp_status text;
  v_option public.club_camp_options%rowtype;
  v_registration public.club_camp_players%rowtype;
  v_choice_values jsonb;
  v_quantity integer;
  v_assigned_by_others integer;
begin
  select camp.status
  into v_camp_status
  from public.club_camps camp
  where camp.id = p_camp_id
  for update;
  if not found then
    raise exception using errcode = 'P0001', message = 'CAMP_NOT_FOUND';
  end if;

  if v_camp_status <> 'scheduled' then
    raise exception using errcode = 'P0001', message = 'CAMP_NOT_AVAILABLE';
  end if;

  select option_row.*
  into v_option
  from public.club_camp_options option_row
  where option_row.id = p_option_id
    and option_row.camp_id = p_camp_id
  for update;
  if not found then
    raise exception using errcode = 'P0001', message = 'CAMP_OPTION_NOT_FOUND';
  end if;

  select cp.*
  into v_registration
  from public.club_camp_players cp
  where cp.camp_id = p_camp_id
    and cp.player_id = p_player_id
  for update;
  if not found then
    raise exception using errcode = 'P0001', message = 'CAMP_PLAYER_NOT_FOUND';
  end if;

  if p_actor_id is null or (
    p_actor_id <> p_player_id
    and not exists (
      select 1
      from public.player_guardians pg
      where pg.player_id = p_player_id
        and pg.guardian_user_id = p_actor_id
        and coalesce(pg.can_view, true) = true
        and coalesce(pg.can_edit, false) = true
    )
  ) then
    raise exception using errcode = 'P0001', message = 'FORBIDDEN';
  end if;

  if v_registration.registration_status <> 'registered' then
    raise exception using errcode = 'P0001', message = 'CAMP_REGISTRATION_REQUIRED';
  end if;

  if not p_selected then
    delete from public.club_camp_player_options assignment
    where assignment.option_id = p_option_id
      and assignment.player_id = p_player_id;
    return jsonb_build_object('ok', true, 'selected', false);
  end if;

  if not v_option.is_active then
    raise exception using errcode = 'P0001', message = 'CAMP_OPTION_UNAVAILABLE';
  end if;

  if v_option.input_type = 'checkbox' and jsonb_array_length(v_option.choices) > 0 then
    begin
      v_choice_values := p_selected_value::jsonb;
    exception when others then
      raise exception using errcode = 'P0001', message = 'INVALID_OPTION_VALUE';
    end;

    if jsonb_typeof(v_choice_values) <> 'array'
      or jsonb_array_length(v_choice_values) = 0
      or exists (
        select 1
        from jsonb_array_elements_text(v_choice_values) selected_choice(value)
        where not (v_option.choices ? selected_choice.value)
      )
    then
      raise exception using errcode = 'P0001', message = 'INVALID_OPTION_VALUE';
    end if;
  elsif v_option.input_type = 'yes_no' then
    if coalesce(p_selected_value, '') not in ('yes', 'no') then
      raise exception using errcode = 'P0001', message = 'INVALID_OPTION_VALUE';
    end if;
  elsif v_option.input_type in ('select', 'radio') then
    if coalesce(p_selected_value, '') = '' or not (v_option.choices ? p_selected_value) then
      raise exception using errcode = 'P0001', message = 'INVALID_OPTION_VALUE';
    end if;
  end if;

  v_quantity := case
    when v_option.input_type = 'checkbox'
      and jsonb_array_length(v_option.choices) = 0
      and v_option.allows_quantity
    then p_quantity
    else 1
  end;

  if v_quantity is null or v_quantity < 1 then
    raise exception using errcode = 'P0001', message = 'INVALID_OPTION_QUANTITY';
  end if;

  select coalesce(sum(assignment.quantity), 0)::integer
  into v_assigned_by_others
  from public.club_camp_player_options assignment
  where assignment.option_id = p_option_id
    and assignment.player_id <> p_player_id;

  if v_option.capacity is not null and v_assigned_by_others + v_quantity > v_option.capacity then
    raise exception using errcode = 'P0001', message = 'CAMP_OPTION_CAPACITY_EXCEEDED';
  end if;

  insert into public.club_camp_player_options (
    option_id,
    player_id,
    quantity,
    selected_value,
    assigned_by,
    updated_at
  ) values (
    p_option_id,
    p_player_id,
    v_quantity,
    case
      when v_option.input_type = 'checkbox' and jsonb_array_length(v_option.choices) = 0 then null
      else p_selected_value
    end,
    p_actor_id,
    now()
  )
  on conflict (option_id, player_id) do update set
    quantity = excluded.quantity,
    selected_value = excluded.selected_value,
    assigned_by = excluded.assigned_by,
    updated_at = excluded.updated_at;

  return jsonb_build_object(
    'ok', true,
    'selected', true,
    'quantity', v_quantity,
    'remaining_capacity', case
      when v_option.capacity is null then null
      else greatest(v_option.capacity - v_assigned_by_others - v_quantity, 0)
    end
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.set_player_camp_registration_transactional(p_camp_id uuid, p_player_id uuid, p_actor_id uuid, p_registered boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_camp public.club_camps%rowtype;
  v_registration public.club_camp_players%rowtype;
  v_registered_count integer;
  v_next_status text;
begin
  select c.*
  into v_camp
  from public.club_camps c
  where c.id = p_camp_id
  for update;
  if not found then
    raise exception using errcode = 'P0001', message = 'CAMP_NOT_FOUND';
  end if;

  if v_camp.status <> 'scheduled' then
    raise exception using errcode = 'P0001', message = 'CAMP_NOT_AVAILABLE';
  end if;

  select cp.*
  into v_registration
  from public.club_camp_players cp
  where cp.camp_id = p_camp_id
    and cp.player_id = p_player_id
  for update;
  if not found then
    raise exception using errcode = 'P0001', message = 'CAMP_PLAYER_NOT_FOUND';
  end if;

  if p_actor_id is null or (
    p_actor_id <> p_player_id
    and not exists (
      select 1
      from public.player_guardians pg
      where pg.player_id = p_player_id
        and pg.guardian_user_id = p_actor_id
        and coalesce(pg.can_view, true) = true
        and coalesce(pg.can_edit, false) = true
    )
  ) then
    raise exception using errcode = 'P0001', message = 'FORBIDDEN';
  end if;

  if p_registered and v_registration.registration_status <> 'registered' then
    select count(*)::integer
    into v_registered_count
    from public.club_camp_players cp
    where cp.camp_id = p_camp_id
      and cp.registration_status = 'registered';

    if v_camp.capacity is not null and v_registered_count >= v_camp.capacity then
      raise exception using errcode = 'P0001', message = 'CAMP_CAPACITY_EXCEEDED';
    end if;
  end if;

  v_next_status := case when p_registered then 'registered' else 'invited' end;

  update public.club_camp_players cp
  set
    registration_status = v_next_status,
    registered_at = case
      when p_registered then coalesce(cp.registered_at, now())
      else null
    end
  where cp.camp_id = p_camp_id
    and cp.player_id = p_player_id;

  insert into public.club_event_attendees (event_id, player_id, status)
  select
    cd.event_id,
    p_player_id,
    case when p_registered then 'present' else 'not_registered' end
  from public.club_camp_days cd
  where cd.camp_id = p_camp_id
  on conflict (event_id, player_id) do update set
    status = excluded.status;

  select count(*)::integer
  into v_registered_count
  from public.club_camp_players cp
  where cp.camp_id = p_camp_id
    and cp.registration_status = 'registered';

  return jsonb_build_object(
    'ok', true,
    'registration_status', v_next_status,
    'registered_count', v_registered_count,
    'capacity', v_camp.capacity
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.set_player_performance_mode_business(p_org_id uuid, p_player_id uuid, p_enabled boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_org_id is null or p_player_id is null then
    raise exception 'missing_arguments';
  end if;

  if not public.is_org_staff_member(p_org_id, auth.uid()) then
    raise exception 'forbidden';
  end if;

  -- Cannot disable if forced by at least one active performance group in any org.
  if coalesce(p_enabled, false) = false and exists (
    select 1
    from public.coach_group_players gp
    join public.coach_groups g on g.id = gp.group_id
    where gp.player_user_id = p_player_id
      and coalesce(g.is_active, true) = true
      and coalesce(g.is_performance, false) = true
  ) then
    raise exception 'forced_by_performance_group';
  end if;

  -- Global setting across all active player memberships.
  update public.club_members cm
  set is_performance = coalesce(p_enabled, false)
  where cm.user_id = p_player_id
    and cm.role = 'player'
    and cm.is_active = true;

  if not found then
    raise exception 'player_membership_not_found';
  end if;
end;
$function$

