CREATE OR REPLACE FUNCTION public.update_coach_event_occurrence_v1_business(p_event_id uuid, p_expected jsonb, p_changes jsonb, p_coach_ids uuid[], p_player_ids uuid[], p_structure jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_event public.club_events%rowtype;
  v_expected jsonb := p_expected->'event';
  v_type text := p_changes->>'event_type';
  v_start timestamptz := (p_changes->>'starts_at')::timestamptz;
  v_end timestamptz := (p_changes->>'ends_at')::timestamptz;
  v_duration int := (p_changes->>'duration_minutes')::int;
  v_ids uuid[];
  v_expected_ids uuid[];
  v_structure jsonb;
  v_expected_structure jsonb;
  v_item jsonb;
  v_position int := 0;
  v_recipients uuid[];
begin
  select * into v_event from public.club_events where id = p_event_id for update;
  if v_event.id is null then raise exception 'event_not_found'; end if;
  if auth.uid() is null or not public.can_manage_assigned_group(v_event.group_id, auth.uid(), 'planning')
    or not exists(select 1 from public.coach_groups where id = v_event.group_id and club_id = v_event.club_id)
    then raise exception 'forbidden'; end if;
  if v_event.status = 'cancelled' then raise exception 'event_cancelled'; end if;
  if v_event.event_type = 'competition' then raise exception 'use_competition_editor'; end if;
  if (v_event.event_type = 'camp') is distinct from (v_type = 'camp') then raise exception 'use_camp_editor'; end if;
  if v_type is null or v_type not in ('training','interclub','camp','session','event')
    or v_start is null or v_end is null or v_end <= v_start
    or v_duration is null or v_duration not between 1 and 300
    or v_duration <> least(300, round(extract(epoch from (v_end - v_start)) / 60)::int)
    then raise exception 'invalid_event'; end if;
  if v_type in ('session','camp','event') and nullif(btrim(p_changes->>'title'),'') is null
    then raise exception 'title_required'; end if;
  if length(coalesce(p_changes->>'title','')) > 500 or length(coalesce(p_changes->>'location_text','')) > 2000
    or length(coalesce(p_changes->>'coach_note','')) > 10000 then raise exception 'invalid_event'; end if;
  if p_expected is null or jsonb_typeof(v_expected) is distinct from 'object'
    or jsonb_typeof(p_expected->'coach_ids') is distinct from 'array'
    or jsonb_typeof(p_expected->'player_ids') is distinct from 'array'
    or jsonb_typeof(p_expected->'structure') is distinct from 'array' then raise exception 'planning_conflict'; end if;

  -- Compare the data actually loaded by the form, not a token obtained after it.
  -- Attendance may evolve independently: it is neither overwritten nor compared.
  if row(v_event.group_id,v_event.club_id,v_event.series_id,v_event.status,v_event.event_type,v_event.title,
      v_event.starts_at,v_event.ends_at,v_event.duration_minutes,v_event.location_text,v_event.coach_note)
    is distinct from row((v_expected->>'group_id')::uuid,(v_expected->>'club_id')::uuid,(v_expected->>'series_id')::uuid,
      v_expected->>'status',v_expected->>'event_type',v_expected->>'title',
      (v_expected->>'starts_at')::timestamptz,(v_expected->>'ends_at')::timestamptz,
      (v_expected->>'duration_minutes')::int,v_expected->>'location_text',v_expected->>'coach_note')
    then raise exception 'planning_conflict'; end if;
  perform 1 from public.club_event_coaches where event_id = p_event_id for update;
  perform 1 from public.club_event_attendees where event_id = p_event_id for update;
  perform 1 from public.club_event_structure_items where event_id = p_event_id for update;
  select coalesce(array_agg(coach_id order by coach_id),'{}'::uuid[]) into v_ids from public.club_event_coaches where event_id=p_event_id;
  select coalesce(array_agg(distinct id::uuid order by id::uuid),'{}'::uuid[]) into v_expected_ids
    from jsonb_array_elements_text(p_expected->'coach_ids') u(id);
  if v_ids is distinct from v_expected_ids then raise exception 'planning_conflict'; end if;
  if v_event.event_type <> 'camp' then
    select coalesce(array_agg(player_id order by player_id),'{}'::uuid[]) into v_ids from public.club_event_attendees where event_id=p_event_id;
    select coalesce(array_agg(distinct id::uuid order by id::uuid),'{}'::uuid[]) into v_expected_ids
      from jsonb_array_elements_text(p_expected->'player_ids') u(id);
    if v_ids is distinct from v_expected_ids then raise exception 'planning_conflict'; end if;
  end if;
  select coalesce(jsonb_agg(jsonb_build_array(category,minutes,note,position) order by position,category,minutes,note),'[]')
    into v_structure from public.club_event_structure_items where event_id=p_event_id;
  select coalesce(jsonb_agg(jsonb_build_array(x->>'category',(x->>'minutes')::int,x->>'note',(x->>'position')::int)
    order by (x->>'position')::int,x->>'category',(x->>'minutes')::int,x->>'note'),'[]')
    into v_expected_structure from jsonb_array_elements(p_expected->'structure') x;
  if v_structure is distinct from v_expected_structure then raise exception 'planning_conflict'; end if;
  if v_event.event_type = 'camp' and (
    (nullif(p_expected->'camp_day','null'::jsonb) is not null) <> exists(select 1 from public.club_camp_days where event_id=p_event_id)
    or exists(select 1 from public.club_camp_days d where d.event_id=p_event_id
    and row(d.camp_id,d.day_index,d.starts_at,d.ends_at,d.location_text) is distinct from
      row((p_expected->'camp_day'->>'camp_id')::uuid,(p_expected->'camp_day'->>'day_index')::int,
        (p_expected->'camp_day'->>'starts_at')::timestamptz,(p_expected->'camp_day'->>'ends_at')::timestamptz,
        p_expected->'camp_day'->>'location_text'))) then raise exception 'planning_conflict'; end if;

  if p_coach_ids is null or cardinality(p_coach_ids) > 500 or cardinality(p_player_ids) > 2000
    or (v_event.event_type <> 'camp' and p_player_ids is null)
    or (v_event.event_type = 'camp' and p_player_ids is not null)
    or jsonb_typeof(p_structure) is distinct from 'array' or jsonb_array_length(p_structure) > 100
    then raise exception 'invalid_assignments'; end if;
  -- Historical members can be retained unchanged, but cannot be newly assigned.
  if exists(select 1 from unnest(p_coach_ids) u(id) where u.id is null or (
      not exists(select 1 from public.club_event_coaches c where c.event_id=p_event_id and c.coach_id=u.id)
      and not exists(select 1 from public.club_members m where m.club_id=v_event.club_id and m.user_id=u.id and m.is_active and m.role in ('coach','manager'))))
    or exists(select 1 from unnest(p_player_ids) u(id) where u.id is null or (
      not exists(select 1 from public.club_event_attendees a where a.event_id=p_event_id and a.player_id=u.id)
      and not exists(select 1 from public.club_members m where m.club_id=v_event.club_id and m.user_id=u.id and m.is_active)))
    then raise exception 'invalid_assignments'; end if;
  for v_item in select * from jsonb_array_elements(p_structure) loop
    if jsonb_typeof(v_item) <> 'object' or v_item->>'category' is null or v_item->>'category' not in
      ('warmup_mobility','long_game','short_game_all','putting','wedging','pitching','chipping','bunker','course','mental','fitness','other')
      or (v_item->>'minutes')::int is null or (v_item->>'minutes')::int not between 1 and 300
      or length(coalesce(v_item->>'note','')) > 10000 then raise exception 'invalid_structure'; end if;
  end loop;
  if p_player_ids is not null and exists(select 1 from public.club_event_attendees a
    where a.event_id=p_event_id and not(a.player_id=any(p_player_ids)) and (
      a.coach_recorded_status is not null
      or exists(select 1 from public.club_event_coach_feedback f where f.event_id=p_event_id and f.player_id=a.player_id)
      or exists(select 1 from public.club_event_evaluation_responses r where r.event_id=p_event_id and r.player_id=a.player_id)
      or exists(select 1 from public.club_event_player_structure_items i where i.event_id=p_event_id and i.player_id=a.player_id)
      or exists(select 1 from public.coach_player_private_notes n where n.event_id=p_event_id and n.player_id=a.player_id)))
    then raise exception 'evaluated_attendee_removal'; end if;

  update public.club_events set event_type=v_type,title=nullif(btrim(p_changes->>'title'),''),starts_at=v_start,ends_at=v_end,
    duration_minutes=v_duration,location_text=nullif(btrim(p_changes->>'location_text'),''),coach_note=nullif(btrim(p_changes->>'coach_note'),'')
    where id=p_event_id;
  if v_event.event_type='camp' then
    update public.club_camp_days set starts_at=v_start,ends_at=v_end,
      location_text=nullif(btrim(p_changes->>'location_text'),''),updated_at=now() where event_id=p_event_id;
  end if;
  delete from public.club_event_coaches where event_id=p_event_id and not(coach_id=any(p_coach_ids));
  insert into public.club_event_coaches(event_id,coach_id) select p_event_id,id from (select distinct unnest(p_coach_ids) id) u
    on conflict(event_id,coach_id) do nothing;
  if p_player_ids is not null then
    delete from public.club_event_attendees where event_id=p_event_id and not(player_id=any(p_player_ids));
    insert into public.club_event_attendees(event_id,player_id,status) select p_event_id,id,'present' from (select distinct unnest(p_player_ids) id) u
      on conflict(event_id,player_id) do nothing;
  end if;
  delete from public.club_event_structure_items where event_id=p_event_id;
  for v_item in select * from jsonb_array_elements(p_structure) loop
    insert into public.club_event_structure_items(event_id,category,minutes,note,position)
      values(p_event_id,v_item->>'category',(v_item->>'minutes')::int,nullif(btrim(v_item->>'note'),''),v_position);
    v_position := v_position + 1;
  end loop;
  select coalesce(array_agg(player_id),'{}'::uuid[]) into v_recipients from public.club_event_attendees a
    where a.event_id=p_event_id and coalesce(a.status,'expected') not in ('absent','excused')
      and coalesce(a.coach_recorded_status,'present') <> 'absent'
      and (v_event.event_type <> 'camp' or not exists(select 1 from public.club_camp_days where event_id=p_event_id)
        or exists(select 1 from public.club_camp_days d join public.club_camp_players p on p.camp_id=d.camp_id
          where d.event_id=p_event_id and p.player_id=a.player_id and p.registration_status='registered'));
  return jsonb_build_object('ok',true,'event_id',p_event_id,'recipient_ids',to_jsonb(v_recipients));
end;
$function$

CREATE OR REPLACE FUNCTION public.update_coach_event_series_v1_business(p_source_event_id uuid, p_template jsonb, p_coach_ids uuid[], p_player_ids uuid[], p_structure jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_source public.club_events%rowtype;
  v_series public.club_event_series%rowtype;
  v_start date := (p_template->>'start_date')::date;
  v_end date := (p_template->>'end_date')::date;
  v_weekday int := (p_template->>'weekday')::int;
  v_interval int := (p_template->>'interval_weeks')::int;
  v_duration int := (p_template->>'duration_minutes')::int;
  v_time time := (p_template->>'time_of_day')::time;
  v_active boolean := (p_template->>'is_active')::boolean;
  v_type text := p_template->>'event_type';
  v_day date;
  v_start_at timestamptz;
  v_dates timestamptz[] := '{}';
  v_existing uuid[] := '{}';
  v_used uuid[] := '{}';
  v_id uuid;
  v_item jsonb;
  v_position int;
begin
  select * into v_source from public.club_events where id = p_source_event_id;
  if v_source.id is null then raise exception 'event_not_found'; end if;
  select * into v_series from public.club_event_series where id = v_source.series_id for update;
  if v_series.id is null then raise exception 'series_not_found'; end if;
  if auth.uid() is null or not public.can_manage_assigned_group(v_series.group_id,auth.uid(),'planning')
    or v_source.club_id <> v_series.club_id or v_source.group_id <> v_series.group_id then raise exception 'forbidden'; end if;
  if v_start is null or v_end is null or v_end < v_start or v_end - v_start > 1827
    or v_weekday is null or v_weekday not between 0 and 6 or v_interval is null or v_interval not between 1 and 52
    or v_duration is null or v_duration not between 1 and 300 or v_time is null or v_active is null
    or v_type is null or v_type not in ('training','interclub','session','event') then raise exception 'invalid_recurrence'; end if;
  if v_source.event_type = 'camp' then raise exception 'use_camp_editor'; end if;
  if v_type in ('session','event') and nullif(btrim(p_template->>'title'),'') is null then raise exception 'title_required'; end if;
  if p_coach_ids is null or p_player_ids is null or p_structure is null or jsonb_typeof(p_structure) <> 'array'
    or jsonb_array_length(p_structure) > 100 then raise exception 'invalid_assignments'; end if;
  if exists(select 1 from unnest(p_coach_ids) u(id) where not exists(select 1 from public.club_members m
    where m.club_id = v_series.club_id and m.user_id = u.id and m.is_active and m.role in ('coach','manager')))
    or exists(select 1 from unnest(p_player_ids) u(id) where not exists(select 1 from public.club_members m
      where m.club_id = v_series.club_id and m.user_id = u.id and m.is_active)) then raise exception 'invalid_assignments'; end if;
  for v_item in select * from jsonb_array_elements(p_structure) loop
    if nullif(btrim(v_item->>'category'),'') is null or (v_item->>'minutes')::int is null
      or (v_item->>'minutes')::int not between 1 and 300 then raise exception 'invalid_structure'; end if;
  end loop;
  -- Generate the FULL plan first; never silently truncate a recurrence at 80.
  v_day := v_start + ((v_weekday - extract(dow from v_start)::int + 7) % 7);
  while v_active and v_day <= v_end loop
    v_start_at := (v_day + v_time) at time zone 'Europe/Zurich';
    if v_start_at >= now() then v_dates := array_append(v_dates,v_start_at); end if;
    if cardinality(v_dates) > 80 then raise exception 'too_many_occurrences'; end if;
    v_day := v_day + v_interval * 7;
  end loop;
  if v_active and cardinality(v_dates) = 0 then raise exception 'no_future_occurrence'; end if;
  perform 1 from public.club_events where series_id = v_series.id and starts_at >= now() order by id for update;
  select coalesce(array_agg(id order by starts_at,id),'{}'::uuid[]) into v_existing
    from public.club_events where series_id = v_series.id and starts_at >= now() and status = 'scheduled';

  update public.club_event_series set event_type = v_type, title = nullif(btrim(p_template->>'title'),''),
    weekday = v_weekday, time_of_day = v_time, interval_weeks = v_interval, start_date = v_start, end_date = v_end,
    duration_minutes = v_duration, location_text = nullif(btrim(p_template->>'location_text'),''),
    coach_note = nullif(btrim(p_template->>'coach_note'),''), is_active = v_active where id = v_series.id;
  foreach v_start_at in array v_dates loop
    v_id := null;
    -- Match the existing calendar day first, then reuse a displaced occurrence
    -- only when its old date is not itself required by the new plan.
    select id into v_id from public.club_events where id = any(v_existing) and not(id = any(v_used))
      and (starts_at at time zone 'Europe/Zurich')::date = (v_start_at at time zone 'Europe/Zurich')::date
      order by starts_at,id limit 1;
    if v_id is null then
      select e.id into v_id from public.club_events e where e.id = any(v_existing) and not(e.id = any(v_used))
        and not exists(select 1 from unnest(v_dates) d(t) where
          (d.t at time zone 'Europe/Zurich')::date = (e.starts_at at time zone 'Europe/Zurich')::date)
        order by e.starts_at,e.id limit 1;
    end if;
    if v_id is null then
      insert into public.club_events(group_id,club_id,series_id,event_type,title,starts_at,ends_at,duration_minutes,location_text,coach_note,created_by,requires_evaluation)
        values(v_series.group_id,v_series.club_id,v_series.id,v_type,nullif(btrim(p_template->>'title'),''),v_start_at,
          v_start_at + make_interval(mins=>v_duration),v_duration,nullif(btrim(p_template->>'location_text'),''),
          nullif(btrim(p_template->>'coach_note'),''),auth.uid(),v_source.requires_evaluation) returning id into v_id;
      insert into public.club_event_evaluation_criteria(club_id,event_id,criterion_id,position)
        select club_id,v_id,criterion_id,position from public.club_event_evaluation_criteria
        where event_id = p_source_event_id and is_enabled and criterion_id is not null;
    else
      update public.club_events set event_type = v_type,title = nullif(btrim(p_template->>'title'),''),
        starts_at = v_start_at,ends_at = v_start_at + make_interval(mins=>v_duration),duration_minutes = v_duration,
        location_text = nullif(btrim(p_template->>'location_text'),''),coach_note = nullif(btrim(p_template->>'coach_note'),'')
        where id = v_id;
    end if;
    v_used := array_append(v_used,v_id);
    delete from public.club_event_coaches where event_id = v_id and not(coach_id = any(p_coach_ids));
    insert into public.club_event_coaches(event_id,coach_id) select v_id,id from unnest(p_coach_ids) u(id)
      on conflict(event_id,coach_id) do nothing;
    -- Retained attendees keep attendance and all recorded metadata. Refuse to
    -- remove an attendee with recorded work instead of silently deleting it.
    if exists(select 1 from public.club_event_attendees a where a.event_id = v_id and not(a.player_id = any(p_player_ids))
      and (a.coach_recorded_status is not null or exists(select 1 from public.club_event_coach_feedback f
        where f.event_id = v_id and f.player_id = a.player_id)
        or exists(select 1 from public.club_event_evaluation_responses r where r.event_id = v_id and r.player_id = a.player_id))) then
      raise exception 'evaluated_attendee_removal';
    end if;
    delete from public.club_event_attendees where event_id = v_id and not(player_id = any(p_player_ids));
    insert into public.club_event_attendees(event_id,player_id,status) select v_id,id,'present' from unnest(p_player_ids) u(id)
      on conflict(event_id,player_id) do nothing;
    delete from public.club_event_structure_items where event_id = v_id;
    v_position := 0;
    for v_item in select * from jsonb_array_elements(p_structure) loop
      insert into public.club_event_structure_items(event_id,category,minutes,note,position)
        values(v_id,v_item->>'category',(v_item->>'minutes')::int,nullif(btrim(v_item->>'note'),''),v_position);
      v_position := v_position + 1;
    end loop;
  end loop;
  update public.club_events set status = 'cancelled' where id = any(v_existing) and not(id = any(v_used));
  return jsonb_build_object('ok',true,'event_ids',to_jsonb(v_used));
end;
$function$

CREATE OR REPLACE FUNCTION public.update_manager_event_occurrence_v1_business(p_event_id uuid, p_expected jsonb, p_changes jsonb, p_coach_ids uuid[], p_player_ids uuid[], p_structure jsonb, p_criterion_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e public.club_events%rowtype; saved jsonb;
begin
  select * into e from public.club_events where id=p_event_id for update;
  if not found then raise exception 'event_not_found' using errcode='P0002'; end if;
  perform public.require_manager_club_scope_v1(auth.uid(),e.club_id);
  perform 1 from public.club_event_coaches where event_id=e.id for update;
  perform 1 from public.club_event_attendees where event_id=e.id for update;
  perform 1 from public.club_event_structure_items where event_id=e.id for update;
  perform 1 from public.club_event_evaluation_criteria where event_id=e.id for update;
  perform 1 from public.club_camp_days where event_id=e.id for update;
  if public.manager_event_snapshot_v1(e.id) is distinct from (p_expected-'series'-'future') then
    raise exception 'planning_conflict' using errcode='PT409';
  end if;
  -- The shared transaction already checks dates, membership, removal of recorded
  -- work, and applies roster deltas without touching retained attendee rows.
  if exists(select 1 from public.club_event_player_feedback f where f.event_id=e.id
    and p_player_ids is not null and not(f.player_id=any(p_player_ids))) then
    raise exception 'evaluated_attendee_removal' using errcode='22023';
  end if;
  if e.event_type='camp' and p_player_ids is not null then
    if exists(select 1 from public.club_camp_days where event_id=e.id) then raise exception 'use_camp_editor' using errcode='22023'; end if;
    if cardinality(p_player_ids)>2000 or exists(select 1 from unnest(p_player_ids) x where x is null or (
      not exists(select 1 from public.club_event_attendees a where a.event_id=e.id and a.player_id=x)
      and not exists(select 1 from public.club_members m where m.club_id=e.club_id and m.user_id=x and m.is_active))) then
      raise exception 'invalid_assignments' using errcode='22023';
    end if;
    if exists(select 1 from public.club_event_attendees a where a.event_id=e.id and not(a.player_id=any(p_player_ids)) and (
      a.coach_recorded_status is not null
      or exists(select 1 from public.club_event_coach_feedback f where f.event_id=e.id and f.player_id=a.player_id)
      or exists(select 1 from public.club_event_evaluation_responses f where f.event_id=e.id and f.player_id=a.player_id)
      or exists(select 1 from public.club_event_player_structure_items f where f.event_id=e.id and f.player_id=a.player_id)
      or exists(select 1 from public.coach_player_private_notes f where f.event_id=e.id and f.player_id=a.player_id))) then
      raise exception 'evaluated_attendee_removal' using errcode='22023';
    end if;
    delete from public.club_event_attendees where event_id=e.id and not(player_id=any(p_player_ids));
    insert into public.club_event_attendees(event_id,player_id,status) select e.id,x,'present' from unnest(p_player_ids) x on conflict do nothing;
  end if;
  saved := public.update_coach_event_occurrence_v1(e.id,p_expected,p_changes,p_coach_ids,
    case when e.event_type='camp' then null else p_player_ids end,p_structure);
  update public.club_events set requires_evaluation=coalesce((p_changes->>'requires_evaluation')::boolean,false) where id=e.id;
  perform public.manager_sync_event_criteria_v1(e.id,p_criterion_ids);
  return saved;
end $function$

CREATE OR REPLACE FUNCTION public.update_manager_event_series_v1_business(p_event_id uuid, p_expected jsonb, p_series jsonb, p_coach_ids uuid[], p_player_ids uuid[], p_structure jsonb, p_criterion_ids uuid[], p_timezone text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  e public.club_events%rowtype; s public.club_event_series%rowtype; item jsonb; snap jsonb; changes jsonb;
  expected_future jsonb; actual_future jsonb; dates timestamptz[] := '{}'; event_ids uuid[] := '{}';
  coaches uuid[]; players uuid[]; criteria uuid[]; structure jsonb; target uuid; start_day date; end_day date; cursor_day date;
  v_weekday int; weeks int; duration int; time_day time; active boolean; start_time timestamptz; end_time timestamptz;
  i int := 0; result jsonb; recipient_ids uuid[] := '{}';
begin
  select * into e from public.club_events where id=p_event_id;
  if not found or e.series_id is null then raise exception 'series_not_found' using errcode='P0002'; end if;
  perform public.require_manager_club_scope_v1(auth.uid(),e.club_id);
  select * into s from public.club_event_series where id=e.series_id for update;
  if s.club_id<>e.club_id or s.group_id<>e.group_id then raise exception 'forbidden' using errcode='42501'; end if;
  if to_jsonb(s) is distinct from p_expected->'series' then raise exception 'planning_conflict' using errcode='PT409'; end if;
  perform 1 from public.club_events where series_id=s.id and starts_at>=now() order by starts_at,id for update;
  perform 1 from public.club_event_coaches where event_id in(select id from public.club_events where series_id=s.id and starts_at>=now()) for update;
  perform 1 from public.club_event_attendees where event_id in(select id from public.club_events where series_id=s.id and starts_at>=now()) for update;
  perform 1 from public.club_event_structure_items where event_id in(select id from public.club_events where series_id=s.id and starts_at>=now()) for update;
  perform 1 from public.club_event_evaluation_criteria where event_id in(select id from public.club_events where series_id=s.id and starts_at>=now()) for update;
  select coalesce(jsonb_agg(public.manager_event_snapshot_v1(x.id) order by starts_at,id),'[]') into actual_future
    from public.club_events x where series_id=s.id and starts_at>=now();
  -- An occurrence which started while the form was open is now historical.
  select coalesce(jsonb_agg(x order by (x#>>'{event,starts_at}')::timestamptz,x#>>'{event,id}'),'[]') into expected_future
    from jsonb_array_elements(p_expected->'future') x where (x#>>'{event,starts_at}')::timestamptz>=now();
  if exists(select 1 from public.club_camp_days d join public.club_events ce on ce.id=d.event_id where ce.series_id=s.id) then
    raise exception 'use_camp_editor' using errcode='22023';
  end if;
  if actual_future is distinct from expected_future then raise exception 'planning_conflict' using errcode='PT409'; end if;
  start_day := (p_series->>'start_date')::date; end_day := (p_series->>'end_date')::date;
  v_weekday := (p_series->>'weekday')::int; weeks := (p_series->>'interval_weeks')::int;
  time_day := (p_series->>'time_of_day')::time; duration := (p_series->>'duration_minutes')::int;
  active := (p_series->>'is_active')::boolean;
  if start_day is null or end_day is null or end_day<start_day or end_day-start_day>3660
    or v_weekday is null or v_weekday not between 0 and 6 or weeks is null or weeks not between 1 and 52
    or duration is null or duration not between 1 and 300 or time_day is null or active is null
    or not exists(select 1 from pg_catalog.pg_timezone_names where name=p_timezone)
    or p_series->>'event_type' not in ('training','interclub','session','event','camp') then
    raise exception 'invalid_series' using errcode='22023';
  end if;
  if active then
    cursor_day := start_day + ((v_weekday-extract(dow from start_day)::int+7)%7);
    while cursor_day<=end_day loop
      start_time := (cursor_day+time_day) at time zone p_timezone;
      if start_time>=now() then dates := array_append(dates,start_time); end if;
      cursor_day := cursor_day+7*weeks;
      if cardinality(dates)>80 then raise exception 'series_limit' using errcode='22023'; end if;
    end loop;
    if cardinality(dates)=0 then raise exception 'empty_series' using errcode='22023'; end if;
  end if;
  -- Reuse the chronological occurrences. Cancel excess slots; never delete
  -- their discussions, RSVPs, individual programmes or evaluations.
  for item in select value from jsonb_array_elements(actual_future) loop
    if item#>>'{event,status}'='cancelled' then continue; end if;
    target := (item#>>'{event,id}')::uuid;
    event_ids := array_append(event_ids,target);
  end loop;
  for i in 1..greatest(cardinality(event_ids),cardinality(dates)) loop
    if i>cardinality(dates) then
      recipient_ids := recipient_ids || array(select a.player_id from public.club_event_attendees a where a.event_id=event_ids[i]
        and coalesce(a.status,'expected') not in ('absent','excused') and coalesce(a.coach_recorded_status,'present')<>'absent');
      update public.club_events set status='cancelled' where id=event_ids[i];
      continue;
    end if;
    target := event_ids[i];
    if target is null then
      insert into public.club_events(club_id,group_id,series_id,created_by,event_type,title,starts_at,ends_at,duration_minutes,status)
        values(s.club_id,s.group_id,s.id,auth.uid(),p_series->>'event_type',nullif(btrim(p_series->>'title'),''),dates[i],dates[i]+make_interval(mins=>duration),duration,'scheduled') returning id into target;
      snap := public.manager_event_snapshot_v1(target);
      coaches := p_coach_ids; players := p_player_ids; structure := p_structure; criteria := p_criterion_ids;
      changes := p_series || jsonb_build_object('starts_at',dates[i],'ends_at',dates[i]+make_interval(mins=>duration));
    else
      snap := public.manager_event_snapshot_v1(target);
      if snap#>>'{event,status}'='cancelled' then continue; end if;
      changes := snap->'event';
      -- Keep occurrence-specific overrides. Only template-derived values follow
      -- the recurrence template; roster changes are deltas from the edited form.
      foreach item in array array['"event_type"'::jsonb,'"title"'::jsonb,'"location_text"'::jsonb,'"coach_note"'::jsonb] loop
        if changes->(item#>>'{}') is not distinct from to_jsonb(s)->(item#>>'{}') then
          changes := jsonb_set(changes,array[item#>>'{}'],coalesce(p_series->(item#>>'{}'),'null'));
        end if;
      end loop;
      start_time := (changes->>'starts_at')::timestamptz;
      end_time := (changes->>'ends_at')::timestamptz;
      if (start_time at time zone p_timezone)::time=s.time_of_day
        and extract(dow from start_time at time zone p_timezone)::int=s.weekday then
        end_time := dates[i]+coalesce(end_time-start_time,make_interval(mins=>(changes->>'duration_minutes')::int));
        start_time := dates[i];
      end if;
      if (changes->>'duration_minutes')::int=s.duration_minutes then
        changes := changes || jsonb_build_object('duration_minutes',duration);
        end_time := start_time+make_interval(mins=>duration);
      end if;
      changes := changes || jsonb_build_object('starts_at',start_time,'ends_at',end_time);
      if changes->'requires_evaluation' is not distinct from p_expected#>'{event,requires_evaluation}' then
        changes := changes || jsonb_build_object('requires_evaluation',p_series->'requires_evaluation');
      end if;
      select coalesce(array_agg(distinct x::uuid),'{}') into coaches from (
        select value x from jsonb_array_elements_text(snap->'coach_ids') where not (value in (select jsonb_array_elements_text(p_expected->'coach_ids')) and not(value::uuid=any(p_coach_ids)))
        union select x::text from unnest(p_coach_ids) x where not(x::text in (select jsonb_array_elements_text(p_expected->'coach_ids')))) q;
      select coalesce(array_agg(distinct x::uuid),'{}') into players from (
        select value x from jsonb_array_elements_text(snap->'player_ids') where not (value in (select jsonb_array_elements_text(p_expected->'player_ids')) and not(value::uuid=any(p_player_ids)))
        union select x::text from unnest(p_player_ids) x where not(x::text in (select jsonb_array_elements_text(p_expected->'player_ids')))) q;
      structure := case when snap->'structure'=p_expected->'structure' then p_structure else snap->'structure' end;
      criteria := case when snap->'criterion_ids'=p_expected->'criterion_ids' then p_criterion_ids
        else array(select jsonb_array_elements_text(snap->'criterion_ids')::uuid) end;
    end if;
    result := public.update_manager_event_occurrence_v1(target,snap,changes,coaches,players,structure,criteria);
    recipient_ids := recipient_ids || array(select jsonb_array_elements_text(result->'recipient_ids')::uuid);
  end loop;
  update public.club_event_series set event_type=p_series->>'event_type',title=nullif(btrim(p_series->>'title'),''),
    weekday=v_weekday,time_of_day=time_day,interval_weeks=weeks,start_date=start_day,end_date=end_day,duration_minutes=duration,
    location_text=nullif(btrim(p_series->>'location_text'),''),coach_note=nullif(btrim(p_series->>'coach_note'),''),is_active=active where id=s.id;
  return jsonb_build_object('ok',true,'recipient_ids',(select coalesce(jsonb_agg(distinct x),'[]') from unnest(recipient_ids) x));
end $function$

CREATE OR REPLACE FUNCTION public.update_player_golf_round_transactional(p_round_id uuid, p_start_at timestamp with time zone, p_notes text, p_competition_level text, p_rounds_18_count smallint, p_tee_name text, p_slope_rating integer, p_course_rating numeric, p_target_hole_count integer, p_holes jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare club uuid;
begin
  select om_organization_id into club from public.golf_rounds where id=p_round_id;
  if public.legal_required_direct_access(club) is not true then raise exception 'Legal validation required'; end if;
  return public.update_player_golf_round_transactional_business(p_round_id,p_start_at,p_notes,
    p_competition_level,p_rounds_18_count,p_tee_name,p_slope_rating,p_course_rating,
    p_target_hole_count,p_holes);
end $function$

CREATE OR REPLACE FUNCTION public.update_player_golf_round_transactional_business(p_round_id uuid, p_start_at timestamp with time zone, p_notes text, p_competition_level text, p_rounds_18_count smallint, p_tee_name text, p_slope_rating integer, p_course_rating numeric, p_target_hole_count integer, p_holes jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor_id uuid := auth.uid();
  v_round public.golf_rounds%rowtype;
  v_hole_count integer;
  v_distinct_hole_count integer;
  v_min_hole integer;
  v_max_hole integer;
begin
  if v_actor_id is null or p_round_id is null then
    raise exception using errcode = 'P0001', message = 'FORBIDDEN';
  end if;

  select gr.*
  into v_round
  from public.golf_rounds gr
  where gr.id = p_round_id
  for update;
  if not found then
    raise exception using errcode = 'P0001', message = 'ROUND_NOT_FOUND';
  end if;

  if v_round.user_id is distinct from v_actor_id and not exists (
    select 1
    from public.player_guardians pg
    where pg.player_id = v_round.user_id
      and pg.guardian_user_id = v_actor_id
      and coalesce(pg.can_view, true) = true
      and coalesce(pg.can_edit, false) = true
  ) then
    raise exception using errcode = 'P0001', message = 'FORBIDDEN';
  end if;

  if not exists (
    select 1 from public.club_members cm
    where cm.user_id = v_round.user_id and cm.role = 'player' and cm.is_active = true
  ) then
    raise exception using errcode = 'P0001', message = 'PLAYER_MEMBERSHIP_REQUIRED';
  end if;
  if exists (
    select 1 from public.club_members cm
    where cm.user_id = v_round.user_id
      and cm.role = 'player'
      and cm.is_active = true
      and coalesce(cm.player_consent_status, 'pending') not in ('granted', 'adult')
  ) then
    raise exception using errcode = 'P0001', message = 'PLAYER_CONSENT_REQUIRED';
  end if;
  if v_round.om_organization_id is not null and not exists (
    select 1 from public.club_members cm
    where cm.user_id = v_round.user_id
      and cm.club_id = v_round.om_organization_id
      and cm.role = 'player'
      and cm.is_active = true
  ) then
    raise exception using errcode = 'P0001', message = 'FORBIDDEN';
  end if;

  if p_start_at is null
    or p_target_hole_count is null
    or p_target_hole_count not in (9, 18)
    or jsonb_typeof(p_holes) is distinct from 'array'
  then
    raise exception using errcode = 'P0001', message = 'INVALID_ROUND_PAYLOAD';
  end if;

  select
    count(*)::integer,
    count(distinct hole_no)::integer,
    min(hole_no),
    max(hole_no)
  into v_hole_count, v_distinct_hole_count, v_min_hole, v_max_hole
  from jsonb_to_recordset(p_holes) as h(hole_no integer);

  if v_hole_count <> p_target_hole_count
    or v_distinct_hole_count <> p_target_hole_count
    or v_min_hole <> 1
    or v_max_hole <> p_target_hole_count
  then
    raise exception using errcode = 'P0001', message = 'INVALID_ROUND_PAYLOAD';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(p_holes) as h(
      hole_no integer,
      par integer,
      score integer,
      putts integer
    )
    where (h.par is not null and (h.par < 1 or h.par > 7))
      or (h.score is not null and (h.score < 0 or h.score > 30))
      or (h.putts is not null and (
        h.putts < 0
        or h.putts > 10
        or (h.score is not null and h.putts > h.score)
      ))
  ) then
    raise exception using errcode = 'P0001', message = 'INVALID_HOLE_PAYLOAD';
  end if;

  update public.golf_rounds gr
  set
    start_at = p_start_at,
    notes = nullif(trim(p_notes), ''),
    om_competition_level = p_competition_level,
    om_rounds_18_count = p_rounds_18_count,
    tee_name = nullif(trim(p_tee_name), ''),
    slope_rating = p_slope_rating,
    course_rating = p_course_rating
  where gr.id = p_round_id;

  delete from public.golf_round_holes gh
  where gh.round_id = p_round_id
    and gh.hole_no > p_target_hole_count;

  insert into public.golf_round_holes (
    round_id,
    hole_no,
    par,
    stroke_index,
    score,
    putts,
    fairway_hit,
    note
  )
  select
    p_round_id,
    h.hole_no,
    h.par,
    h.stroke_index,
    h.score,
    h.putts,
    h.fairway_hit,
    nullif(trim(h.note), '')
  from jsonb_to_recordset(p_holes) as h(
    hole_no integer,
    par integer,
    stroke_index integer,
    score integer,
    putts integer,
    fairway_hit boolean,
    note text
  )
  on conflict (round_id, hole_no) do update set
    par = excluded.par,
    stroke_index = excluded.stroke_index,
    score = excluded.score,
    putts = excluded.putts,
    fairway_hit = excluded.fairway_hit,
    note = excluded.note;

  perform public.om_recompute_round(p_round_id);

  return jsonb_build_object(
    'ok', true,
    'round_id', p_round_id,
    'hole_count', p_target_hole_count
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_coach_training_private_notes(p_event_id uuid, p_coach_id uuid, p_report_version integer, p_proposals jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_event public.club_events%rowtype;
  v_debrief public.coach_training_debriefs%rowtype;
  v_item jsonb;
  v_player_id uuid;
  v_body text;
  v_source_text text;
  v_inserted integer := 0;
  v_row_count integer := 0;
begin
  if not public.can_manage_coach_event(p_event_id, p_coach_id) then raise exception 'forbidden'; end if;

  select * into v_event from public.club_events where id = p_event_id;
  select * into v_debrief from public.coach_training_debriefs where event_id = p_event_id;

  if v_event.id is null then raise exception 'event_not_found'; end if;
  if v_event.event_type <> 'training' then raise exception 'training_only'; end if;
  if not public.is_coach_training_assistance_enabled(v_event.club_id) then
    raise exception 'coach_training_assistance_disabled';
  end if;
  if v_debrief.id is null then raise exception 'report_required'; end if;
  if p_report_version is null or p_report_version <> v_debrief.report_version then
    raise exception 'stale_report_analysis';
  end if;
  if jsonb_typeof(coalesce(p_proposals, '[]'::jsonb)) <> 'array'
     or jsonb_array_length(coalesce(p_proposals, '[]'::jsonb)) > 50 then
    raise exception 'invalid_proposals';
  end if;

  for v_item in select value from jsonb_array_elements(coalesce(p_proposals, '[]'::jsonb))
  loop
    v_player_id := (v_item ->> 'player_id')::uuid;
    v_body := btrim(coalesce(v_item ->> 'text', ''));
    v_source_text := case
      when v_debrief.report_scope = 'individual'
        then btrim(coalesce(v_debrief.individual_comments ->> v_player_id::text, ''))
      else btrim(coalesce(v_debrief.report_text, ''))
    end;

    if char_length(v_body) not between 1 and 4000 then raise exception 'invalid_note'; end if;
    if v_source_text = '' then raise exception 'report_required'; end if;
    if not exists (
      select 1
      from public.club_event_attendees attendee
      where attendee.event_id = p_event_id
        and attendee.player_id = v_player_id
        and attendee.coach_recorded_status = 'present'
    ) then
      raise exception 'note_player_must_be_present';
    end if;

    insert into public.coach_player_private_notes (
      event_id, debrief_id, organization_id, player_id, author_coach_id,
      body, source, source_report_version, source_report_text, validated_at
    ) values (
      p_event_id, v_debrief.id, v_event.club_id, v_player_id, p_coach_id,
      v_body, 'ai_suggested', v_debrief.report_version, v_source_text, now()
    )
    on conflict do nothing;
    get diagnostics v_row_count = row_count;
    v_inserted := v_inserted + v_row_count;
  end loop;

  return v_inserted;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_custom_evaluation_response()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_link public.club_event_evaluation_criteria%rowtype;
  v_format text;
  v_valid boolean;
begin
  select * into v_link from public.club_event_evaluation_criteria where id = new.event_criterion_id;
  if v_link.id is null or v_link.event_id <> new.event_id then raise exception 'Invalid activity criterion'; end if;
  if new.respondent_role = 'coach' and v_link.snapshot_respondent not in ('coach', 'both') then raise exception 'Criterion is not for coaches'; end if;
  if new.respondent_role = 'player' and v_link.snapshot_respondent not in ('player', 'both') then raise exception 'Criterion is not for players'; end if;
  if new.respondent_role = 'player' and new.respondent_user_id <> new.player_id then raise exception 'Player response owner mismatch'; end if;
  new.club_id := v_link.club_id;
  v_format := v_link.snapshot_response_format;
  if v_format = 'short_text' then
    v_valid := jsonb_typeof(new.value_json) = 'string' and char_length(btrim(new.value_json #>> '{}')) between 1 and 240;
  else
    select exists (
      select 1 from jsonb_array_elements(v_link.snapshot_choices) choice
      where choice->'value' = new.value_json
    ) into v_valid;
  end if;
  if not v_valid then raise exception 'Invalid structured response value' using errcode = '23514'; end if;
  new.updated_at := now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_player_document_event_link()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.club_event_id is null then
    return new;
  end if;

  if not exists (
    select 1
    from public.club_events event
    join public.club_event_attendees attendee
      on attendee.event_id = event.id
     and attendee.player_id = new.player_id
    where event.id = new.club_event_id
      and event.club_id = new.organization_id
  ) then
    raise exception 'Invalid Player document event association'
      using errcode = '23514';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.write_manager_om_v1_business(p_request_id uuid, p_club_id uuid, p_kind text, p_action text, p_id uuid, p_expected text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 c public.om_internal_contests%rowtype; tour public.om_exceptional_tournaments%rowtype;
 req public.manager_om_write_requests%rowtype; body jsonb; v_result jsonb; v_version text; v_id uuid; v_group uuid;
 v_title text; v_start date; v_end date; rankings jsonb; item jsonb; v_player uuid; v_rank int; v_points numeric; v_saved int; v_bonus int;
begin
 perform public.require_manager_club_scope_v1(auth.uid(),p_club_id);
 if p_request_id is null or jsonb_typeof(p_payload) is distinct from 'object' or p_kind is null or p_kind not in ('contest','tournament')
  or p_action is null or p_action not in ('create','delete','toggle','publish') then raise exception 'invalid_request'; end if;
 body:=jsonb_build_object('club',p_club_id,'kind',p_kind,'action',p_action,'id',p_id,'expected',p_expected,'payload',p_payload);
 insert into public.manager_om_write_requests(actor_id,request_id,payload) values(auth.uid(),p_request_id,body) on conflict do nothing;
 select * into req from public.manager_om_write_requests where actor_id=auth.uid() and request_id=p_request_id for update;
 if req.payload is distinct from body then raise exception 'request_conflict'; end if;
 if req.result is not null then return req.result||jsonb_build_object('replayed',true); end if;
 if p_action='create' then
  if p_id is not null then raise exception 'invalid_request'; end if;
  v_title:=nullif(btrim(p_payload->>'name'),'');
  if v_title is null or length(v_title)>500 or length(coalesce(p_payload->>'description',''))>10000 then raise exception 'invalid_fields'; end if;
  if p_kind='contest' then
   v_start:=(p_payload->>'date')::date; v_group:=nullif(p_payload->>'group_id','')::uuid;
   if v_start is null then raise exception 'invalid_dates'; end if;
   if v_group is not null then
    perform 1 from public.coach_groups g where g.id=v_group and g.club_id=p_club_id and g.is_active is distinct from false and g.club_season_id is not null and coalesce(g.name,'') !~ '^(__ARCHIVE_|__EVENT_SPECIFIQUE__)' and coalesce(g.name,'')<>'Groupe spécifique' for share;
    if not found then raise exception 'invalid_group'; end if;
   end if;
   insert into public.om_internal_contests(organization_id,group_id,title,description,contest_date,created_by)
    values(p_club_id,v_group,v_title,nullif(btrim(p_payload->>'description'),''),v_start,auth.uid()) returning id into v_id;
  else
   v_start:=nullif(p_payload->>'starts_on','')::date; v_end:=nullif(p_payload->>'ends_on','')::date;
   if v_start is not null and v_end is not null and v_end<v_start then raise exception 'invalid_dates'; end if;
   insert into public.om_exceptional_tournaments(organization_id,name,description,starts_on,ends_on,is_active,created_by)
    values(p_club_id,v_title,nullif(btrim(p_payload->>'description'),''),v_start,v_end,true,auth.uid()) returning id into v_id;
  end if;
 else
  v_id:=p_id;
  if p_kind='contest' then
   select * into c from public.om_internal_contests where id=p_id for update;
   if c.id is null then raise exception 'contest_not_found'; end if;
   if c.organization_id is distinct from p_club_id then raise exception 'forbidden'; end if;
   perform 1 from public.om_internal_contest_results where contest_id=p_id for update;
   perform 1 from public.om_bonus_entries where source_table='om_internal_contests' and source_id=p_id and bonus_type='internal_contest_podium' for update;
   v_version:=public.manager_om_contest_version_v1(p_id);
  else
   select * into tour from public.om_exceptional_tournaments where id=p_id for update;
   if tour.id is null then raise exception 'tournament_not_found'; end if;
   if tour.organization_id is distinct from p_club_id then raise exception 'forbidden'; end if;
   v_version:=md5(to_jsonb(tour)::text);
  end if;
  if p_expected is null or p_expected is distinct from v_version then raise exception 'om_conflict'; end if;
  if p_action='delete' then
   if p_kind='contest' then
    delete from public.om_bonus_entries where source_table='om_internal_contests' and source_id=p_id and bonus_type='internal_contest_podium';
    delete from public.om_internal_contests where id=p_id;
   else
    -- A referenced tournament is deactivated instead: deleting it must not rewrite played rounds.
    if exists(select 1 from public.golf_rounds where om_exceptional_tournament_id=p_id) then raise exception 'tournament_in_use'; end if;
    delete from public.om_exceptional_tournaments where id=p_id;
   end if;
  elsif p_action='toggle' and p_kind='tournament' then
   if jsonb_typeof(p_payload->'is_active') is distinct from 'boolean' then raise exception 'invalid_fields'; end if;
   update public.om_exceptional_tournaments set is_active=(p_payload->>'is_active')::boolean where id=p_id;
  elsif p_action='publish' and p_kind='contest' then
   rankings:=p_payload->'rankings';
   if jsonb_typeof(rankings) is distinct from 'array' or jsonb_array_length(rankings)>2000 then raise exception 'invalid_rankings'; end if;
   if jsonb_array_length(rankings)=0 and exists(select 1 from public.om_internal_contest_results where contest_id=p_id)
    and not coalesce((p_payload->>'allow_empty')::boolean,false) then raise exception 'empty_confirmation_required'; end if;
   if exists(select 1 from jsonb_array_elements(rankings) x group by x->>'player_id' having count(*)>1) then raise exception 'duplicate_player'; end if;
   for item in select * from jsonb_array_elements(rankings) loop
    v_player:=(item->>'player_id')::uuid;
    if v_player is null or (item->>'rank') is null or (item->>'rank') !~ '^[0-9]+$' or (item->>'rank')::numeric not between 1 and 10000 or length(coalesce(item->>'note',''))>10000 then raise exception 'invalid_rankings'; end if;
    if not exists(select 1 from public.om_internal_contest_results where contest_id=p_id and player_id=v_player) then
     perform 1 from public.club_members where club_id=p_club_id and user_id=v_player and role='player' and is_active for share;
     if not found then raise exception 'invalid_player'; end if;
     if c.group_id is not null then
      perform 1 from public.coach_groups g join public.coach_group_players gp on gp.group_id=g.id where g.id=c.group_id and g.club_id=p_club_id and gp.player_user_id=v_player for share of g,gp;
      if not found then raise exception 'invalid_player'; end if;
     end if;
    end if;
   end loop;
   delete from public.om_internal_contest_results r where r.contest_id=p_id and not exists(select 1 from jsonb_array_elements(rankings) x where (x->>'player_id')::uuid=r.player_id);
   for item in select * from jsonb_array_elements(rankings) loop
    v_player:=(item->>'player_id')::uuid;v_rank:=(item->>'rank')::int;v_points:=case v_rank when 1 then 15 when 2 then 10 when 3 then 5 else 0 end;
    insert into public.om_internal_contest_results(contest_id,player_id,rank,points_net,points_brut,note)
     values(p_id,v_player,v_rank,v_points,v_points,nullif(btrim(item->>'note'),''))
     on conflict(contest_id,player_id) do update set rank=excluded.rank,points_net=excluded.points_net,points_brut=excluded.points_brut,note=excluded.note;
   end loop;
   -- Drop only obsolete/duplicate generated podium entries. Keep IDs for unchanged participants.
   delete from public.om_bonus_entries b where b.source_table='om_internal_contests' and b.source_id=p_id and b.bonus_type='internal_contest_podium' and (
    b.organization_id<>p_club_id or not exists(select 1 from public.om_internal_contest_results r where r.contest_id=p_id and r.player_id=b.player_id and r.rank<=3)
    or exists(select 1 from public.om_bonus_entries older where older.source_table=b.source_table and older.source_id=b.source_id and older.bonus_type=b.bonus_type and older.player_id=b.player_id and older.organization_id=p_club_id and (older.created_at,older.id)<(b.created_at,b.id)));
   for item in select * from jsonb_array_elements(rankings) loop
    v_player:=(item->>'player_id')::uuid;v_rank:=(item->>'rank')::int;
    if v_rank>3 then continue; end if;
    v_points:=case v_rank when 1 then 15 when 2 then 10 else 5 end;
    update public.om_bonus_entries set points_net=v_points,points_brut=v_points,occurred_on=c.contest_date
     where source_table='om_internal_contests' and source_id=p_id and bonus_type='internal_contest_podium' and player_id=v_player and organization_id=p_club_id;
    if not found then
     insert into public.om_bonus_entries(organization_id,player_id,bonus_type,points_net,points_brut,source_table,source_id,description,occurred_on,created_by)
      values(p_club_id,v_player,'internal_contest_podium',v_points,v_points,'om_internal_contests',p_id,'Internal contest podium',c.contest_date,auth.uid());
    end if;
   end loop;
   update public.om_internal_contests set full_ranking=coalesce((select jsonb_agg(jsonb_build_object('rank',r.rank,'player_id',r.player_id,'player_name',nullif(btrim(concat_ws(' ',p.first_name,p.last_name)),''),'note',r.note) order by r.rank,r.player_id)
    from public.om_internal_contest_results r join public.profiles p on p.id=r.player_id where r.contest_id=p_id),'[]'),updated_at=clock_timestamp() where id=p_id;
   select count(*) into v_saved from public.om_internal_contest_results where contest_id=p_id;
   select count(*) into v_bonus from public.om_bonus_entries where source_table='om_internal_contests' and source_id=p_id and bonus_type='internal_contest_podium';
  else raise exception 'invalid_action'; end if;
 end if;
 v_result:=jsonb_build_object('ok',true,'id',v_id,'action',p_action,'saved_rows',v_saved,'bonus_rows',v_bonus,'replayed',false);
 update public.manager_om_write_requests set result=v_result where actor_id=auth.uid() and request_id=p_request_id;
 return v_result;
end $function$
